package com.groupscape;

import net.runelite.api.Client;

public class AchievementDiaryState implements ConsumableState {
    private final transient String playerName;
    private static final int[] diaryVarbits = new int[]{
            /* Karamja Easy */
            3566, 3567, 3568, 3569, 3570, 3571, 3572, 3573, 3574, 3575,
            /* Karamja Medium */
            3579, 3580, 3581, 3582, 3583, 3584, 3596, 3586, 3587, 3588, 3589, 3590, 3591, 3592, 3593, 3594, 3595, 3597, 3585,
            /* Karamja Hard */
            3600, 3601, 3602, 3603, 3604, 3605, 3606, 3607, 3608, 3609
    };

    private static final int[] diaryVarps = new int[]{
            /* Ardougne */
            1196, 1197,
            /* Desert */
            1198, 1199,
            /* Falador */
            1186, 1187,
            /* Fremennik */
            1184, 1185,
            /* Kandarin */
            1178, 1179,
            /* Karamja Elite */
            1200,
            /* Kourend & Kebos */
            2085, 2086,
            /* Lumbridge & Draynor */
            1194, 1195,
            /* Morytania */
            1180, 1181,
            /* Varrock */
            1176, 1177,
            /* Western Provinces */
            1182, 1183,
            /* Wilderness */
            1192, 1193
    };

    private final int[] diaryVarValues = new int[diaryVarbits.length + diaryVarps.length];

    public AchievementDiaryState(String playerName, Client client) {
        this.playerName = playerName;

        for (int i = 0; i < diaryVarps.length; ++i) {
            diaryVarValues[i] = client.getVarpValue(diaryVarps[i]);
        }
        for (int i = 0; i < diaryVarbits.length; ++i) {
            diaryVarValues[i + diaryVarps.length] = client.getVarbitValue(diaryVarbits[i]);
        }
    }

    @Override
    public Object get() {
        return diaryVarValues;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof AchievementDiaryState)) return false;

        AchievementDiaryState other = (AchievementDiaryState) o;
        for (int i = 0; i < diaryVarValues.length; ++i) {
            if (diaryVarValues[i] != other.diaryVarValues[i]) return false;
        }

        return true;
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Prayer;

public class ActivePrayersState implements ConsumableState {
    private final List<String> activePrayers;
    private final transient String playerName;

    ActivePrayersState(String playerName, Client client) {
        this.playerName = playerName;
        List<String> raw = new ArrayList<>();
        for (Prayer prayer : Prayer.values()) {
            if (client.isPrayerActive(prayer)) {
                raw.add(prayer.name());
            }
        }
        this.activePrayers = PrayerVisibility.visible(raw);
    }

    @Override
    public Object get() {
        return activePrayers;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof ActivePrayersState)) return false;

        ActivePrayersState other = (ActivePrayersState) o;
        return other.activePrayers.equals(activePrayers);
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Low-HP and wilderness-entry alerts are discrete events like {@link ObjectInteractionEvents},
 * not per-tick snapshot data - this accumulates them into a list and drains everything buffered
 * since the last upload into the "alerts" key on the next {@code consumeState}, mirroring
 * {@link ObjectInteractionEvents}'s accumulator pattern. Must only be touched from the client thread.
 */
public class AlertEvents {
    private final List<Map<String, Object>> pending = new ArrayList<>();
    private String owner;

    private List<Map<String, Object>> consumed;
    private String consumedOwner;

    public synchronized void onLowHp(String playerName, int currentHp, int maxHp, int worldX, int worldY, int plane, int world) {
        owner = playerName;
        Map<String, Object> event = new HashMap<>();
        event.put("type", "low_hp");
        event.put("currentHp", currentHp);
        event.put("maxHp", maxHp);
        event.put("worldX", worldX);
        event.put("worldY", worldY);
        event.put("plane", plane);
        event.put("world", world);
        pending.add(event);
    }

    public synchronized void onWildernessEntry(String playerName, int wildernessLevel, int worldX, int worldY, int plane, int world) {
        owner = playerName;
        Map<String, Object> event = new HashMap<>();
        event.put("type", "wilderness_entry");
        event.put("wildernessLevel", wildernessLevel);
        event.put("worldX", worldX);
        event.put("worldY", worldY);
        event.put("plane", plane);
        event.put("world", world);
        pending.add(event);
    }

    public synchronized void consumeState(Map<String, Object> output) {
        if (pending.isEmpty()) return;

        String whoIsUpdating = (String) output.get("name");
        if (owner != null && owner.equals(whoIsUpdating)) {
            output.put("alerts", new ArrayList<>(pending));
        }

        consumed = new ArrayList<>(pending);
        consumedOwner = owner;
        pending.clear();
        owner = null;
    }

    public synchronized void restoreState() {
        if (consumed == null) return;

        pending.addAll(0, consumed);
        if (owner == null) {
            owner = consumedOwner;
        }
        consumed = null;
        consumedOwner = null;
    }
}

package com.groupscape;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Fire-and-forget push of the account's read cursor to
 * {@code POST /api/characters/{accountHash}/mark-chat-read} - see the "!gs" chat spec §6 (distinct
 * from the delivery cursor {@code ChatBackfillClient} backfills against). Mirrors {@link
 * ChatSendManager}'s send pattern: own daemon executor, never blocking the caller (the sidepanel's
 * Swing refresh timer, which decides *when* to call this based on the visible+focused rule - see
 * {@code GroupScapePanel}).
 */
@Slf4j
@Singleton
public class ChatMarkReadManager {
    private final Client client;
    private final HttpRequestService httpRequestService;
    private final ExecutorService markReadExecutor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "groupscape-chat-mark-read");
        t.setDaemon(true);
        return t;
    });
    private volatile long lastSyncedMessageId = 0;

    @Inject
    public ChatMarkReadManager(Client client, HttpRequestService httpRequestService) {
        this.client = client;
        this.httpRequestService = httpRequestService;
    }

    private static class MarkChatReadRequestBody {
        long messageId;
    }

    /** No-op when {@code messageId} isn't newer than what this session already synced - the panel
     * calls this on every refresh tick while the chat tab is visible and focused, so most calls
     * would otherwise be redundant round-trips. */
    public void markRead(long messageId, GroupScapeTrackerConfig config) {
        if (messageId <= lastSyncedMessageId) return;
        String apiKey = config.apiKey().trim();
        long accountHashValue = client.getAccountHash();
        if (apiKey.isEmpty() || accountHashValue == -1) return;

        lastSyncedMessageId = messageId;
        MarkChatReadRequestBody body = new MarkChatReadRequestBody();
        body.messageId = messageId;

        String url = httpRequestService.getBaseUrl() + "/api/characters/" + accountHashValue + "/mark-chat-read";
        markReadExecutor.submit(() -> {
            HttpRequestService.HttpResponse response = httpRequestService.post(url, apiKey, body);
            if (!response.isSuccessful()) {
                log.debug("mark-chat-read failed: {} {}", response.getCode(), response.getBody());
            }
        });
    }

    public void shutdown() {
        markReadExecutor.shutdownNow();
    }
}

package com.groupscape;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Fire-and-forget relay of a captured {@code !gs} chat line to
 * {@code POST /api/characters/{accountHash}/send-chat-message} - see the "!gs" group chat spec,
 * §1 (client-side capture/suppression) and §3 (wire protocol). Mirrors {@link
 * com.groupscape.roster.PingManager}'s send pattern: never called from the client thread's
 * blocking path, so the HTTP round-trip runs on its own daemon executor instead.
 */
@Slf4j
@Singleton
public class ChatSendManager {
    private static final int CHAT_MESSAGE_MAX_LEN = 150;

    private final Client client;
    private final HttpRequestService httpRequestService;
    private final ExecutorService sendExecutor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "groupscape-chat-send");
        t.setDaemon(true);
        return t;
    });

    @Inject
    public ChatSendManager(Client client, HttpRequestService httpRequestService) {
        this.client = client;
        this.httpRequestService = httpRequestService;
    }

    private static class SendChatMessageRequestBody {
        String text;
    }

    /** Truncates silently to {@code CHAT_MESSAGE_MAX_LEN} (see the "Message formatting and length
     * limits" spec ticket §8) before sending - the server truncates too, but callers like {@link
     * ChatSuppressionSubscriber}'s in-game {@code !gs} capture never pass through the side panel's
     * input field, so this is the only client-side enforcement point that covers every caller. */
    public void send(String text, GroupScapeTrackerConfig config) {
        String apiKey = config.apiKey().trim();
        long accountHashValue = client.getAccountHash();
        if (apiKey.isEmpty() || accountHashValue == -1) {
            log.debug("Chat: not sending - apiKey empty={}, accountHash={}", apiKey.isEmpty(), accountHashValue);
            return;
        }

        SendChatMessageRequestBody body = new SendChatMessageRequestBody();
        body.text = text.length() > CHAT_MESSAGE_MAX_LEN ? text.substring(0, CHAT_MESSAGE_MAX_LEN) : text;

        String url = httpRequestService.getBaseUrl() + "/api/characters/" + accountHashValue + "/send-chat-message";
        sendExecutor.submit(() -> {
            HttpRequestService.HttpResponse response = httpRequestService.post(url, apiKey, body);
            if (!response.isSuccessful()) {
                log.debug("chat send failed: {} {}", response.getCode(), response.getBody());
            } else {
                log.debug("chat send ok");
            }
        });
    }

    public void shutdown() {
        sendExecutor.shutdownNow();
    }
}

package com.groupscape;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ChatboxInput;

/**
 * Captures {@code !gs}-prefixed chat, from any chat type/tab, before it reaches the OSRS server
 * and reroutes it to GroupScape instead - see the group chat spec, §1 (client-side capture and
 * suppression). Subscribes to {@link ChatboxInput}, RuneLite's pre-send hook (the same one {@code
 * ChatCommandManager} uses for {@code !kc}/{@code !pb}), rather than {@code ChatMessage} (which
 * only fires after the message has already gone out).
 *
 * <p>Suppression is client-side only, by design (see the spec's "Non-plugin !gs leak handling"
 * ticket) - a group member without the plugin, or with {@link GroupScapeTrackerConfig#chatEnabled()}
 * off, still leaks the literal {@code !gs ...} text into real OSRS chat. No detection/mitigation
 * for that is in scope.
 */
@Slf4j
@Singleton
public class ChatSuppressionSubscriber {
    private static final String COMMAND_PREFIX = "!gs";

    @Inject
    private EventBus eventBus;

    @Inject
    private GroupScapeTrackerConfig config;

    @Inject
    private ChatSendManager chatSendManager;

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onChatboxInput(ChatboxInput event) {
        if (!config.chatEnabled()) {
            log.debug("!gs: chatEnabled is off, skipping");
            return;
        }

        String value = event.getValue();
        if (value == null || !isGsCommand(value)) return;

        // Captured regardless of chat type/tab (Public, Clan, Private, Trade, All, ...) - a
        // !gs-prefixed line always reroutes to GroupScape and never sends as real chat, no matter
        // which channel it was typed into.
        event.consume();

        String text = value.substring(COMMAND_PREFIX.length()).trim();
        if (text.isEmpty()) return;

        chatSendManager.send(text, config);
    }

    private static boolean isGsCommand(String value) {
        if (!value.regionMatches(true, 0, COMMAND_PREFIX, 0, COMMAND_PREFIX.length())) return false;
        // Reject "!gsomething" - the prefix must be the whole token, followed by whitespace or EOL.
        return value.length() == COMMAND_PREFIX.length()
                || Character.isWhitespace(value.charAt(COMMAND_PREFIX.length()));
    }
}

package com.groupscape;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Curated allowlist of chest/instance reward source names, matched against
 * {@code LootReceived.getName()} when {@code getType() == LootRecordType.EVENT} - these are
 * never correlated to an NPC kill (there's often no {@code NpcDespawned} to hook at all, e.g.
 * raids), unlike the {@code NpcDespawned}-based kill-detection in
 * {@link com.groupscape.GroupScapeTrackerPlugin#onNpcDespawned}.
 *
 * Doesn't include the raid chests ({@code RAID_CHEST_NAMES} in
 * {@link com.groupscape.GroupScapeTrackerPlugin}) or the combo chests ({@link ComboKillEvents}) -
 * both are checked ahead of this class in {@code onLootReceived} and claimed by their own
 * dedicated handling instead.
 *
 * Kept in sync with the server's chest-loot allowlist (server/src/loot_sources.rs).
 */
public final class ChestLootSourceNames {
    private ChestLootSourceNames() {
    }

    private static final Set<String> NAMES = new HashSet<>(Arrays.asList(
            "Chambers of Xeric",
            "Theatre of Blood",
            "Tombs of Amascut",
            "The Gauntlet",
            "The Corrupted Gauntlet",
            "Wintertodt",
            "Tempoross",
            "Zalcano",
            "Guardians of the Rift",
            "Fortis Colosseum",
            "Hunters' loot sack (basic)",
            "Hunters' loot sack (adept)",
            "Hunters' loot sack (expert)",
            "Hunters' loot sack (master)"
    ));

    public static boolean isTrackedChest(String sourceName) {
        return sourceName != null && NAMES.contains(sourceName);
    }
}

package com.groupscape;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Extracts a clue scroll's tier from RuneLite's {@code LootReceived.getName()} for a clue
 * casket reward (e.g. "Clue Scroll (Elite)"), which arrives as {@code LootRecordType.EVENT}
 * like any other chest source - there's no dedicated clue event type in the RuneLite API.
 */
public final class ClueTier {
    private ClueTier() {
    }

    private static final Pattern CLUE_PATTERN = Pattern.compile("^Clue Scroll \\((\\w+)\\)$");

    /**
     * @return the tier lowercased ("beginner".."master"), or {@code null} if {@code eventName}
     * isn't a clue casket reward.
     */
    public static String extractTier(String eventName) {
        if (eventName == null) {
            return null;
        }
        Matcher matcher = CLUE_PATTERN.matcher(eventName);
        return matcher.matches() ? matcher.group(1).toLowerCase() : null;
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class CollectionLogV2Manager {
    // item id -> quantity, resolved via the live drop-detection path (chat message + inventory/
    // loot match) - these are genuine "this just happened" unlocks and go out under
    // collection_log_v2, which the server treats as notify-worthy.
    private final Map<Integer, Integer> liveItems = new HashMap<>();
    // item id -> quantity, seen only via a collection log widget scan with no matching live
    // signal (e.g. the player just opened their log to browse) - these go out under
    // collection_log_sync, which the server merges into stored state without firing Discord/
    // activity-feed events, since they aren't drops happening now.
    private final Map<Integer, Integer> syncItems = new HashMap<>();
    // item ids registered via the live path since the last clear - lets a scan that follows a
    // live drop (to learn the true stackable quantity) correct liveItems instead of being
    // mistaken for a plain sync hit.
    private final java.util.Set<Integer> confirmedLiveIds = new java.util.HashSet<>();

    public synchronized void storeLiveClogItem(int itemId, int quantity) {
        if (quantity <= 0) return;
        liveItems.put(itemId, quantity);
        confirmedLiveIds.add(itemId);
    }

    public synchronized void storeScannedClogItem(int itemId, int quantity) {
        if (quantity <= 0) return;
        if (confirmedLiveIds.contains(itemId)) {
            liveItems.put(itemId, quantity);
        } else {
            syncItems.put(itemId, quantity);
        }
    }

    public synchronized void consumeClogItems(Map<String, Object> updates) {
        if (!liveItems.isEmpty()) {
            updates.put("collection_log_v2", flatten(liveItems));
        }
        if (!syncItems.isEmpty()) {
            updates.put("collection_log_sync", flatten(syncItems));
        }
    }

    private static List<Integer> flatten(Map<Integer, Integer> items) {
        List<Integer> result = new ArrayList<>(items.size() * 2);
        for (Map.Entry<Integer, Integer> item : items.entrySet()) {
            result.add(item.getKey());
            result.add(item.getValue());
        }
        return result;
    }

    public synchronized void clearClogItems() {
        liveItems.clear();
        syncItems.clear();
        confirmedLiveIds.clear();
    }

    @Subscribe
    public synchronized void onGameStateChanged(GameStateChanged ev) {
        if (ev.getGameState() != GameState.LOGGED_IN) {
            clearClogItems();
        }
    }
}

package com.groupscape;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class CollectionLogWidgetSubscriber {
    /** Fires the moment a new item is unlocked, whether or not the log UI is open - this is
     * what lets collection log sync happen at drop time instead of only on next log open. */
    private static final Pattern NEW_CLOG_ITEM_PATTERN =
            Pattern.compile("^New item added to your collection log: (?<item>.+)$");

    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private CollectionLogV2Manager collectionLogV2Manager;

    private boolean searchTriggered = false;
    private int searchTriggeredTick = -1;

    // itemManager.search() only matches items with a GE price, so it silently misses a large
    // share of collection log items (untradeable, or the search cache just hasn't loaded yet).
    // Instead, resolve the item id from the player's own inventory: snapshot it the moment the
    // unlock chat message fires, then diff it against the inventory a tick later (once the item
    // has actually landed) and match the newly-added item's real name (read straight from the
    // local item cache, not a name search) against the chat message's item name. This is the
    // same approach the reference collection-log RuneLite plugin uses and works for every item
    // regardless of GE tradeability.
    //
    // The inventory-diff alone races against event ordering: for some drops (e.g. boss uniques)
    // the item lands in the inventory the same tick the unlock message is queued, and RuneLite
    // can dispatch ItemContainerChanged before ChatMessage - the diff then sees no change to
    // match against. LootReceived is a second, independent source for the same item (the raw
    // loot the kill granted) that isn't subject to that same ordering, so it's kept as a
    // fallback resolver rather than clearing pendingItemName on a failed diff.
    private String pendingItemName;
    private Map<Integer, Integer> inventorySnapshot;
    private int pendingItemTick = -1;

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged e) {
        GameState s = e.getGameState();
        if (s != GameState.HOPPING && s != GameState.LOGGED_IN) {
            searchTriggered = false;
            searchTriggeredTick = -1;
            pendingItemName = null;
            inventorySnapshot = null;
            pendingItemTick = -1;
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        if (searchTriggeredTick != -1) {
            int currentTick = client.getTickCount();

            if (currentTick - searchTriggeredTick >= 500) {
                searchTriggered = false;
                searchTriggeredTick = -1;
            }
        }

        // Neither the inventory diff nor LootReceived resolved the pending item within a few
        // ticks - give up and fall back to the next manual/widget-triggered collection log scan
        // (onScriptPreFired below) rather than letting a stale name linger and get matched
        // against an unrelated later drop.
        if (pendingItemTick != -1 && client.getTickCount() - pendingItemTick >= 5) {
            log.warn("timed out resolving collection log item id for name '{}'", pendingItemName);
            pendingItemName = null;
            inventorySnapshot = null;
            pendingItemTick = -1;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) return;

        String message = Text.removeTags(event.getMessage());
        Matcher m = NEW_CLOG_ITEM_PATTERN.matcher(message);
        if (!m.find()) return;

        pendingItemName = m.group("item").trim();
        inventorySnapshot = snapshotInventory();
        pendingItemTick = client.getTickCount();
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (pendingItemName == null) return;
        if (event.getContainerId() != InventoryID.INV) return;

        Map<Integer, Integer> before = inventorySnapshot != null ? inventorySnapshot : new HashMap<>();
        Map<Integer, Integer> after = snapshotInventory();

        int resolvedItemId = -1;
        for (Map.Entry<Integer, Integer> entry : after.entrySet()) {
            int itemId = entry.getKey();
            int gained = entry.getValue() - before.getOrDefault(itemId, 0);
            if (gained <= 0) continue;

            ItemComposition composition = itemManager.getItemComposition(itemId);
            if (composition.getName().equalsIgnoreCase(pendingItemName)) {
                resolvedItemId = itemId;
                break;
            }
        }

        if (resolvedItemId == -1) {
            // No match yet - some rewards (e.g. clue caskets) route through a different
            // container before landing in the inventory, or this ItemContainerChanged simply
            // fired before the item actually landed. Leave pendingItemName set so
            // onLootReceived (or a later ItemContainerChanged) still gets a chance to resolve
            // it; onGameTick above expires it if nothing ever does.
            return;
        }

        // Real quantity (for stackable log entries) is only known once the log widget is
        // scanned; this just registers the unlock immediately so it isn't lost until the
        // player next opens the log. onScriptPreFired below overwrites it with the true count,
        // while keeping it flagged as a live drop rather than a plain sync hit.
        collectionLogV2Manager.storeLiveClogItem(resolvedItemId, 1);
        pendingItemName = null;
        inventorySnapshot = null;
        pendingItemTick = -1;
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        if (pendingItemName == null) return;

        for (ItemStack item : event.getItems()) {
            ItemComposition composition = itemManager.getItemComposition(item.getId());
            if (!composition.getName().equalsIgnoreCase(pendingItemName)) continue;

            collectionLogV2Manager.storeLiveClogItem(item.getId(), 1);
            pendingItemName = null;
            inventorySnapshot = null;
            pendingItemTick = -1;
            return;
        }
    }

    private Map<Integer, Integer> snapshotInventory() {
        Map<Integer, Integer> snapshot = new HashMap<>();
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) return snapshot;

        for (Item item : inventory.getItems()) {
            if (item.getId() == -1) continue;
            snapshot.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        return snapshot;
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired pre) {
        // Script 4100 fires when collection log items are enumerated via search - this covers
        // both the drop-triggered scan above (confirming a live item's true count) and a plain
        // manual open/browse of the log, which enumerates the player's whole log regardless of
        // whether anything is actually new. storeScannedClogItem tells those two apart by
        // checking confirmedLiveIds, so a manual check-in doesn't get reported as a fresh drop.
        if (pre.getScriptId() == 4100) {
            // Arguments: [widgetId, itemId, qty]
            Object[] args = pre.getScriptEvent().getArguments();
            if (args != null && args.length >= 3) {
                try {
                    int itemId = (int) args[1];
                    int quantity = (int) args[2];
                    collectionLogV2Manager.storeScannedClogItem(itemId, quantity);
                } catch (Exception ignored) {
                    //
                }
            }
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired post) {
        final int COLLECTION_LOG_SETUP = 7797;
        if (post.getScriptId() == COLLECTION_LOG_SETUP) {
            if (searchTriggered) return;
            boolean isAdventureLog = client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
            if (isAdventureLog) return;

            searchTriggered = true;
            searchTriggeredTick = client.getTickCount();
            client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
            final int COLLECTION_INIT = 2240;
            client.runScript(COLLECTION_INIT);
        }
    }
}

package com.groupscape;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CollectionPageState implements ConsumableState {
    private final ItemContainerState items;
    private final String pageName;
    private final int tabIdx;
    private final List<Integer> completionCounts;

    public CollectionPageState(int tabIdx, String pageName, ItemContainerState items, List<Integer> completionCounts) {
        this.tabIdx = tabIdx;
        this.pageName = pageName;
        this.items = items;
        this.completionCounts = completionCounts;
    }

    @Override
    public Object get() {
        Map<String, Object> result = new HashMap<>();
        result.put("tab", tabIdx);
        result.put("page_name", pageName);
        result.put("items", items.get());
        result.put("completion_counts", completionCounts);
        return result;
    }

    @Override
    public String whoOwnsThis() { return items.whoOwnsThis(); }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof CollectionPageState)) return false;
        CollectionPageState other = (CollectionPageState) o;
        boolean completionCountsEqual = completionCounts.size() == other.completionCounts.size();
        if (completionCountsEqual) {
            for (int i = 0; i < completionCounts.size(); ++i) {
                completionCountsEqual = completionCounts.get(i).equals(other.completionCounts.get(i));
                if (!completionCountsEqual) break;
            }
        }

        return (completionCountsEqual && tabIdx == other.tabIdx && pageName.equals(other.pageName) && items.equals(other.items));
    }
}

package com.groupscape;

import net.runelite.api.Client;
import net.runelite.api.Varbits;
import net.runelite.api.gameval.VarPlayerID;

import java.util.HashMap;
import java.util.Map;

/**
 * Tier completion is a per-tier varbit (set once every task in the tier is done and the
 * reward claimed); per-task completion is a packed bitset spread across 21 varps
 * (net.runelite.api.gameval.VarPlayerID#CA_TASK_COMPLETED_0..20, 32 bits each, task id =
 * varp index * 32 + bit index). Both are read passively off client state - no CA log needs
 * to be open.
 */
public class CombatAchievementState implements ConsumableState {
    static final int[] CA_TASK_COMPLETED_VARPS = {
            VarPlayerID.CA_TASK_COMPLETED_0,
            VarPlayerID.CA_TASK_COMPLETED_1,
            VarPlayerID.CA_TASK_COMPLETED_2,
            VarPlayerID.CA_TASK_COMPLETED_3,
            VarPlayerID.CA_TASK_COMPLETED_4,
            VarPlayerID.CA_TASK_COMPLETED_5,
            VarPlayerID.CA_TASK_COMPLETED_6,
            VarPlayerID.CA_TASK_COMPLETED_7,
            VarPlayerID.CA_TASK_COMPLETED_8,
            VarPlayerID.CA_TASK_COMPLETED_9,
            VarPlayerID.CA_TASK_COMPLETED_10,
            VarPlayerID.CA_TASK_COMPLETED_11,
            VarPlayerID.CA_TASK_COMPLETED_12,
            VarPlayerID.CA_TASK_COMPLETED_13,
            VarPlayerID.CA_TASK_COMPLETED_14,
            VarPlayerID.CA_TASK_COMPLETED_15,
            VarPlayerID.CA_TASK_COMPLETED_16,
            VarPlayerID.CA_TASK_COMPLETED_17,
            VarPlayerID.CA_TASK_COMPLETED_18,
            VarPlayerID.CA_TASK_COMPLETED_19,
            VarPlayerID.CA_TASK_COMPLETED_20,
    };

    private final transient String playerName;
    private final Map<String, Boolean> tiers;
    private final int[] taskVarpValues = new int[CA_TASK_COMPLETED_VARPS.length];

    public CombatAchievementState(String playerName, Client client) {
        this.playerName = playerName;

        tiers = new HashMap<>();
        tiers.put("easy", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_EASY) != 0);
        tiers.put("medium", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_MEDIUM) != 0);
        tiers.put("hard", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_HARD) != 0);
        tiers.put("elite", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_ELITE) != 0);
        tiers.put("master", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_MASTER) != 0);
        tiers.put("grandmaster", client.getVarbitValue(Varbits.COMBAT_ACHIEVEMENT_TIER_GRANDMASTER) != 0);

        for (int i = 0; i < CA_TASK_COMPLETED_VARPS.length; ++i) {
            taskVarpValues[i] = client.getVarpValue(CA_TASK_COMPLETED_VARPS[i]);
        }
    }

    @Override
    public Object get() {
        Map<String, Object> out = new HashMap<>();
        out.put("tiers", tiers);

        Map<String, Boolean> tasks = new HashMap<>();
        for (int varpIndex = 0; varpIndex < taskVarpValues.length; varpIndex++) {
            int bits = taskVarpValues[varpIndex];
            for (int bit = 0; bit < 32; bit++) {
                boolean done = (bits & (1 << bit)) != 0;
                if (done) {
                    int taskId = varpIndex * 32 + bit;
                    tasks.put(String.valueOf(taskId), true);
                }
            }
        }
        out.put("tasks", tasks);

        return out;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof CombatAchievementState)) return false;

        CombatAchievementState other = (CombatAchievementState) o;
        if (!tiers.equals(other.tiers)) return false;

        for (int i = 0; i < taskVarpValues.length; ++i) {
            if (taskVarpValues[i] != other.taskVarpValues[i]) return false;
        }

        return true;
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Tracks "combo" encounters - Barrows' six brothers, the three Moons of Peril moons - where each
 * sub-boss despawns independently but the group only wants one combined activity-feed/toast/
 * webhook entry naming whichever ones actually died, emitted the moment the shared reward chest
 * (Barrows chest / Lunar Chest) is looted. Individual sub-boss kills still ship as their own
 * ordinary {@link KillLootDeathEvents#onKill} events untouched by this class - so per-NPC kill
 * count/stats tracking keeps working - they're just excluded from the server's notable-npc list
 * so they never surface on their own; this class only adds the extra combined entry on top.
 *
 * Each despawn of a tracked sub-boss ({@link #onSubBossDespawned}) appends its short display label
 * to a per-combo pending list, in kill order. {@link #onComboChestLoot} is called once the
 * matching chest's {@code LootReceived} arrives; it flushes that list into one synthesized
 * {@link KillLootDeathEvents#onComboKill} call carrying every label collected so far, then clears
 * it. A pending list idle for longer than {@link #STALE_MILLIS} (no sub-boss despawn and no chest
 * loot) is dropped rather than carried into a later, unrelated attempt - see
 * {@link #dropIfStale}. Must only be touched from the client thread.
 *
 * The despawn-tracked pending list is only a fallback, though: production data showed Barrows
 * brothers' despawns silently missing the general "died at 0hp" heuristic in
 * {@link GroupScapeTrackerPlugin#onNpcDespawned} for some brothers in a run (no despawn = no
 * {@link #onSubBossDespawned} call at all, same class of gap as the Hunllef/Hueycoatl), which
 * under-reported the combined kill. Barrows has an authoritative alternative - the
 * {@code VarbitID.BARROWS_KILLED_*} flags - so {@link #onComboChestLoot}'s caller reads those
 * directly and passes them in as {@code verifiedLabelsOverride} instead of trusting the pending
 * list for that combo. Moons of Peril has no equivalent varbit, so it still relies on the pending
 * list built from despawns.
 */
public class ComboKillEvents {
    /** No sub-boss death or chest loot arriving within 20 minutes of the last activity means the
     * attempt was abandoned (death, logout, giving up) - the reward chest, if ever opened after
     * that, shouldn't be attributed to a stale/unrelated set of kills. */
    private static final long STALE_MILLIS = 20 * 60 * 1000L;

    /** One combo's identity: the {@code LootReceived} source name that flushes it, the synthetic
     * npc name/id shipped on the combined kill, and the short display label for each tracked
     * sub-boss, keyed by that sub-boss's own {@code NpcDespawned} name. */
    private static final class ComboDefinition {
        final String chestLootName;
        final String combinedNpcName;
        final int sentinelNpcId;
        final Map<String, String> shortLabelsByNpcName;
        // True (Barrows) means an empty/stale pending label list is treated as "no verified kills
        // this attempt" and the chest loot is dropped rather than logged (see onComboChestLoot) -
        // Barrows brothers reliably despawn at 0hp so an empty list really does mean nothing died.
        // False (Moons of Peril) means the chest loot is logged unconditionally, labels or not:
        // the moons never reliably hit 0hp via onNpcDespawned (they finish through an "Enraged"
        // transform - see GroupScapeTrackerPlugin#onNpcDespawned's javadoc on mid-fight transforms),
        // so requiring a verified label first would mean the combo entry almost never fires at all.
        final boolean requireVerifiedSubKills;

        ComboDefinition(String chestLootName, String combinedNpcName, int sentinelNpcId,
                         Map<String, String> shortLabelsByNpcName, boolean requireVerifiedSubKills) {
            this.chestLootName = chestLootName;
            this.combinedNpcName = combinedNpcName;
            this.sentinelNpcId = sentinelNpcId;
            this.shortLabelsByNpcName = shortLabelsByNpcName;
            this.requireVerifiedSubKills = requireVerifiedSubKills;
        }
    }

    // Negative, made-up ids - there's no single real NPC id representing "Barrows" or "Moons of
    // Peril" as a whole, and these are never used to look up anything client-side; the server
    // resolves icon/wiki links from npcName instead (see notable_npcs::is_notable/boss_icon_url).
    private static final int BARROWS_SENTINEL_NPC_ID = -1;
    private static final int MOONS_OF_PERIL_SENTINEL_NPC_ID = -2;

    private static final ComboDefinition BARROWS = new ComboDefinition(
            "Barrows", "Barrows", BARROWS_SENTINEL_NPC_ID, mapOf(
                    "Dharok the Wretched", "Dharok",
                    "Ahrim the Blighted", "Ahrim",
                    "Guthan the Infested", "Guthan",
                    "Karil the Tainted", "Karil",
                    "Torag the Corrupted", "Torag",
                    "Verac the Defiled", "Verac"), true);

    private static final ComboDefinition MOONS_OF_PERIL = new ComboDefinition(
            "Lunar Chest", "Moons of Peril", MOONS_OF_PERIL_SENTINEL_NPC_ID, mapOf(
                    "Blue Moon", "Blue",
                    "Eclipse Moon", "Eclipse",
                    "Blood Moon", "Blood"), false);

    private static final ComboDefinition[] COMBOS = { BARROWS, MOONS_OF_PERIL };

    private static Map<String, String> mapOf(String... pairs) {
        Map<String, String> map = new LinkedHashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            map.put(pairs[i], pairs[i + 1]);
        }
        return map;
    }

    private static final class Pending {
        final List<String> labelsInKillOrder = new ArrayList<>();
        long lastActivityMillis;
    }

    private final Map<ComboDefinition, Pending> pendingByCombo = new LinkedHashMap<>();

    /** Called from {@link GroupScapeTrackerPlugin#onNpcDespawned} for every ordinary kill, in
     * addition to (not instead of) that method's normal {@code onKill} call - a no-op unless
     * {@code npcName} belongs to one of {@link #COMBOS}. */
    public synchronized void onSubBossDespawned(String npcName) {
        for (ComboDefinition combo : COMBOS) {
            String label = combo.shortLabelsByNpcName.get(npcName);
            if (label == null) continue;

            Pending pending = pendingByCombo.computeIfAbsent(combo, c -> new Pending());
            dropIfStale(pending);
            if (!pending.labelsInKillOrder.contains(label)) {
                pending.labelsInKillOrder.add(label);
            }
            pending.lastActivityMillis = System.currentTimeMillis();
            return;
        }
    }

    /** Whether {@code sourceName} is one of {@link #COMBOS}' chest names - checked by
     * {@link GroupScapeTrackerPlugin#onLootReceived} ahead of {@link ChestLootSourceNames}'
     * broader chest handling. */
    public static boolean isComboChestName(String sourceName) {
        for (ComboDefinition combo : COMBOS) {
            if (combo.chestLootName.equals(sourceName)) return true;
        }
        return false;
    }

    /**
     * Called from {@link GroupScapeTrackerPlugin#onLootReceived} when a {@code LootReceived}
     * {@code LootRecordType.EVENT} source name matches a combo's chest (see
     * {@link #isComboChestName}). Flushes whichever sub-bosses were tracked as killed since the
     * last flush into one combined kill with this loot attached, mirroring the Gauntlet's
     * synthesized-kill pattern ({@code claimPendingGauntletKill}) - unlike that one there's no
     * separate {@code onLoot} call for the caller to make, since an empty/stale pending set (see
     * below) means there may be no kill at all to attach the loot to.
     *
     * @param verifiedLabelsOverride when non-null, used in place of the despawn-tracked pending
     * list for this flush - e.g. Barrows brothers' deaths, read straight from their
     * {@code VarbitID.BARROWS_KILLED_*} flags in {@link GroupScapeTrackerPlugin#onLootReceived},
     * since despawn/health-ratio detection silently misses some brothers in production (see that
     * call site's javadoc) the same way it does for the Hunllef/Hueycoatl. Null keeps the
     * existing despawn-tracked behavior (Moons of Peril, which has no equivalent varbit).
     * @return true if {@code sourceName} matched a combo chest (caller should treat this loot as
     * claimed rather than falling back to a standalone chest "loot" event) - even when nothing
     * ends up logged (see below)
     */
    public synchronized boolean onComboChestLoot(String playerName, String sourceName, int worldX, int worldY,
                                                  int plane, int world, List<Map<String, Object>> items,
                                                  KillLootDeathEvents killLootDeathEvents,
                                                  List<String> verifiedLabelsOverride) {
        for (ComboDefinition combo : COMBOS) {
            if (!combo.chestLootName.equals(sourceName)) continue;

            Pending pending = pendingByCombo.remove(combo);
            List<String> labels;
            if (verifiedLabelsOverride != null) {
                labels = verifiedLabelsOverride;
            } else {
                if (pending != null) {
                    dropIfStale(pending);
                }
                labels = pending != null ? new ArrayList<>(pending.labelsInKillOrder) : new ArrayList<>();
            }
            // Empty/stale pending set on a combo that requires verified sub-kills (Barrows):
            // nothing verified as killed this run, so nothing is logged (no misleading empty-
            // bracket or guessed-full-run entry) - the chest loot itself is still consumed as
            // "claimed" so it doesn't also fall through to a standalone chest loot event with no
            // sub-boss context. A combo that doesn't require verification (Moons of Peril) logs
            // regardless, since its sub-bosses' despawns aren't reliably detectable to begin with
            // (see ComboDefinition#requireVerifiedSubKills) - an empty label list there just means
            // no per-moon breakdown, not "nothing happened".
            if (!labels.isEmpty() || !combo.requireVerifiedSubKills) {
                killLootDeathEvents.onComboKill(playerName, combo.sentinelNpcId, combo.combinedNpcName,
                        labels, worldX, worldY, plane, world);
                killLootDeathEvents.onLoot(combo.combinedNpcName, items);
            }
            return true;
        }
        return false;
    }

    private void dropIfStale(Pending pending) {
        if (pending.lastActivityMillis != 0 && System.currentTimeMillis() - pending.lastActivityMillis > STALE_MILLIS) {
            pending.labelsInKillOrder.clear();
        }
    }
}

package com.groupscape;

public interface ConsumableState {
    Object get();

    String whoOwnsThis();
}

package com.groupscape;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@Singleton
public class DataManager {
    @Inject
    Client client;
    @Inject
    GroupScapeTrackerConfig config;
    @Inject
    private CollectionLogV2Manager collectionLogV2Manager;
    @Inject
    private HttpRequestService httpRequestService;
    @Inject
    private ScheduledExecutorService executor;
    private int skipNextNAttempts = 0;
    private GroupLinkListener groupLinkListener;

    /**
     * Forces a heartbeat-only POST (just the player name, no changed fields) at least this often
     * even when nothing tracked has changed. Without this, a fully idle/AFK player (no
     * inventory/position/stat changes) never sends anything at all, so the server's
     * last-seen timestamp for them goes stale and they read as offline until something finally
     * changes - which can mean indefinitely, until the player restarts and the plugin's
     * previous-state caches reset to null, forcing every field to look "changed" again.
     */
    private static final long HEARTBEAT_INTERVAL_MILLIS = 30_000;
    private long lastSentAtMillis = 0;

    /** Called once from plugin startup; not constructor-injected since Guice owns this singleton. */
    public void setGroupLinkListener(GroupLinkListener groupLinkListener) {
        this.groupLinkListener = groupLinkListener;
    }

    @Getter
    private final DataState inventory = new DataState("inventory", false);
    @Getter
    private final DataState bank = new DataState("bank", false);
    @Getter
    private final DataState equipment = new DataState("equipment", false);
    @Getter
    private final DataState sharedBank = new DataState("shared_bank", true);
    @Getter
    private final DataState resources = new DataState("stats", false);
    @Getter
    private final DataState skills = new DataState("skills", false);
    @Getter
    private final DataState quests = new DataState("quests", false);
    @Getter
    private final DataState position = new DataState("coordinates", false);
    @Getter
    private final DataState runePouch = new DataState("rune_pouch", false);
    @Getter
    private final DataState quiver = new DataState("quiver", false);
    @Getter
    private final DataState interacting = new DataState("interacting", false);
    @Getter
    private final DataState seedVault = new DataState("seed_vault", false);
    @Getter
    private final DataState potionStorage = new DataState("potion_storage", false);
    @Getter
    private final DataState achievementDiary = new DataState("diary_vars", false);
    @Getter
    private final DataState combatAchievements = new DataState("combat_achievements", false);
    @Getter
    private final DataState slayerTask = new DataState("slayer_task", false);
    @Getter
    private final DataState specialAttack = new DataState("special_attack", false);
    @Getter
    private final DataState activePrayers = new DataState("active_prayers", false);
    @Getter
    private final DataState richPresence = new DataState("rich_presence", false);
    @Getter
    private final DepositedItems deposited = new DepositedItems();
    @Getter
    private final KillLootDeathEvents killLootDeathEvents = new KillLootDeathEvents();
    @Getter
    private final ObjectInteractionEvents objectInteractionEvents = new ObjectInteractionEvents();
    @Getter
    private final InteractionEvents interactionEvents = new InteractionEvents();
    @Getter
    private final NpcDialogueTracker npcDialogueTracker = new NpcDialogueTracker();
    @Getter
    private final AlertEvents alertEvents = new AlertEvents();
    @Getter
    private final NotableDropEvents notableDropEvents = new NotableDropEvents();
    @Getter
    private final SlayerTaskCloseEvents slayerTaskCloseEvents = new SlayerTaskCloseEvents();
    @Getter
    private final RaidCompletionEvents raidCompletionEvents = new RaidCompletionEvents();
    @Getter
    private final ComboKillEvents comboKillEvents = new ComboKillEvents();

    public void submitToApi() {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null || isBadWorldType()) return;
        if (skipNextNAttempts-- > 0) return;

        String playerName = client.getLocalPlayer().getName();
        String apiKey = config.apiKey().trim();

        if (apiKey.length() > 0) {
            String url = getUpdateGroupMemberUrl();
            if (url == null) return;

            Map<String, Object> updates = new HashMap<>();
            updates.put("name", playerName);
            inventory.consumeState(updates);
            bank.consumeState(updates);
            equipment.consumeState(updates);
            sharedBank.consumeState(updates);
            resources.consumeState(updates);
            skills.consumeState(updates);
            quests.consumeState(updates);
            position.consumeState(updates);
            runePouch.consumeState(updates);
            quiver.consumeState(updates);
            interacting.consumeState(updates);
            deposited.consumeState(updates);
            seedVault.consumeState(updates);
            potionStorage.consumeState(updates);
            achievementDiary.consumeState(updates);
            combatAchievements.consumeState(updates);
            slayerTask.consumeState(updates);
            specialAttack.consumeState(updates);
            activePrayers.consumeState(updates);
            richPresence.consumeState(updates);
            collectionLogV2Manager.consumeClogItems(updates);
            killLootDeathEvents.consumeState(updates);
            raidCompletionEvents.consumeState(updates);
            objectInteractionEvents.consumeState(updates);
            interactionEvents.consumeState(updates);
            alertEvents.consumeState(updates);
            notableDropEvents.consumeState(updates);
            slayerTaskCloseEvents.consumeState(updates);

            boolean hasChanges = updates.size() > 1;
            boolean heartbeatDue = System.currentTimeMillis() - lastSentAtMillis >= HEARTBEAT_INTERVAL_MILLIS;
            if (hasChanges || heartbeatDue) {
                lastSentAtMillis = System.currentTimeMillis();
                HttpRequestService.HttpResponse response = httpRequestService.post(url, apiKey, updates);

                if (!response.isSuccessful()) {
                    log.warn("Telemetry POST failed ({}): {} {}", updates.size() - 1, response.getCode(), response.getBody());
                    skipNextNAttempts = 10;
                    restoreStateIfNothingUpdated();
                    if (response.getCode() == 403 && groupLinkListener != null) {
                        groupLinkListener.onLinkRequired();
                    }
                } else {
                    collectionLogV2Manager.clearClogItems();
                    if (groupLinkListener != null) {
                        groupLinkListener.onLinked();
                    }
                }
            } else {
                log.debug("Skip POST: no changes to send (fields={})", updates.size());
            }
        }
    }

    public void uploadPortrait(byte[] mesh) {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null || isBadWorldType()) return;

        String playerName = client.getLocalPlayer().getName();
        String apiKey = config.apiKey().trim();
        // The /update-portrait route is behind the same Authenticated middleware as everything
        // else, so a bad key or an unlinked character still fails safely below.
        if (apiKey.isEmpty()) return;

        String url = getUpdatePortraitUrl(playerName);
        if (url == null) return;

        // capture() runs on the client thread (needed to read the live Model), but OkHttp's
        // blocking call() is not allowed there - RuneLite throws "Blocking network calls are
        // not allowed on the client thread" and the upload silently never lands. Everything
        // above this point only touches client-thread state, so hand off just the network call.
        executor.execute(() -> {
            HttpRequestService.HttpResponse response =
                    httpRequestService.postBytes(url, apiKey, mesh, "application/octet-stream");

            if (!response.isSuccessful()) {
                log.debug("Portrait upload failed ({} bytes): {} {}", mesh.length, response.getCode(), response.getBody());
            }
        });
    }

    /**
     * Lets the server learn this character's RSN even before it has been linked to a group -
     * needed for a website confirmation UI. Cheap and idempotent, so it's fine to call on the
     * same ~1s cadence as the rest of the periodic reconciliation. Called from the client thread
     * (see reconcileRosterConnection()), so - like uploadPortrait() - the actual network call is
     * handed off to the executor rather than blocking here.
     */
    public void identify() {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null) return;

        String apiKey = config.apiKey().trim();
        if (apiKey.isEmpty()) return;

        String url = getIdentifyUrl();
        if (url == null) return;

        String playerName = client.getLocalPlayer().getName();
        Map<String, Object> body = new HashMap<>();
        body.put("rsn", playerName);

        executor.execute(() -> httpRequestService.post(url, apiKey, body));
    }

    // NOTE: These states should only be restored if a new update did not come in at some point before calling this
    private void restoreStateIfNothingUpdated() {
        inventory.restoreState();
        bank.restoreState();
        equipment.restoreState();
        sharedBank.restoreState();
        resources.restoreState();
        skills.restoreState();
        quests.restoreState();
        position.restoreState();
        runePouch.restoreState();
        quiver.restoreState();
        interacting.restoreState();
        deposited.restoreState();
        seedVault.restoreState();
        potionStorage.restoreState();
        achievementDiary.restoreState();
        combatAchievements.restoreState();
        slayerTask.restoreState();
        specialAttack.restoreState();
        activePrayers.restoreState();
        richPresence.restoreState();
        killLootDeathEvents.restoreState();
        raidCompletionEvents.restoreState();
        objectInteractionEvents.restoreState();
        interactionEvents.restoreState();
        alertEvents.restoreState();
        notableDropEvents.restoreState();
        slayerTaskCloseEvents.restoreState();
    }

    private String baseUrl() {
        return httpRequestService.getBaseUrl();
    }

    /** Returns null (matching the old "missing config" guard) when the account hash isn't ready yet. */
    private String accountHash() {
        long accountHash = client.getAccountHash();
        if (accountHash == -1) return null;

        return String.valueOf(accountHash);
    }

    private String getUpdateGroupMemberUrl() {
        String baseUrl = baseUrl();
        String accountHash = accountHash();

        if (baseUrl == null || accountHash == null) return null;

        return String.format("%s/api/characters/%s/update-group-member", baseUrl, accountHash);
    }

    private String getUpdatePortraitUrl(String playerName) {
        String baseUrl = baseUrl();
        String accountHash = accountHash();

        if (baseUrl == null || accountHash == null) return null;

        return String.format("%s/api/characters/%s/update-portrait/%s", baseUrl, accountHash, urlEncodePathSegment(playerName));
    }

    private String getIdentifyUrl() {
        String baseUrl = baseUrl();
        String accountHash = accountHash();

        if (baseUrl == null || accountHash == null) return null;

        return String.format("%s/api/characters/%s/identify", baseUrl, accountHash);
    }

    // RuneScape names can contain spaces (e.g. "Zezima 1"), which OkHttp's Request.Builder.url()
    // rejects unencoded, silently failing the request before it's ever sent.
    private static String urlEncode(String value) {
        try {
            return java.net.URLEncoder.encode(value, "UTF-8");
        } catch (java.io.UnsupportedEncodingException e) {
            return value;
        }
    }

    // URLEncoder is query-string encoding (space -> '+'); a path segment needs percent-encoding
    // (space -> "%20") since actix percent-decodes path segments but won't treat '+' as a space.
    private static String urlEncodePathSegment(String value) {
        return urlEncode(value).replace("+", "%20");
    }

    private boolean isBadWorldType() {
        EnumSet<WorldType> worldTypes = client.getWorldType();
        for (WorldType worldType : worldTypes) {
            if (worldType == WorldType.SEASONAL ||
                    worldType == WorldType.DEADMAN ||
                    worldType == WorldType.TOURNAMENT_WORLD ||
                    worldType == WorldType.PVP_ARENA ||
                    worldType == WorldType.BETA_WORLD ||
                    worldType == WorldType.QUEST_SPEEDRUNNING) {
                return true;
            }
        }

        return false;
    }
}

package com.groupscape;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;

public class DataState {
    private final AtomicReference<ConsumableState> state = new AtomicReference<>();
    private ConsumableState previousState;
    private final String key;
    private final boolean transactionBased;

    DataState() {
        key = "";
        transactionBased = false;
    }

    DataState(String key, boolean transactionBased) {
        this.key = key;
        this.transactionBased = transactionBased;
    }

    public void update(ConsumableState o) {
        if (!o.equals(previousState)) {
            previousState = o;

            if (!transactionBased) {
                state.set(o);
            }
        }
    }

    public Object consumeState(String whoIsUpdating) {
        return consumeState(whoIsUpdating, new HashMap<>());
    }

    public Object consumeState(Map<String, Object> output) {
        return consumeState((String) output.get("name"), output);
    }

    public Object consumeState(String whoIsUpdating, Map<String, Object> output) {
        final ConsumableState consumedState = state.getAndSet(null);
        if (consumedState != null) {
            final String whoOwnsThis = consumedState.whoOwnsThis();
            if (whoOwnsThis != null && whoOwnsThis.equals(whoIsUpdating)) {
                Object c = consumedState.get();
                output.put(key, c);
                return c;
            }
        }

        return null;
    }

    public ConsumableState mostRecentState() {
        return this.previousState;
    }

    public void restoreState() {
        state.compareAndSet(null, previousState);
    }

    public void commitTransaction() {
        state.set(previousState);
    }
}

package com.groupscape;

import java.util.Map;

public class DepositedItems {
    private ItemContainerState items = null;
    private ItemContainerState consumedItems = null;

    public DepositedItems() {
    }

    public synchronized void update(ItemContainerState deposited) {
        if (deposited == null) return;
        if (items == null || !deposited.whoOwnsThis().equals(items.whoOwnsThis())) {
            items = deposited;
        } else {
            items = items.add(deposited);
        }
    }

    public synchronized void consumeState(Map<String, Object> output) {
        if (items != null) {
            final String whoOwnsThis = items.whoOwnsThis();
            final String whoIsUpdating = (String) output.get("name");
            if (whoOwnsThis != null && whoOwnsThis.equals(whoIsUpdating)) output.put("deposited", items.get());
        }
        consumedItems = items;
        items = null;
    }

    public synchronized void restoreState() {
        if (consumedItems == null) return;
        if (items != null) {
            items = items.add(consumedItems);
        } else {
            items = consumedItems;
        }
        consumedItems = null;
    }

    public synchronized void reset() {
        items = null;
        consumedItems = null;
    }
}

package com.groupscape;

/**
 * Notified when the server rejects a request because this character isn't linked to a group yet
 * (HTTP 403), and again once a request subsequently succeeds. Shared between every client that
 * talks to a `/api/characters/{accountHash}/...` route ({@link com.groupscape.roster.RosterClient}'s
 * websocket, {@link DataManager}'s telemetry POSTs) so a single debounced warning covers all of
 * them instead of each failing silently on its own.
 */
public interface GroupLinkListener {
    void onLinkRequired();
    void onLinked();
}

package com.groupscape;

import com.groupscape.roster.ChatState;
import com.groupscape.roster.GroupSnapshotMember;
import com.groupscape.roster.GroupSnapshotState;
import com.groupscape.roster.RosterMember;
import com.groupscape.roster.RosterState;
import com.groupscape.roster.RosterWireTypes;
import com.groupscape.sidepanel.ChatPanel;
import com.groupscape.sidepanel.RosterListPanel;
import com.groupscape.sidepanel.SidePanelTheme;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Window;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.WindowEvent;
import java.awt.event.WindowFocusListener;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JViewport;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidepanel with two top-level tabs (spec §2/§6): Roster - the existing HP/prayer/run/spec +
 * per-member inventory/equipment/stats view - and Chat, the group's {@code !gs} chat log with its
 * own input box. A Swing {@link Timer} pulls from {@link RosterState}/{@link GroupSnapshotState}
 * (roster) and {@link ChatState} (chat) rather than being pushed to directly, since all three are
 * written from background threads.
 *
 * <p>The Chat tab's unread dot doubles as this session's read-cursor auto-advance trigger (spec
 * §6): {@link #updateChatUnreadDot} only advances {@link #lastSeenChatMessageId} - and pushes it
 * to the server via {@link ChatMarkReadManager} - while the tab is both the active one
 * ({@code visible}) and the RuneLite client window has OS focus ({@link #windowFocused}, tracked
 * via a {@link WindowFocusListener} attached in {@link #addNotify()}). {@link #applyChatRead}
 * mirrors the same clear from the other direction - an incoming {@code ChatRead} broadcast from
 * one of this account's *other* live sessions.
 */
class GroupScapePanel extends PluginPanel {
    private static final int REFRESH_MS = 600;
    private static final String TAB_ROSTER = "roster";
    private static final String TAB_CHAT = "chat";

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final ClientThread clientThread;
    private final ChatMarkReadManager chatMarkReadManager;
    private final RosterListPanel rosterListPanel;
    private final ChatPanel chatPanel;
    private final Timer refreshTimer;
    private final JLabel rosterTabButton;
    private final JLabel chatTabButton;
    private final JPanel content;

    private String activeTab = TAB_ROSTER;
    private volatile long lastSeenChatMessageId = -1;
    private volatile boolean windowFocused = true;
    private boolean focusListenerAttached = false;
    // Chat divider boundary, frozen once per Chat-tab "viewing session" - see
    // updateChatDividerSnapshot's doc comment. -1 means "not currently frozen".
    private long dividerSnapshotCursor = -1;
    private long dividerSnapshotNewestId = -1;

    GroupScapePanel(
            Runnable onOpenGroupScape,
            Client client,
            GroupScapeTrackerConfig config,
            RosterState rosterState,
            GroupSnapshotState groupSnapshotState,
            ChatState chatState,
            Consumer<String> onSendChatMessage,
            ChatMarkReadManager chatMarkReadManager,
            ItemManager itemManager,
            SkillIconManager skillIconManager,
            SpriteManager spriteManager,
            ClientThread clientThread,
            Supplier<RosterMember> localMemberSupplier,
            Supplier<GroupSnapshotMember> localSnapshotSupplier
    ) {
        super(false);
        this.client = client;
        this.config = config;
        this.clientThread = clientThread;
        this.chatMarkReadManager = chatMarkReadManager;

        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        JButton openButton = new JButton("Open GroupScape");
        openButton.setPreferredSize(new Dimension(0, 30));
        openButton.addActionListener(event -> onOpenGroupScape.run());
        add(openButton, BorderLayout.NORTH);

        JPanel body = new JPanel(new BorderLayout());
        body.setOpaque(false);
        add(body, BorderLayout.CENTER);

        rosterTabButton = tabButton("Roster", TAB_ROSTER);
        chatTabButton = tabButton("Chat", TAB_CHAT);
        JPanel tabStrip = new JPanel(new java.awt.GridLayout(1, 2));
        tabStrip.setOpaque(false);
        tabStrip.setBorder(new EmptyBorder(4, 0, 0, 0));
        tabStrip.add(rosterTabButton);
        tabStrip.add(chatTabButton);
        body.add(tabStrip, BorderLayout.NORTH);

        rosterListPanel = new RosterListPanel(client, config, itemManager, skillIconManager, spriteManager, clientThread);
        JScrollPane rosterScrollPane = new JScrollPane(rosterListPanel,
                ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED, ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        rosterScrollPane.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
        rosterScrollPane.getVerticalScrollBar().setUnitIncrement(16);
        // BLIT_SCROLL_MODE (the default) copies existing pixels around on scroll/resize instead
        // of repainting them - a card growing when a tab opens shifts everything below it, and
        // that blit copy was leaving stale fragments (a card's old header/vitals) behind in
        // whatever now-different content scrolled into that spot. Always repainting properly
        // avoids the stale copy entirely.
        rosterScrollPane.getViewport().setScrollMode(JViewport.SIMPLE_SCROLL_MODE);

        chatPanel = new ChatPanel(rosterState, onSendChatMessage);

        content = new JPanel(new CardLayout());
        content.setOpaque(false);
        content.setBorder(new EmptyBorder(6, 0, 0, 0));
        content.add(rosterScrollPane, TAB_ROSTER);
        content.add(chatPanel, TAB_CHAT);
        body.add(content, BorderLayout.CENTER);

        selectTab(TAB_ROSTER);

        refreshTimer = new Timer(REFRESH_MS, e -> {
            rosterListPanel.refresh(
                    rosterState.all(), groupSnapshotState, localMemberSupplier.get(), localSnapshotSupplier.get());
            updateChatDividerSnapshot(chatState);
            chatPanel.refresh(chatState, dividerSnapshotCursor, dividerSnapshotNewestId);
            updateChatUnreadDot(chatState);
        });
        refreshTimer.start();
    }

    /**
     * Freezes {@link #dividerSnapshotCursor}/{@link #dividerSnapshotNewestId} the instant the
     * Chat tab becomes active, clearing them the instant it isn't - mirrors the webapp chat
     * drawer's {@code open()}/{@code freezeDividerSnapshot} (see that doc comment for why a
     * message that arrives *during* an already-active viewing session, this account's own sent
     * message included, must never itself trigger the divider). Waits for {@link
     * #updateChatUnreadDot}'s own first-tick initialization of {@link #lastSeenChatMessageId}
     * before freezing (runs one tick later than that method in the timer above), so a Chat tab
     * that's already active on plugin startup doesn't freeze against the sentinel `-1` and flag
     * the entire backfilled history as unread.
     */
    private void updateChatDividerSnapshot(ChatState chatState) {
        if (!TAB_CHAT.equals(activeTab)) {
            dividerSnapshotCursor = -1;
            dividerSnapshotNewestId = -1;
            return;
        }
        if (dividerSnapshotCursor >= 0 || lastSeenChatMessageId < 0) return;
        dividerSnapshotCursor = lastSeenChatMessageId;
        dividerSnapshotNewestId = chatState.latestMessageId();
    }

    private void selectTab(String tab) {
        activeTab = tab;
        ((CardLayout) content.getLayout()).show(content, tab);
        highlightTab(rosterTabButton, TAB_ROSTER.equals(tab));
        highlightTab(chatTabButton, TAB_CHAT.equals(tab));
        // Dot clears on the next refresh tick via updateChatUnreadDot, which sees activeTab ==
        // TAB_CHAT - but only if the window is also focused right now, per spec §6.
    }

    /** Attaches a {@link WindowFocusListener} to the RuneLite client window the first time this
     * panel is realized - {@link java.awt.Component#addNotify()} is the standard Swing hook for
     * "now part of a window hierarchy", since no ancestor window exists yet at construction time
     * (the panel isn't added to the sidebar's toolbar until after this constructor returns). */
    @Override
    public void addNotify() {
        super.addNotify();
        if (focusListenerAttached) return;
        Window window = javax.swing.SwingUtilities.getWindowAncestor(this);
        if (window == null) return;
        focusListenerAttached = true;
        windowFocused = window.isFocused();
        window.addWindowFocusListener(new WindowFocusListener() {
            @Override
            public void windowGainedFocus(WindowEvent e) {
                windowFocused = true;
            }

            @Override
            public void windowLostFocus(WindowEvent e) {
                windowFocused = false;
            }
        });
    }

    /** Plain unread dot (no count) on the Chat tab label when it isn't read - see spec §6.
     * "Read" means the tab is both the active one and the client window has OS focus; either
     * alone leaves the dot up. When both hold and new messages arrived, advances the local cursor
     * and pushes it to the server read cursor via {@link ChatMarkReadManager}. */
    private void updateChatUnreadDot(ChatState chatState) {
        long latest = chatState.latestMessageId();
        if (lastSeenChatMessageId < 0) {
            lastSeenChatMessageId = latest; // first tick: don't flag pre-existing backfilled history as unread
            chatTabButton.setText("Chat");
            return;
        }

        boolean readNow = TAB_CHAT.equals(activeTab) && windowFocused;
        if (readNow && latest > lastSeenChatMessageId) {
            lastSeenChatMessageId = latest;
            chatMarkReadManager.markRead(latest, config);
        }

        chatTabButton.setText(latest > lastSeenChatMessageId ? "Chat ●" : "Chat");
    }

    /** Mirrors {@link #updateChatUnreadDot}'s clear from the other direction - one of this
     * account's *other* live sessions (another RuneLite client, or a webapp tab) advanced the
     * server read cursor. {@code payload.memberName} carries no account id (see the server's
     * {@code ChatReadPayload} doc comment), so this compares it against the local player's own
     * name - reading {@link Client} state off the client thread, since this runs on the
     * WebSocket's own callback thread (see {@code RosterClient}). */
    void applyChatRead(RosterWireTypes.ChatReadPayload payload) {
        clientThread.invoke(() -> {
            Player local = client.getLocalPlayer();
            String localName = local != null ? local.getName() : null;
            if (localName == null || !localName.equalsIgnoreCase(payload.memberName)) return;
            if (payload.messageId > lastSeenChatMessageId) {
                lastSeenChatMessageId = payload.messageId;
            }
        });
    }

    private JLabel tabButton(String text, String tab) {
        JLabel label = new JLabel(text, SwingConstants.CENTER);
        label.setOpaque(true);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setBackground(SidePanelTheme.CARD_BG);
        label.setForeground(SidePanelTheme.MUTED);
        label.setBorder(new MatteBorder(0, 0, 2, 0, SidePanelTheme.BORDER));
        label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        label.setPreferredSize(new Dimension(0, 26));
        label.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                selectTab(tab);
            }
        });
        return label;
    }

    private void highlightTab(JLabel label, boolean active) {
        label.setForeground(active ? SidePanelTheme.ACCENT : SidePanelTheme.MUTED);
        label.setBorder(new MatteBorder(0, 0, 2, 0, active ? SidePanelTheme.ACCENT : SidePanelTheme.BORDER));
    }
}

