        return other.id == id && other.quantity == quantity;
    }
}

package com.groupscape;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
public class ItemContainerState implements ConsumableState {
    private final List<ItemContainerItem> items;
    private transient final String playerName;

    public ItemContainerState(String playerName, ItemContainer container, ItemManager itemManager) {
        this.playerName = playerName;
        items = new ArrayList<>();
        Item[] contents = container.getItems();
        for (final Item item : contents) {
            if (isItemValid(item, itemManager)) {
                items.add(new ItemContainerItem(itemManager.canonicalize(item.getId()), item.getQuantity()));
            }
        }
    }

    // NOTE: This is for when we care about the order of the items in the container
    // like the player inventory and equipment.
    public ItemContainerState(String playerName, ItemContainer container, ItemManager itemManager, int containerSize) {
        this.playerName = playerName;
        items = new ArrayList<>();
        for (int i = 0; i < containerSize; i++) {
            Item item = container.getItem(i);
            if (!isItemValid(item, itemManager)) {
                items.add(new ItemContainerItem(0, 0));
            } else {
                items.add(new ItemContainerItem(itemManager.canonicalize(item.getId()), item.getQuantity()));
            }
        }
    }

    public ItemContainerState(String playerName, List<ItemContainerItem> items) {
        this.playerName = playerName;
        this.items = items;
    }

    @Nullable
    public ItemContainerState add(ItemContainerState itemsToAdd) {
        if (itemsToAdd == null || !itemsToAdd.whoOwnsThis().equals(whoOwnsThis())) return null;
        Map<Integer, ItemContainerItem> thisItems = getItemMap();
        Map<Integer, ItemContainerItem> otherItems = itemsToAdd.getItemMap();
        List<ItemContainerItem> result = new ArrayList<>();

        for (Integer itemId : thisItems.keySet()) {
            ItemContainerItem item = thisItems.get(itemId);
            if (otherItems.containsKey(itemId)) {
                item.addQuantity(otherItems.get(itemId).getQuantity());
            }
            result.add(item);
        }

        for (Integer itemId : otherItems.keySet()) {
            if (!thisItems.containsKey(itemId)) {
                result.add(otherItems.get(itemId));
            }
        }

        return new ItemContainerState(whoOwnsThis(), result);
    }

    @Nullable
    public ItemContainerState whatGotRemoved(ItemContainerState other) {
        if (other == null || !other.whoOwnsThis().equals(whoOwnsThis())) return null;
        Map<Integer, ItemContainerItem> thisItems = getItemMap();
        Map<Integer, ItemContainerItem> otherItems = other.getItemMap();
        List<ItemContainerItem> result = new ArrayList<>();

        for (Integer itemId : otherItems.keySet()) {
            ItemContainerItem otherItem = otherItems.get(itemId);
            if (otherItem.getId() == 0) continue;

            if (thisItems.containsKey(itemId)) {
                ItemContainerItem thisItem = thisItems.get(itemId);
                int quantityDifference = otherItem.getQuantity() - thisItem.getQuantity();
                if (quantityDifference > 0) {
                    result.add(new ItemContainerItem(itemId, quantityDifference));
                }
            } else {
                result.add(new ItemContainerItem(itemId, otherItem.getQuantity()));
            }
        }

        return new ItemContainerState(playerName, result);
    }

    public Map<Integer, ItemContainerItem> getItemMap() {
        Map<Integer, ItemContainerItem> itemMap = new HashMap<>();
        for (ItemContainerItem itemContainerItem : items) {
            Integer id = itemContainerItem.getId();
            if (itemMap.containsKey(id)) {
                itemMap.get(id).addQuantity(itemContainerItem.getQuantity());
            } else {
                itemMap.put(id, new ItemContainerItem(id, itemContainerItem.getQuantity()));
            }
        }
        return itemMap;
    }

    public boolean isEmpty() {
        return items.isEmpty();
    }

    private boolean isItemValid(Item item, ItemManager itemManager) {
        if (item == null) return false;
        final int id = item.getId();
        final int quantity = item.getQuantity();
        if (itemManager != null) {
            final boolean isPlaceholder = itemManager.getItemComposition(id).getPlaceholderTemplateId() != -1;

            return id >= 0 && quantity >= 0 && !isPlaceholder;
        }
        return false;
    }

    public List<Integer> asFlatList() {
        List<Integer> result = new ArrayList<>(items.size() * 2);

        for (ItemContainerItem item : items) {
            result.add(item.getId());
            result.add(item.getQuantity());
        }
        return result;
    }

    @Override
    public Object get() {
        return asFlatList();
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof ItemContainerState)) return false;
        ItemContainerState other = (ItemContainerState) o;
        if (other.items.size() != items.size()) return false;

        for (int i = 0; i < items.size(); i++) {
            if (!items.get(i).equals(other.items.get(i))) return false;
        }

        return true;
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.time.Instant;
import java.util.UUID;

/**
 * Kill/loot/death/chest-or-clue-loot aren't per-tick snapshot data like the rest of
 * {@link DataManager}'s {@link DataState} fields - they're discrete events detected between
 * uploads, so this accumulates them into a list (mirroring {@link DepositedItems}'s
 * accumulator pattern rather than DataState's latest-value-wins one) and drains everything
 * buffered since the last upload into the "events" key on the next {@code consumeState}.
 *
 * Kill+loot correlation is best-effort, matched by NPC name. It runs in both directions:
 * a same-name {@code LootReceived} arriving after {@code NpcDespawned} attaches straight to
 * the held {@link PendingKill}; one arriving *before* it (loot is typically granted before the
 * corpse actually despawns) is buffered in {@link #pendingUnmatchedLoot} and claimed by the
 * next matching {@link #onKill}. A freshly-captured, still loot-less {@link PendingKill} is held
 * back from the drain for {@link #LOOT_GRACE_MILLIS} (see {@link #consumeState}) rather than
 * shipped immediately, so a {@code LootReceived} that lands a moment after the despawn (observed
 * for bosses with a longer death animation, e.g. Vardorvis) still has a chance to attach before
 * the kill goes out loot-less. Once that grace period elapses with no match, the kill ships
 * without loot and the loot is dropped rather than held back indefinitely.
 *
 * Chest/clue loot (see {@link #onChestOrClueLoot}) is unrelated to that correlation - it has
 * no kill to attach to, so it's queued and drained as its own standalone "loot"-typed event
 * alongside kills/deaths. Everything here is drained into the same "events" key by
 * {@link #consumeState}, so a second, independent accumulator would race with this one over
 * who last wrote that key - hence chest/clue loot living on this class rather than a sibling
 * one. Must only be touched from the client thread.
 *
 * Every event gets a random {@code eventId} at the moment it's captured (in {@link PendingKill}'s
 * constructor, {@link #onDeath}, {@link #onChestOrClueLoot}) rather than when it's sent, so a
 * resend from {@link #restoreState} - e.g. after a server restart drops the connection before its
 * (already-successful) response reaches the client - carries the same id both times and the
 * server can reject the replay instead of double-counting the kill/loot/death.
 */
public class KillLootDeathEvents {
    /** Bound on {@link #pendingUnmatchedLoot} so a kill that never despawns (e.g. NPC leaves
     * the area) can't leak memory - the oldest unmatched loot is dropped once this is hit. */
    private static final int MAX_UNMATCHED_LOOT = 20;

    /** How long a loot-less {@link PendingKill} is held back from the drain in {@link #consumeState}
     * to give a late-arriving same-name {@code LootReceived} a chance to attach (see class doc). */
    private static final long LOOT_GRACE_MILLIS = 3000;

    private final List<PendingKill> pendingKills = new ArrayList<>();
    private final List<Map<String, Object>> pendingDeaths = new ArrayList<>();
    private final List<Map<String, Object>> pendingLoot = new ArrayList<>();
    // Internal correlation buffers only - unlike pendingKills/Deaths/Loot they're never
    // themselves part of the "events" upload, so consumeState/restoreState don't touch them.
    private final List<UnmatchedLoot> pendingUnmatchedLoot = new ArrayList<>();
    // Bound for the same leak reason as pendingUnmatchedLoot: an "X kill count is" line whose
    // boss never actually despawns (e.g. a kill count chat message from a source we don't track
    // a despawn for) can't accumulate forever.
    private static final int MAX_UNMATCHED_KC = 20;
    private final List<UnmatchedKc> pendingUnmatchedKc = new ArrayList<>();
    private String owner;

    private List<PendingKill> consumedKills;
    private List<Map<String, Object>> consumedDeaths;
    private List<Map<String, Object>> consumedLoot;
    private String consumedOwner;

    private static final class UnmatchedLoot {
        final String npcName;
        final List<Map<String, Object>> items;

        UnmatchedLoot(String npcName, List<Map<String, Object>> items) {
            this.npcName = npcName;
            this.items = items;
        }
    }

    private static final class UnmatchedKc {
        final String npcName;
        final int accountKc;

        UnmatchedKc(String npcName, int accountKc) {
            this.npcName = npcName;
            this.accountKc = accountKc;
        }
    }

    private static final class PendingKill {
        final int npcId;
        final String npcName;
        final int worldX;
        final int worldY;
        final int plane;
        final int world;
        final String occurredAt;
        // Generated once here, at capture time, not on every send - consumeState/restoreState
        // requeue this same PendingKill object verbatim on a failed upload, so a resend carries
        // the identical id and the server can recognize it as a replay rather than a new kill
        // (see DataManager.restoreStateIfNothingUpdated).
        final String eventId;
        // Wall-clock capture time, purely local bookkeeping for the LOOT_GRACE_MILLIS hold in
        // consumeState - unlike occurredAt this is never sent to the server.
        final long createdAtMillis;
        List<Map<String, Object>> loot;
        Integer accountKc;
        // Non-null only for a combo kill synthesized by ComboKillEvents (e.g. "Barrows"/"Moons of
        // Peril") - the short display labels of whichever sub-bosses were actually killed that
        // run, in kill order. Absent for every ordinary single-NPC kill.
        List<String> subKills;
        // Non-null only for the single synthesized "Doom of Mokhaiotl" kill created by
        // GroupScapeTrackerPlugin#claimDoomOfMokhaiotlKill - the delve level the player had
        // reached when they claimed rewards and left, scraped from the reward widget. Absent for
        // every other kill, and absent even for a Doom kill if the scrape failed to find a level.
        Integer delveLevel;

        PendingKill(int npcId, String npcName, int worldX, int worldY, int plane, int world) {
            this.npcId = npcId;
            this.npcName = npcName;
            this.worldX = worldX;
            this.worldY = worldY;
            this.plane = plane;
            this.world = world;
            this.occurredAt = Instant.now().toString();
            this.eventId = UUID.randomUUID().toString();
            this.createdAtMillis = System.currentTimeMillis();
        }

        Map<String, Object> toMap() {
            Map<String, Object> event = new HashMap<>();
            event.put("type", "kill");
            event.put("npcId", npcId);
            event.put("npcName", npcName);
            event.put("worldX", worldX);
            event.put("worldY", worldY);
            event.put("plane", plane);
            event.put("world", world);
            event.put("occurredAt", occurredAt);
            event.put("eventId", eventId);
            if (loot != null) {
                event.put("loot", loot);
            }
            if (accountKc != null) {
                event.put("accountKc", accountKc);
            }
            if (subKills != null) {
                event.put("subKills", subKills);
            }
            if (delveLevel != null) {
                event.put("delveLevel", delveLevel);
            }
            return event;
        }
    }

    public synchronized void onKill(String playerName, int npcId, String npcName, int worldX, int worldY, int plane, int world) {
        owner = playerName;
        PendingKill kill = new PendingKill(npcId, npcName, worldX, worldY, plane, world);
        // Claim the oldest same-name loot that arrived before this despawn, if any (see class doc).
        for (int i = 0; i < pendingUnmatchedLoot.size(); i++) {
            UnmatchedLoot loot = pendingUnmatchedLoot.get(i);
            if (loot.npcName.equals(npcName)) {
                kill.loot = loot.items;
                pendingUnmatchedLoot.remove(i);
                break;
            }
        }
        // Same correlation for a "Your X kill count is: N." chat line that beat the despawn.
        for (int i = 0; i < pendingUnmatchedKc.size(); i++) {
            UnmatchedKc kc = pendingUnmatchedKc.get(i);
            if (kc.npcName.equals(npcName)) {
                kill.accountKc = kc.accountKc;
                pendingUnmatchedKc.remove(i);
                break;
            }
        }
        pendingKills.add(kill);
    }

    /**
     * Like {@link #onKill}, but for a combo kill synthesized by {@link ComboKillEvents} once its
     * shared reward chest is looted (e.g. "Barrows", "Moons of Peril") - {@code npcName} is the
     * combo's own synthetic name, not a real despawned NPC, and {@code subKills} names whichever
     * sub-bosses were actually killed that run. The caller must immediately follow this with
     * {@link #onLoot} for the same {@code npcName} so the chest's loot attaches, exactly like an
     * ordinary kill.
     */
    public synchronized void onComboKill(String playerName, int npcId, String npcName, List<String> subKills,
                                          int worldX, int worldY, int plane, int world) {
        onKill(playerName, npcId, npcName, worldX, worldY, plane, world);
        pendingKills.get(pendingKills.size() - 1).subKills = subKills;
    }

    /**
     * Like {@link #onKill}, but for the single synthesized "Doom of Mokhaiotl" kill created once
     * the player claims rewards and leaves the delve (see
     * {@code GroupScapeTrackerPlugin#claimDoomOfMokhaiotlKill}) - despawns at each individual
     * delve level are never queued as their own kills, so only this one entry is ever shipped per
     * delve run. {@code delveLevel} is the level reached when rewards were claimed, or
     * {@code null} if it couldn't be read from the reward widget.
     */
    public synchronized void onDoomOfMokhaiotlKill(String playerName, int npcId, String npcName, Integer delveLevel,
                                                    int worldX, int worldY, int plane, int world) {
        onKill(playerName, npcId, npcName, worldX, worldY, plane, world);
        pendingKills.get(pendingKills.size() - 1).delveLevel = delveLevel;
    }

    /**
     * Attaches loot to the most recently-queued pending kill for this NPC name, merging into
     * any loot already attached rather than requiring the kill to still be loot-less. Some
     * bosses (e.g. Vet'ion, whose mid-fight transform splits its reward across multiple loot
     * table rolls) fire {@code LootReceived} more than once for a single kill; requiring
     * {@code kill.loot == null} would route that second batch to {@link #pendingUnmatchedLoot}
     * as if it belonged to a future kill, where it would only be reclaimed by another kill of
     * the same NPC name - silently losing the loot (and the items in it) otherwise. Matching by
     * name (not id) since {@code LootReceived} exposes the NPC's composition name, not
     * necessarily the same id {@code NpcDespawned} reported for multi-form bosses.
     */
    public synchronized void onLoot(String npcName, List<Map<String, Object>> items) {
        for (int i = pendingKills.size() - 1; i >= 0; i--) {
            PendingKill kill = pendingKills.get(i);
            if (kill.npcName.equals(npcName)) {
                if (kill.loot == null) {
                    kill.loot = new ArrayList<>(items);
                } else {
                    kill.loot.addAll(items);
                }
                return;
            }
        }
        // No matching pending kill yet - buffer it for onKill to claim once the despawn fires.
        if (pendingUnmatchedLoot.size() >= MAX_UNMATCHED_LOOT) {
            pendingUnmatchedLoot.remove(0);
        }
        pendingUnmatchedLoot.add(new UnmatchedLoot(npcName, items));
    }

    /**
     * Attaches the account's real in-game kill count (parsed from the "Your X kill count is: N."
     * chat line) to the most recently-queued still-unattached pending kill for this NPC name -
     * this is the authoritative KC a Discord kill notification should show, not a count of kills
     * this server happened to see logged. Mirrors {@link #onLoot}'s correlation: the chat line
     * can arrive either before or after {@code NpcDespawned}, so an unmatched one is buffered for
     * {@link #onKill} to claim.
     */
    public synchronized void onKillCount(String npcName, int accountKc) {
        for (int i = pendingKills.size() - 1; i >= 0; i--) {
            PendingKill kill = pendingKills.get(i);
            if (kill.npcName.equals(npcName) && kill.accountKc == null) {
                kill.accountKc = accountKc;
                return;
            }
        }
        if (pendingUnmatchedKc.size() >= MAX_UNMATCHED_KC) {
            pendingUnmatchedKc.remove(0);
        }
        pendingUnmatchedKc.add(new UnmatchedKc(npcName, accountKc));
    }

    /**
     * Queues a standalone chest/instance reward or clue casket opening - unlike {@link #onKill}/
     * {@link #onLoot}, there's no correlation step: the {@code LootReceived} for one of these
     * sources is itself the terminal, complete event.
     *
     * @param sourceType "chest" or "clue"
     * @param clueTier   "beginner".."master" when {@code sourceType} is "clue", else {@code null}
     */
    public synchronized void onChestOrClueLoot(String playerName, String sourceType, String sourceName, String clueTier,
                                                int worldX, int worldY, int plane, int world,
                                                List<Map<String, Object>> items) {
        owner = playerName;
        Map<String, Object> loot = new HashMap<>();
        loot.put("type", "loot");
        loot.put("sourceType", sourceType);
        loot.put("sourceName", sourceName);
        if (clueTier != null) {
            loot.put("clueTier", clueTier);
        }
        loot.put("worldX", worldX);
        loot.put("worldY", worldY);
        loot.put("plane", plane);
        loot.put("world", world);
        loot.put("occurredAt", Instant.now().toString());
        loot.put("eventId", UUID.randomUUID().toString());
        loot.put("loot", items);
        pendingLoot.add(loot);
    }

    /**
     * @param doomDelveLevel the Doom of Mokhaiotl delve level the player was on when they died,
     *                       read live from {@code VarPlayerID.DOM_CURRENT_LEVEL_TEMP} at death
     *                       time (see {@code GroupScapeTrackerPlugin#onActorDeath}) - {@code null}
     *                       outside a delve run.
     */
    public synchronized void onDeath(String playerName, int worldX, int worldY, int plane, int world,
                                      String killerName, Integer doomDelveLevel) {
        owner = playerName;
        Map<String, Object> death = new HashMap<>();
        death.put("type", "death");
        death.put("worldX", worldX);
        death.put("worldY", worldY);
        death.put("plane", plane);
        death.put("world", world);
        death.put("occurredAt", Instant.now().toString());
        death.put("eventId", UUID.randomUUID().toString());
        if (killerName != null) {
            death.put("killerName", killerName);
        }
        if (doomDelveLevel != null) {
            death.put("doomDelveLevel", doomDelveLevel);
        }
        pendingDeaths.add(death);
    }

    public synchronized void consumeState(Map<String, Object> output) {
        if (pendingKills.isEmpty() && pendingDeaths.isEmpty() && pendingLoot.isEmpty()) return;

        // If the owner doesn't match this flush's target, leave pending events untouched so
        // they're retried on a later consumeState() call instead of being silently dropped -
        // a mismatch here (e.g. a transient local-player-name hiccup around a death/teleport)
        // used to fall through to the clear below with nothing ever attached to output.
        String whoIsUpdating = (String) output.get("name");
        if (owner == null || !owner.equals(whoIsUpdating)) return;

        // Loot-less kills younger than LOOT_GRACE_MILLIS are held back (see class doc) rather
        // than shipped immediately, giving a late LootReceived a chance to still attach.
        long now = System.currentTimeMillis();
        List<PendingKill> readyKills = new ArrayList<>();
        List<PendingKill> stillWaiting = new ArrayList<>();
        for (PendingKill kill : pendingKills) {
            if (kill.loot != null || now - kill.createdAtMillis >= LOOT_GRACE_MILLIS) {
                readyKills.add(kill);
            } else {
                stillWaiting.add(kill);
            }
        }

        if (readyKills.isEmpty() && pendingDeaths.isEmpty() && pendingLoot.isEmpty()) return;

        List<Map<String, Object>> events = new ArrayList<>();
        for (PendingKill kill : readyKills) {
            events.add(kill.toMap());
        }
        events.addAll(pendingDeaths);
        events.addAll(pendingLoot);
        output.put("events", events);

        consumedKills = readyKills.isEmpty() ? null : new ArrayList<>(readyKills);
        consumedDeaths = pendingDeaths.isEmpty() ? null : new ArrayList<>(pendingDeaths);
        consumedLoot = pendingLoot.isEmpty() ? null : new ArrayList<>(pendingLoot);
        consumedOwner = owner;
        pendingKills.clear();
        pendingKills.addAll(stillWaiting);
        pendingDeaths.clear();
        pendingLoot.clear();
        // Only release the owner gate once nothing of this player's is left pending - a still-
        // waiting kill needs owner to keep matching whoIsUpdating on the next consumeState call,
        // otherwise it would get stuck here forever (onKill is the only other thing that sets it).
        if (stillWaiting.isEmpty()) {
            owner = null;
        }
    }

    public synchronized void restoreState() {
        if (consumedKills == null && consumedDeaths == null && consumedLoot == null) return;

        if (consumedKills != null) {
            pendingKills.addAll(0, consumedKills);
        }
        if (consumedDeaths != null) {
            pendingDeaths.addAll(0, consumedDeaths);
        }
        if (consumedLoot != null) {
            pendingLoot.addAll(0, consumedLoot);
        }
        if (owner == null) {
            owner = consumedOwner;
        }
        consumedKills = null;
        consumedDeaths = null;
        consumedLoot = null;
        consumedOwner = null;
    }
}

package com.groupscape;

import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

public class LocationState implements ConsumableState {
    @Getter
    private final int x;
    @Getter
    private final int y;
    @Getter
    private final int plane;
    private transient final int world;
    @Getter
    private transient final boolean isOnBoat;
    private transient final String playerName;

    LocationState(String playerName, WorldPoint worldPoint, boolean isOnBoat) {
        this(playerName, worldPoint, isOnBoat, 0);
    }

    LocationState(String playerName, WorldPoint worldPoint, boolean isOnBoat, int world) {
        this.playerName = playerName;
        x = worldPoint.getX();
        y = worldPoint.getY();
        plane = worldPoint.getPlane();
        this.world = world;
        this.isOnBoat = isOnBoat;
    }

    @Override
    public Object get() {
        return new int[] { x, y, plane, isOnBoat ? 1 : 0, world };
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof LocationState)) return false;

        LocationState other = (LocationState) o;
        return (x == other.x) && (y == other.y) && (plane == other.plane) && (isOnBoat == other.isOnBoat);
    }

    @Override
    public String toString() {
        return String.format("{ x: %d, y: %d, plane: %d, isOnBoat: %b }", x, y, plane, isOnBoat);
    }
}

package com.groupscape;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import net.runelite.api.Model;
import net.runelite.api.TextureProvider;

/**
 * Exports a live {@link Model} (e.g. {@code player.getModel()}) as a real binary-little-endian
 * PLY (Stanford Polygon File Format) mesh, so the webapp can load it with three.js's stock
 * {@code PLYLoader} without a custom parser.
 *
 * <p>Each triangle's 3 corners are written as their own vertices (no shared-vertex indexing) so
 * each corner can carry its own per-face-corner color straight from {@link Model#getFaceColors1()}
 * /2/3 — {@code Model}'s per-face colors don't agree at shared vertices, so deduplicating would
 * need averaging/smoothing this export doesn't attempt. Cheap trade for a player-model-sized mesh
 * (a few hundred to low-thousands of faces).
 */
public final class ModelExporter {
    private ModelExporter() {
    }

    /**
     * @param textureProvider used to resolve a representative color for textured faces (no
     *                        per-vertex color exists for those, per {@link Model#getFaceColors1()}'s
     *                        contract) — pass {@code null} to fall back to a flat gray for them.
     */
    public static byte[] toBytes(Model model, TextureProvider textureProvider) {
        int rawFaceCount = model.getFaceCount();
        float[] x = model.getVerticesX();
        float[] y = model.getVerticesY();
        float[] z = model.getVerticesZ();
        int[] indices1 = model.getFaceIndices1();
        int[] indices2 = model.getFaceIndices2();
        int[] indices3 = model.getFaceIndices3();
        int[] colors1 = model.getFaceColors1();
        int[] colors2 = model.getFaceColors2();
        int[] colors3 = model.getFaceColors3();
        short[] textures = model.getFaceTextures();

        // colors3[face] doubles as a sentinel: HIDDEN_FACE marks a face the game never draws
        // (not a color at all — decoding it as one paints a stray near-white triangle over the
        // model), so it's filtered out before sizing the PLY buffers rather than skipped in place.
        int faceCount = 0;
        for (int face = 0; face < rawFaceCount; face++) {
            if (colors3[face] != HIDDEN_FACE) {
                faceCount++;
            }
        }

        int vertexCount = faceCount * 3;
        ByteBuffer body = ByteBuffer.allocate(vertexCount * VERTEX_RECORD_BYTES + faceCount * FACE_RECORD_BYTES);
        body.order(ByteOrder.LITTLE_ENDIAN);

        for (int face = 0; face < rawFaceCount; face++) {
            if (colors3[face] == HIDDEN_FACE) {
                continue;
            }

            boolean textured = textures != null && face < textures.length && textures[face] != -1;
            // FLAT_SHADED means this face has one color for all three corners, carried in
            // colors1 — colors3 itself holds the sentinel, not a corner color, for that case.
            boolean flat = colors3[face] == FLAT_SHADED;
            writeVertex(body, x[indices1[face]], y[indices1[face]], z[indices1[face]],
                    resolveColor(textured, colors1[face], textures, face, textureProvider));
            writeVertex(body, x[indices2[face]], y[indices2[face]], z[indices2[face]],
                    resolveColor(textured, flat ? colors1[face] : colors2[face], textures, face, textureProvider));
            writeVertex(body, x[indices3[face]], y[indices3[face]], z[indices3[face]],
                    resolveColor(textured, flat ? colors1[face] : colors3[face], textures, face, textureProvider));
        }

        int base = 0;
        for (int face = 0; face < rawFaceCount; face++) {
            if (colors3[face] == HIDDEN_FACE) {
                continue;
            }
            body.put((byte) 3);
            body.putInt(base);
            body.putInt(base + 1);
            body.putInt(base + 2);
            base += 3;
        }

        try {
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            out.write(header(vertexCount, faceCount).getBytes(StandardCharsets.US_ASCII));
            out.write(body.array());
            return out.toByteArray();
        } catch (IOException e) {
            // ByteArrayOutputStream never actually throws — satisfy the checked signature.
            throw new UncheckedIOException(e);
        }
    }

    private static final int VERTEX_RECORD_BYTES = 3 * Float.BYTES + 3; // x,y,z floats + r,g,b bytes
    private static final int FACE_RECORD_BYTES = 1 + 3 * Integer.BYTES; // list-count byte + 3 vertex indices

    private static String header(int vertexCount, int faceCount) {
        return "ply\n"
                + "format binary_little_endian 1.0\n"
                + "comment GroupScape character portrait export\n"
                + "element vertex " + vertexCount + "\n"
                + "property float x\n"
                + "property float y\n"
                + "property float z\n"
                + "property uchar red\n"
                + "property uchar green\n"
                + "property uchar blue\n"
                + "element face " + faceCount + "\n"
                + "property list uchar int vertex_indices\n"
                + "end_header\n";
    }

    private static void writeVertex(ByteBuffer body, float vx, float vy, float vz, int[] rgb) {
        body.putFloat(vx);
        body.putFloat(vy);
        body.putFloat(vz);
        body.put((byte) rgb[0]);
        body.put((byte) rgb[1]);
        body.put((byte) rgb[2]);
    }

    private static int[] resolveColor(boolean textured, int packedHsl, short[] textures, int face, TextureProvider textureProvider) {
        if (!textured) {
            return jagexHslToRgb(packedHsl);
        }
        if (textureProvider != null) {
            return jagexHslToRgb(textureProvider.getDefaultColor(textures[face]));
        }
        return new int[]{128, 128, 128};
    }

    /** colors3[face] sentinel: this face has one flat color for all 3 corners, carried in colors1. */
    private static final int FLAT_SHADED = -1;
    /** colors3[face] sentinel: the game never draws this face at all — not a color to decode. */
    private static final int HIDDEN_FACE = -2;

    /**
     * Gamma the game's own HSL-to-RGB conversion applies after the standard math, confirmed
     * against {@code JagexColor.adjustForBrightness}. Without it, colors decode noticeably darker
     * than the client actually renders them — many mid-range luminance indices (skin tones,
     * cloth) are authored assuming this brightening pass runs, and skipping it makes captured
     * models look close to solid black.
     */
    private static final double BRIGHTNESS_GAMMA = 0.9;
    private static final double HUE_BIN_OFFSET = 0.5 / 64.0;
    private static final double SATURATION_BIN_OFFSET = 0.5 / 8.0;

    /**
     * Jagex's packed HSL: bits 10-15 hue (0-63), bits 7-9 saturation (0-7), bits 0-6 luminance
     * (0-127) — bit layout confirmed against {@code net.runelite.api.JagexColor}'s pack/unpack
     * methods. The hue/saturation bin-center offsets, the luminance-by-128 (not 127) denominator,
     * and the post-conversion gamma all mirror the client's own conversion rather than a plain
     * textbook HSL-to-RGB — those details are what previously produced overly dark colors.
     */
    static int[] jagexHslToRgb(int packed) {
        int hue = (packed >> 10) & 0x3F;
        int saturation = (packed >> 7) & 0x7;
        int luminance = packed & 0x7F;

        double h = hue / 64.0 + HUE_BIN_OFFSET;
        double s = saturation / 8.0 + SATURATION_BIN_OFFSET;
        double l = luminance / 128.0;

        double chroma = (1 - Math.abs(2 * l - 1)) * s;
        double x = chroma * (1 - Math.abs((h * 6) % 2 - 1));
        double m = l - chroma / 2;

        double r = m;
        double g = m;
        double b = m;
        switch ((int) (h * 6)) {
            case 0:
                r += chroma;
                g += x;
                break;
            case 1:
                g += chroma;
                r += x;
                break;
            case 2:
                g += chroma;
                b += x;
                break;
            case 3:
                b += chroma;
                g += x;
                break;
            case 4:
                b += chroma;
                r += x;
                break;
            default:
                r += chroma;
                b += x;
                break;
        }

        return new int[]{adjustForBrightness(r), adjustForBrightness(g), adjustForBrightness(b)};
    }

    private static int adjustForBrightness(double component) {
        double clamped = Math.max(0, Math.min(1, component));
        return (int) Math.round(Math.pow(clamped, BRIGHTNESS_GAMMA) * 255.0);
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Drops whose total GE value crosses {@link GroupScapeTrackerConfig#notableDropThreshold()} are
 * discrete events like {@link AlertEvents}, not per-tick snapshot data - this accumulates them
 * into a list and drains everything buffered since the last upload into the "notableDrops" key
 * on the next {@code consumeState}, mirroring {@link AlertEvents}' accumulator pattern. Must
 * only be touched from the client thread.
 */
public class NotableDropEvents {
    private final List<Map<String, Object>> pending = new ArrayList<>();
    private String owner;

    private List<Map<String, Object>> consumed;
    private String consumedOwner;

    public synchronized void onNotableDrop(String playerName, String sourceType, String sourceName,
                                            int itemId, String itemName, long itemValue, long totalValue) {
        owner = playerName;
        Map<String, Object> event = new HashMap<>();
        event.put("sourceType", sourceType);
        event.put("sourceName", sourceName);
        event.put("itemId", itemId);
        event.put("itemName", itemName);
        event.put("itemValue", itemValue);
        event.put("totalValue", totalValue);
        pending.add(event);
    }

    public synchronized void consumeState(Map<String, Object> output) {
        if (pending.isEmpty()) return;

        String whoIsUpdating = (String) output.get("name");
        if (owner != null && owner.equals(whoIsUpdating)) {
            output.put("notable_drops", new ArrayList<>(pending));
        }

        consumed = new ArrayList<>(pending);
        consumedOwner = owner;
        pending.clear();
        owner = null;
    }

    public synchronized void restoreState() {
        if (consumed == null) return;

        pending.addAll(0, consumed);
        if (owner == null) {
            owner = consumedOwner;
        }
        consumed = null;
        consumedOwner = null;
    }
}

package com.groupscape;

/**
 * {@code Actor.getInteracting()} only reports an NPC target during the walk-up/click moment -
 * once the dialogue box is actually open and the conversation is under way, it goes back to
 * null. Without this, both rich presence ("Talking to X") and dialogue interaction events would
 * drop the instant the chat box opened, which is the opposite of what they should show. Remembers
 * the last NPC actually interacted with and keeps reporting it for as long as the dialogue widget
 * stays open, clearing the moment it closes. Ported from groupscape-old. Must only be touched from
 * the client thread.
 */
public class NpcDialogueTracker {
    private Integer lastNpcId;
    private String lastNpcName;
    private int lastCombatLevel;

    /** Called whenever {@code getInteracting()} currently reports an NPC target. */
    public void observe(int npcId, String npcName, int combatLevel) {
        lastNpcId = npcId;
        lastNpcName = npcName;
        lastCombatLevel = combatLevel;
    }

    /** Called once the dialogue widget is no longer open and there's no live NPC target. */
    public void clear() {
        lastNpcId = null;
        lastNpcName = null;
        lastCombatLevel = 0;
    }

    public Integer lastNpcId() {
        return lastNpcId;
    }

    public String lastNpcName() {
        return lastNpcName;
    }

    public int lastCombatLevel() {
        return lastCombatLevel;
    }
}

