package com.groupscape;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class PluginVersion {
    private static final String VERSION = loadVersion();

    public static String get() {
        return VERSION;
    }

    private static String loadVersion() {
        Properties props = new Properties();
        try (InputStream is = PluginVersion.class.getResourceAsStream("/com/groupscape/version.properties")) {
            if (is != null) {
                props.load(is);
                return props.getProperty("version", "unknown");
            }
        } catch (IOException e) {
            log.warn("Failed to load plugin version", e);
        }
        return "unknown";
    }

    private PluginVersion() {
    }
}

package com.groupscape;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.Player;

/**
 * Drives the character portrait mesh capture — login, equipment change, plus a periodic backstop
 * (wired by {@link GroupScapeTrackerPlugin}). Capture always happens on the client thread, since
 * every trigger it's called from (event subscribers, non-async scheduled methods) is already on
 * it — same assumption the rest of this plugin's state readers make.
 */
@Slf4j
@Singleton
public class PortraitCaptureManager {
    @Inject
    private Client client;

    @Inject
    private DataManager dataManager;

    public void onLogin() {
        capture();
    }

    public void onEquipmentSynced() {
        capture();
    }

    public void captureIfLoggedIn() {
        if (client.getGameState() == GameState.LOGGED_IN) {
            capture();
        }
    }

    private void capture() {
        if (client.getGameState() != GameState.LOGGED_IN) {
            return;
        }

        Player local = client.getLocalPlayer();
        if (local == null) {
            return;
        }

        Model model = local.getModel();
        if (model == null) {
            // Momentarily unavailable right after login/teleport; the next trigger catches it.
            return;
        }

        byte[] mesh = ModelExporter.toBytes(model, client.getTextureProvider());
        log.debug("GroupScape portrait captured: {} bytes", mesh.length);
        dataManager.uploadPortrait(mesh);
    }
}

package com.groupscape;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.client.game.ItemManager;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class PotionStorageState implements ConsumableState {
    private final List<ItemContainerItem> items;
    private final transient String playerName;

    private PotionStorageState(String playerName, List<ItemContainerItem> items) {
        this.playerName = playerName;
        this.items = items;
    }

    public static PotionStorageState fromClient(String playerName, Client client, ItemManager itemManager) {
        List<ItemContainerItem> items = new ArrayList<>();

        for (EnumComposition e : new EnumComposition[]{
            client.getEnum(EnumID.POTIONSTORE_POTIONS),
            client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS)
        }) {
            if (e == null) continue;

            for (int potionEnumId : e.getIntVals()) {
                EnumComposition potionEnum = client.getEnum(potionEnumId);
                if (potionEnum == null) continue;

                client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
                int doses = client.getIntStack()[0];

                if (doses > 0) {
                    // Canonicalize the 1-dose variant's item ID so the potion type has a
                    // consistent identifier regardless of how many doses are currently stored.
                    int canonicalOneDoseItemId = itemManager.canonicalize(potionEnum.getIntValue(1));
                    if (canonicalOneDoseItemId > 0) {
                        items.add(new ItemContainerItem(canonicalOneDoseItemId, doses));
                    }
                }
            }
        }

        items.sort(Comparator.comparingInt(ItemContainerItem::getId));
        return new PotionStorageState(playerName, items);
    }

    @Override
    public Object get() {
        List<Integer> result = new ArrayList<>(items.size() * 2);
        for (ItemContainerItem item : items) {
            result.add(item.getId());
            result.add(item.getQuantity());
        }
        return result;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof PotionStorageState)) return false;
        PotionStorageState other = (PotionStorageState) o;
        return items.equals(other.items);
    }
}

package com.groupscape;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Prayer;

/**
 * Filters a raw {@code client.isPrayerActive()} scan down to the prayers that should actually be
 * shown. RuneLite's per-prayer varbits don't cleanly separate a base prayer from the curse/upgrade
 * that replaces it in the prayer book (Deadeye over Rigour/Eagle Eye/Hawk Eye/Sharp Eye, Mystic
 * Vigour over Augury/Mystic Might/Mystic Lore/Mystic Will): activating the upgrade reports every
 * prayer in that book column as active at once. Drop a base prayer whenever its listed upgrade is
 * also present in the same raw scan.
 */
public final class PrayerVisibility {
    private static final Map<Prayer, Prayer> BASE_PRAYER_SUPPRESSED_BY_UPGRADE = new EnumMap<>(Prayer.class);

    static {
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.RIGOUR, Prayer.DEADEYE);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.EAGLE_EYE, Prayer.DEADEYE);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.HAWK_EYE, Prayer.DEADEYE);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.SHARP_EYE, Prayer.DEADEYE);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.AUGURY, Prayer.MYSTIC_VIGOUR);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.MYSTIC_MIGHT, Prayer.MYSTIC_VIGOUR);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.MYSTIC_LORE, Prayer.MYSTIC_VIGOUR);
        BASE_PRAYER_SUPPRESSED_BY_UPGRADE.put(Prayer.MYSTIC_WILL, Prayer.MYSTIC_VIGOUR);
    }

    private PrayerVisibility() {
    }

    public static List<String> visible(List<String> rawPrayerNames) {
        if (rawPrayerNames == null || rawPrayerNames.isEmpty()) {
            return Collections.emptyList();
        }

        Set<Prayer> active = EnumSet.noneOf(Prayer.class);
        for (String name : rawPrayerNames) {
            Prayer prayer = parsePrayer(name);
            if (prayer != null) {
                active.add(prayer);
            }
        }

        List<String> visible = new ArrayList<>(rawPrayerNames.size());
        for (String name : rawPrayerNames) {
            Prayer prayer = parsePrayer(name);
            Prayer upgrade = prayer != null ? BASE_PRAYER_SUPPRESSED_BY_UPGRADE.get(prayer) : null;
            if (upgrade != null && active.contains(upgrade)) {
                continue;
            }
            visible.add(name);
        }
        return visible;
    }

    private static Prayer parsePrayer(String prayerName) {
        try {
            return Prayer.valueOf(prayerName);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }
}

package com.groupscape;

import net.runelite.api.Client;
import net.runelite.api.Quest;

import java.util.*;
import java.util.stream.Collectors;

public class QuestState implements ConsumableState {
    private final Map<Integer, net.runelite.api.QuestState> questStateMap;
    private transient final String playerName;
    private List<Integer> sortedQuestIds = Arrays.stream(Quest.values()).map(Quest::getId).sorted().collect(Collectors.toList());

    public QuestState(String playerName, Client client) {
        this.playerName = playerName;
        this.questStateMap = new HashMap<>();
        for (Quest quest : Quest.values()) {
            questStateMap.put(quest.getId(), quest.getState(client));
        }
    }

    @Override
    public Object get() {
        List<Integer> result = new ArrayList<>(questStateMap.size());
        for (Integer questId : sortedQuestIds) {
            result.add(questStateMap.get(questId).ordinal());
        }

        return result;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof QuestState)) return false;

        QuestState other = (QuestState) o;
        for (Quest quest : Quest.values()) {
            Integer questId = quest.getId();
            if (questStateMap.get(questId) != other.questStateMap.get(questId)) {
                return false;
            }
        }

        return true;
    }
}

package com.groupscape;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;

public class QuiverState implements ConsumableState {
    private final ItemContainerItem ammo;
    private final String playerName;

    public QuiverState(String playerName, Client client, ItemManager itemManager) {
        this.playerName = playerName;

        int id = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
        int qty = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
        if (id <= 0 || qty <= 0) {
            this.ammo = new ItemContainerItem(0, 0);
        } else {
            int canonId = itemManager.canonicalize(id);
            this.ammo = new ItemContainerItem(canonId, qty);
        }
    }

    @Override
    public Object get() {
        return new int[] {ammo.getId(), ammo.getQuantity()};
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) {
            return true;
        }

        if (!(o instanceof QuiverState)) {
            return false;
        }

        QuiverState other = (QuiverState) o;

        return this.ammo.equals(other.ammo);
    }
}

package com.groupscape;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Correlates a raid's completion signal (chat message for CoX/ToA, the reward-chest
 * {@code LootReceived} itself for ToB - see {@link GroupScapeTrackerPlugin#onChatMessage}/
 * {@link GroupScapeTrackerPlugin#onLootReceived}) with the reward-chest loot that follows it, and
 * queues one "raid"-typed event per completion for the next upload.
 *
 * The reward-chest {@code LootReceived} is the authoritative completion signal for all three raids
 * (as it always was for ToB, which prints no chat line at all). For CoX/ToA, a chat completion
 * line held in {@link #pendingCox}/{@link #pendingToa} is used only to enrich the event with a
 * difficulty (CoX mode / ToA invocation level) when it arrives within
 * {@link #CORRELATION_WINDOW_MILLIS} of the chest loot - if it doesn't (missed, expired, or the
 * chat pattern fails to match a real completion line), the completion still ships, just with the
 * difficulty left unset/unresolved. This mirrors {@link KillLootDeathEvents}'s pending-kill/loot
 * correlation shape but deliberately does NOT drop the event when only one half shows up, since an
 * unresolved difficulty is a much smaller loss than a raid vanishing from the feed entirely.
 *
 * Drains into the *same* "events" upload key {@link KillLootDeathEvents} owns, so unlike that
 * class this one only ever appends to whatever's already there rather than overwriting it -
 * {@link #consumeState} must run after {@link KillLootDeathEvents#consumeState} in
 * {@link DataManager#submitToApi()}. Must only be touched from the client thread.
 */
public class RaidCompletionEvents {
    private static final long CORRELATION_WINDOW_MILLIS = 30_000;

    /** One of "mode" (CoX/ToB - {@code mode} may be {@code null} for regular difficulty) or
     * "level" (ToA numeric invocation level). */
    public static final class RaidDifficulty {
        final String kind;
        final String mode;
        final int level;

        private RaidDifficulty(String kind, String mode, int level) {
            this.kind = kind;
            this.mode = mode;
            this.level = level;
        }

        public static RaidDifficulty mode(String mode) {
            return new RaidDifficulty("mode", mode, 0);
        }

        public static RaidDifficulty level(int level) {
            return new RaidDifficulty("level", null, level);
        }

        Map<String, Object> toMap() {
            Map<String, Object> map = new HashMap<>();
            map.put("kind", kind);
            if ("mode".equals(kind)) {
                if (mode != null) {
                    map.put("mode", mode);
                }
            } else {
                // Always send level, even when unresolved (-1) - the server model requires this
                // field, so omitting it fails deserialization of the entire heartbeat, not just
                // this raid. The server already treats a negative/unresolved level as its lowest
                // tier and hides it from the display suffix, so -1 is a safe "unknown" sentinel.
                map.put("level", level);
            }
            return map;
        }
    }

    private static final class PendingCompletion {
        final RaidDifficulty difficulty;
        final long detectedAtMillis;

        PendingCompletion(RaidDifficulty difficulty) {
            this.difficulty = difficulty;
            this.detectedAtMillis = System.currentTimeMillis();
        }

        boolean isFresh() {
            return System.currentTimeMillis() - detectedAtMillis <= CORRELATION_WINDOW_MILLIS;
        }
    }

    private PendingCompletion pendingCox;
    private PendingCompletion pendingToa;
    private final List<Map<String, Object>> pendingCompletions = new ArrayList<>();
    private String owner;

    private List<Map<String, Object>> consumedCompletions;
    private String consumedOwner;

    /** Called from {@code onChatMessage} once a CoX/ToA completion line is matched. */
    public synchronized void onChatCompletion(String raidType, RaidDifficulty difficulty) {
        if ("cox".equals(raidType)) {
            pendingCox = new PendingCompletion(difficulty);
        } else if ("toa".equals(raidType)) {
            pendingToa = new PendingCompletion(difficulty);
        }
    }

    /**
     * Called for every {@code LootReceived} whose source name is one of the three raid chests
     * (checked by the caller before {@link ChestLootSourceNames}'s broader chest handling, so
     * raid chests never also reach the standalone chest/clue "loot" event path).
     *
     * @return true if this loot was claimed as a raid completion (caller should also skip the
     * standalone notable-drop check for it, so the same gold isn't reported twice)
     */
    public synchronized boolean onRaidChestLoot(String playerName, String sourceName,
                                                 int worldX, int worldY, int plane, int world,
                                                 List<Map<String, Object>> items) {
        String raidType;
        RaidDifficulty difficulty;
        if ("Theatre of Blood".equals(sourceName)) {
            // ToB prints no chat-completion line at all - the reward chest loot IS the
            // completion signal. Mode is left unset ("regular") since it can't be told apart
            // from Hard Mode without widget parsing this feature doesn't otherwise need -
            // TODO: revisit if ToB Hard Mode distinction turns out to matter to users.
            raidType = "tob";
            difficulty = RaidDifficulty.mode(null);
        } else if ("Chambers of Xeric".equals(sourceName)) {
            raidType = "cox";
            // Chat line is only used to enrich with mode when it landed in time - the chest loot
            // itself is the authoritative completion signal (matches ToB), so a missed/unmatched
            // chat line (e.g. an unexpected wording) no longer drops the completion, just its mode.
            difficulty = (pendingCox != null && pendingCox.isFresh()) ? pendingCox.difficulty : RaidDifficulty.mode(null);
            pendingCox = null;
        } else if ("Tombs of Amascut".equals(sourceName)) {
            raidType = "toa";
            difficulty = (pendingToa != null && pendingToa.isFresh()) ? pendingToa.difficulty : RaidDifficulty.level(-1);
            pendingToa = null;
        } else {
            // Not a raid chest - caller falls back to its normal chest/notable-drop handling.
            return false;
        }

        owner = playerName;
        Map<String, Object> event = new HashMap<>();
        event.put("type", "raid");
        event.put("raidType", raidType);
        event.put("difficulty", difficulty.toMap());
        event.put("worldX", worldX);
        event.put("worldY", worldY);
        event.put("plane", plane);
        event.put("world", world);
        event.put("occurredAt", Instant.now().toString());
        event.put("loot", items);
        pendingCompletions.add(event);
        return true;
    }

    public synchronized void consumeState(Map<String, Object> output) {
        if (pendingCompletions.isEmpty()) return;

        String whoIsUpdating = (String) output.get("name");
        if (owner != null && owner.equals(whoIsUpdating)) {
            // Must append to KillLootDeathEvents' "events" list, not overwrite it - see class doc.
            @SuppressWarnings("unchecked")
            List<Map<String, Object>> events =
                    (List<Map<String, Object>>) output.computeIfAbsent("events", k -> new ArrayList<Map<String, Object>>());
            events.addAll(pendingCompletions);
        }

        consumedCompletions = new ArrayList<>(pendingCompletions);
        consumedOwner = owner;
        pendingCompletions.clear();
        owner = null;
    }

    public synchronized void restoreState() {
        if (consumedCompletions == null) return;

        pendingCompletions.addAll(0, consumedCompletions);
        if (owner == null) {
            owner = consumedOwner;
        }
        consumedCompletions = null;
        consumedOwner = null;
    }
}

package com.groupscape;

import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Skill;

public class ResourcesState implements ConsumableState {
    private static class CurrentMax {
        @Getter
        private final int current;
        @Getter
        private final int max;

        CurrentMax(int current, int max) {
            this.current = current;
            this.max = max;
        }

        @Override
        public boolean equals(Object o) {
            if (o == this) return true;
            if (!(o instanceof CurrentMax)) return false;

            CurrentMax other = (CurrentMax) o;
            return other.getCurrent() == current && other.getMax() == max;
        }
    }

    @Getter
    private final CurrentMax hitpoints;
    @Getter
    private final CurrentMax prayer;
    @Getter
    private final CurrentMax energy;
    @Getter
    int world;
    private transient final String playerName;

    ResourcesState(String playerName, Client client) {
        this.playerName = playerName;
        hitpoints = new CurrentMax(
                client.getBoostedSkillLevel(Skill.HITPOINTS),
                client.getRealSkillLevel(Skill.HITPOINTS)
        );
        prayer = new CurrentMax(
                client.getBoostedSkillLevel(Skill.PRAYER),
                client.getRealSkillLevel(Skill.PRAYER)
        );
        energy = new CurrentMax(
                client.getEnergy(),
                100
        );
        world = client.getWorld();
    }

    @Override
    public Object get() {
        return new int[] {
                hitpoints.current, hitpoints.max,
                prayer.current, prayer.max,
                energy.current, energy.max,
                world
        };
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof ResourcesState)) return false;

        ResourcesState other = (ResourcesState) o;
        return other.world == world && other.hitpoints.equals(hitpoints) && other.prayer.equals(prayer) && other.energy.equals(energy);
    }
}

package com.groupscape;

import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Derives a short human-readable activity string ("Fighting Zulrah", "Talking
 * to Hans", "Browsing the bank") entirely from local Client state, so the
 * party overlay can show it without a server-side NPC/animation lookup table.
 */
public class RichPresenceState implements ConsumableState {
    private final String text;
    private final transient String playerName;

    RichPresenceState(String playerName, Client client, NpcDialogueTracker dialogueTracker) {
        this.playerName = playerName;
        this.text = computeText(client, dialogueTracker);
    }

    /**
     * Exposed so the party overlay can compute the same text for the local player's own row.
     * {@code dialogueTracker} may be null (falls back to the pre-tracker behavior of going idle
     * the instant a dialogue box swallows {@code getInteracting()}'s target).
     */
    public static String computeText(Client client, NpcDialogueTracker dialogueTracker) {
        Player player = client.getLocalPlayer();
        if (player == null) {
            return null;
        }

        Actor interacting = player.getInteracting();
        if (interacting != null) {
            String name = interacting.getName();
            if (name == null) {
                return null;
            }

            int combatLevel = 0;
            if (interacting instanceof NPC) {
                combatLevel = ((NPC) interacting).getCombatLevel();
            } else if (interacting instanceof Player) {
                combatLevel = ((Player) interacting).getCombatLevel();
            }

            return (combatLevel > 0 ? "Fighting " : "Talking to ") + name;
        }

        // getInteracting() has already gone null once the dialogue box is actually open (see
        // NpcDialogueTracker) but the box is still up, so the player is still talking to
        // whoever they last targeted.
        if (dialogueTracker != null && dialogueTracker.lastNpcName() != null) {
            return "Talking to " + dialogueTracker.lastNpcName();
        }

        Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (bankItems != null && !bankItems.isHidden()) {
            return "Browsing the bank";
        }

        return null;
    }

    @Override
    public Object get() {
        return text;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof RichPresenceState)) return false;

        RichPresenceState other = (RichPresenceState) o;
        return text == null ? other.text == null : text.equals(other.text);
    }
}

package com.groupscape;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.gameval.VarbitID;

public class RunePouchState implements ConsumableState {
    private final ItemContainerItem rune1;
    private final ItemContainerItem rune2;
    private final ItemContainerItem rune3;
    private final ItemContainerItem rune4;
    private final transient String playerName;

    public RunePouchState(String playerName, Client client) {
        this.playerName = playerName;
        final EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
        rune1 = itemForRune(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1), client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1), runepouchEnum);
        rune2 = itemForRune(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2), client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_2), runepouchEnum);
        rune3 = itemForRune(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_3), client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_3), runepouchEnum);
        rune4 = itemForRune(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_4), client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_4), runepouchEnum);
    }

    private ItemContainerItem itemForRune(int runeId, int amount, EnumComposition runepouchEnum) {
        return new ItemContainerItem(runepouchEnum.getIntValue(runeId), amount);
    }

    @Override
    public Object get() {
        return new int[] {
                rune1.getId(), rune1.getQuantity(),
                rune2.getId(), rune2.getQuantity(),
                rune3.getId(), rune3.getQuantity(),
                rune4.getId(), rune4.getQuantity()
        };
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof RunePouchState)) return false;
        RunePouchState other = (RunePouchState) o;

        return rune1.equals(other.rune1) && rune2.equals(other.rune2) && rune3.equals(other.rune3) && rune4.equals(other.rune4);
    }
}

package com.groupscape;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;

import java.util.*;

@Slf4j
public class SkillState implements ConsumableState {
    private final Map<String, Integer> skillXpMap;
    private transient final String playerName;

    public SkillState(String playerName, Client client) {
        this.playerName = playerName;
        skillXpMap = new HashMap<>();
        for (Skill skill : Skill.values()) {
            skillXpMap.put(skill.getName(), client.getSkillExperience(skill));
        }
    }

    @Override
    public Object get() {
        return new int[] {
                skillXpMap.get("Agility"),
                skillXpMap.get("Attack"),
                skillXpMap.get("Construction"),
                skillXpMap.get("Cooking"),
                skillXpMap.get("Crafting"),
                skillXpMap.get("Defence"),
                skillXpMap.get("Farming"),
                skillXpMap.get("Firemaking"),
                skillXpMap.get("Fishing"),
                skillXpMap.get("Fletching"),
                skillXpMap.get("Herblore"),
                skillXpMap.get("Hitpoints"),
                skillXpMap.get("Hunter"),
                skillXpMap.get("Magic"),
                skillXpMap.get("Mining"),
                skillXpMap.get("Prayer"),
                skillXpMap.get("Ranged"),
                skillXpMap.get("Runecraft"),
                skillXpMap.get("Slayer"),
                skillXpMap.get("Smithing"),
                skillXpMap.get("Strength"),
                skillXpMap.get("Thieving"),
                skillXpMap.get("Woodcutting"),
                skillXpMap.get("Sailing")
        };
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof SkillState)) return false;

        SkillState other = (SkillState) o;
        for (Skill skill : Skill.values()) {
            String skillName = skill.getName();
            if (!skillXpMap.get(skillName).equals(other.skillXpMap.get(skillName))) return false;
        }

        return true;
    }
}

package com.groupscape;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * Slayer task assignment/close events for the web site's slayer History/Stats tabs - a discrete
 * event stream like {@link NotableDropEvents}, not per-tick snapshot data (that's still
 * {@link SlayerTaskState}/{@code slayer_task}), so it mirrors that accumulator's
 * pending/consumed/restore pattern rather than {@link ConsumableState}'s latest-value-wins one.
 *
 * <p>Each task assignment gets one stable {@code clientEventId} (a fresh {@link UUID}, minted by
 * {@link #onTaskAssigned}), reused by the later {@link #onTaskClosed} call for that same task so
 * the server can upsert one history row per task instead of writing two. Must only be touched
 * from the client thread.
 */
public class SlayerTaskCloseEvents {
    private final List<Map<String, Object>> pending = new ArrayList<>();
    private String owner;

    private List<Map<String, Object>> consumed;
    private String consumedOwner;

    public synchronized String onTaskAssigned(String playerName, String clientEventId, String taskName,
                                               String masterName, int amountTotal, String modifierType,
                                               Integer modifierValue, Boolean modifierNegative) {
        owner = playerName;
        Map<String, Object> event = new HashMap<>();
        event.put("clientEventId", clientEventId);
        event.put("taskName", taskName);
        event.put("masterName", masterName);
        event.put("status", amountTotal > 0 ? "in_progress" : "not_started");
        event.put("amountDone", 0);
        event.put("amountTotal", amountTotal);
        event.put("assignedAt", Instant.now().toString());
        // Fixed for the task's whole lifecycle - not re-sent by onTaskClosed, so the history row
        // keeps whatever this assignment set even though the close event's upsert doesn't touch
        // these columns (see db::upsert_slayer_task_history_event).
        if (modifierType != null) {
            event.put("modifierType", modifierType);
            event.put("modifierValue", modifierValue);
            event.put("modifierNegative", modifierNegative);
        }
        pending.add(event);
        return clientEventId;
    }

    public synchronized void onTaskClosed(String playerName, String clientEventId, String taskName,
                                           String masterName, String status, int amountDone,
                                           int amountTotal, Integer points, String assignedAt) {
        owner = playerName;
        Map<String, Object> event = new HashMap<>();
        event.put("clientEventId", clientEventId);
        event.put("taskName", taskName);
        event.put("masterName", masterName);
        event.put("status", status);
        event.put("amountDone", amountDone);
        event.put("amountTotal", amountTotal);
        if (points != null) {
            event.put("points", points);
        }
        event.put("assignedAt", assignedAt);
        event.put("closedAt", Instant.now().toString());
        pending.add(event);
    }

    public static String newClientEventId() {
        return UUID.randomUUID().toString();
    }

    public synchronized void consumeState(Map<String, Object> output) {
        if (pending.isEmpty()) return;

        String whoIsUpdating = (String) output.get("name");
        if (owner != null && owner.equals(whoIsUpdating)) {
            output.put("slayer_task_events", new ArrayList<>(pending));
        }

        consumed = new ArrayList<>(pending);
        consumedOwner = owner;
        pending.clear();
        owner = null;
    }

    public synchronized void restoreState() {
        if (consumed == null) return;

        pending.addAll(0, consumed);
        if (owner == null) {
            owner = consumedOwner;
        }
        consumed = null;
        consumedOwner = null;
    }
}

package com.groupscape;

import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Current slayer task, read passively off client varps/varbits - no slayer log or task widget
 * needs to be open. {@code VarPlayerID#SLAYER_TARGET} is the task id (0/negative both observed
 * as "no task assigned", e.g. between turning in a task and getting a new one); task name and
 * area name are looked up from the game's own DB tables rather than shipping a static id->name
 * table here, the same way RuneLite core's SlayerPlugin resolves them.
 *
 * <p>There is no varbit or DB row that names the assigning master directly - {@code
 * VarbitID#SLAYER_MASTER} is a small ordinal (used only to pick which "tasks completed" counter
 * applies, see the streak switch below), not an index into a master list. The master name is
 * instead captured passively from NPC dialogue text elsewhere (see
 * {@code GroupScapeTrackerPlugin#captureSlayerTaskMasterDialogue}) and snapshotted into {@code
 * masterName} by the caller whenever {@code SLAYER_TARGET}/{@code SLAYER_COUNT_ORIGINAL} change -
 * i.e. a new task was just assigned - or immediately whenever the player talks to a recognized
 * slayer master (including just rechecking an existing task), so a plugin/client restart mid-task
 * only leaves {@code masterName} null until the next such conversation, not until the next
 * reassignment.
 */
public class SlayerTaskState implements ConsumableState {
    private final transient String playerName;
    private final boolean hasTask;
    private final String masterName;
    private final String taskName;
    private final String taskLocation;
    private final int amountRemaining;
    private final int initialAmount;
    private final int points;
    private final int streak;

    /**
     * Mortimer's task modifier, resolved from the raw {@code SLAYER_MODIFIER_ID}/{@code
     * SLAYER_MODIFIER_VALUE}/{@code SLAYER_MODIFIER_NEGATIVE} varbits - {@code null} when no
     * modifier is active. Ids confirmed against the game's own decompiled interface script
     * (`slayer_modifiername_rewardshop`/script9747, which renders this same id/value pair into
     * Mortimer's assignment text) - see {@link #resolveModifierType}.
     */
    private final String modifierType;
    private final Integer modifierValue;
    private final Boolean modifierNegative;

    private final int taskId;

    public SlayerTaskState(String playerName, Client client, String masterName) {
        this(playerName, client, masterName, null);
    }

    /**
     * @param previous the last state successfully pushed for this player, or null. The DB-row
     * lookups in {@link #resolveTaskName} and {@link #resolveAreaName} can transiently come back
     * empty for a real, currently-assigned task (RuneLite core's own SlayerPlugin sees the same
     * thing and simply skips the update that tick rather than clobbering its last-known name -
     * ported here as falling back to {@code previous}'s name/location when the id being resolved
     * hasn't changed, since this class always rebuilds a full immutable snapshot rather than
     * patching one in place).
     */
    public SlayerTaskState(String playerName, Client client, String masterName, SlayerTaskState previous) {
        this.playerName = playerName;

        int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
        this.taskId = taskId;
        this.hasTask = taskId > 0;
        this.amountRemaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        this.points = client.getVarbitValue(VarbitID.SLAYER_POINTS);

        // Mortimer (and possibly other masters) can modify the assigned count up or down (e.g.
        // "+65 kills") via SLAYER_MODIFIER_ID == 2; SLAYER_COUNT_ORIGINAL alone only reflects the
        // pre-modifier base amount, but SLAYER_COUNT (remaining) already accounts for the modifier,
        // so only the initial/total needs adjusting here. Ported from RuneLite core's SlayerPlugin.
        int initialAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
        int rawModifierId = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID);
        boolean rawModifierNegative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
        int rawModifierValue = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
        if (rawModifierId == 2) {
            initialAmount += rawModifierNegative ? -rawModifierValue : rawModifierValue;
        }
        this.initialAmount = initialAmount;

        this.modifierType = resolveModifierType(rawModifierId);
        this.modifierValue = modifierType != null ? rawModifierValue : null;
        this.modifierNegative = modifierType != null ? rawModifierNegative : null;

        // Krystilia (wilderness) and Mortimer (Managing Miscellania hard diary reward) keep their
        // own separate "tasks completed" counters instead of feeding the regular one - ported
        // 1:1 from RuneLite core's SlayerPlugin streak logic.
        int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
        switch (master) {
            case 7:
                this.streak = client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
                break;
            case 10:
                this.streak = client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
                break;
            default:
                this.streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
                break;
        }

        if (hasTask) {
            boolean samePreviousTask = previous != null && previous.hasTask && previous.taskId == taskId;

            this.masterName = masterName != null
                    ? masterName
                    : (samePreviousTask ? previous.masterName : resolveMasterNameFromOrdinal(master));

            String resolvedTaskName = resolveTaskName(client, taskId);
            this.taskName = resolvedTaskName != null
                    ? resolvedTaskName
                    : (samePreviousTask ? previous.taskName : null);

            int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
            String resolvedAreaName = resolveAreaName(client, areaId);
            this.taskLocation = resolvedAreaName != null
                    ? resolvedAreaName
                    : (samePreviousTask ? previous.taskLocation : null);
        } else {
            this.masterName = null;
            this.taskName = null;
            this.taskLocation = null;
        }
    }

    /** See {@link #modifierType}'s javadoc. */
    private static String resolveModifierType(int modifierId) {
        switch (modifierId) {
            case 1:
                return "points";
            case 2:
                return "quantity";
            case 3:
                return "clue_rate";
            case 4:
                return "superior_rate";
            case 5:
                return "xp";
            default:
                return null;
        }
    }

    /**
     * {@code VarbitID#SLAYER_MASTER} isn't a full index into the master list (see this class's
     * javadoc), but two of its values are confirmed constants ported from RuneLite core's
     * SlayerPlugin (used there to pick the right streak counter, see the switch above) - reused
     * here as an immediate fallback for these two masters specifically when dialogue capture
     * hasn't named the master yet (e.g. right after a client/plugin restart mid-task), rather than
     * leaving masterName null until the player next talks to them.
     */
    private static String resolveMasterNameFromOrdinal(int master) {
        switch (master) {
            case 7:
                return "Krystilia";
            case 10:
                return "Mortimer";
            default:
                return null;
        }
    }

    /** Task id shared by every DT2-boss slayer assignment (Leviathan, Whisperer, Vardorvis, Duke
     * Sucellus, ...) - which specific boss is actually assigned lives in a separate varbit, see
     * {@link #resolveBossTaskId}. Ported from RuneLite core's SlayerPlugin. */
    private static final int BOSS_TASK_ID = 98;

    private static String resolveTaskName(Client client, int taskId) {
        if (taskId == BOSS_TASK_ID) {
            // SlayerTaskSublist.COL_TASK is already an encoded SlayerTask DB row reference, not a
            // value to search SlayerTask.COL_ID for - RuneLite core's own SlayerPlugin passes it
            // straight into getDBTableField. Searching by value here (as this used to) only works
            // by chance for some bosses and returns no rows for others (confirmed against a live
            // Barrows Brothers assignment, whose COL_TASK value never matches any COL_ID row).
            Integer bossTaskRow = resolveBossTaskId(client, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
            if (bossTaskRow == null) return "Boss";

            Object[] fields = client.getDBTableField(bossTaskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
            return fields.length > 0 ? (String) fields[0] : "Boss";
        }

        List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
        if (rows.isEmpty()) return null;

        Object[] fields = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
        return fields.length > 0 ? (String) fields[0] : null;
    }

    /**
     * A boss-task assignment ({@code SLAYER_TARGET == BOSS_TASK_ID}) names which boss via {@code
     * VarbitID#SLAYER_TARGET_BOSSID} indexing {@code DBTableID.SlayerTaskSublist} rather than
     * directly via {@code DBTableID.SlayerTask} like every other task - this resolves that
     * indirection to the {@code SlayerTask} DB row (an opaque row reference, not a {@code COL_ID}
     * value - pass it straight to {@code getDBTableField}, don't search {@code COL_ID} for it).
     * Ported from RuneLite core's SlayerPlugin.
     */
    private static Integer resolveBossTaskId(Client client, int bossVarbitId) {
        List<Integer> rows = client.getDBRowsByValue(
                DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossVarbitId);
        if (rows.isEmpty()) return null;

        Object[] fields = client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
        return fields.length > 0 ? (Integer) fields[0] : null;
    }

    private static String resolveAreaName(Client client, int areaId) {
        if (areaId <= 0) return null;

        List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
        if (rows.isEmpty()) return null;

        Object[] fields = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
        return fields.length > 0 ? (String) fields[0] : null;
    }

    // Package-visible accessors for GroupScapeTrackerPlugin's transition detection
    // (pushSlayerTaskState comparing `previous` against a freshly-built state) - `get()` only
    // exposes the wire-shaped Map, which doesn't let a caller cheaply inspect a *previous*
    // instance's fields without re-parsing its own output.
    boolean hasTask() {
        return hasTask;
    }

    int taskId() {
        return taskId;
    }

    String masterName() {
        return masterName;
    }

    String taskName() {
        return taskName;
    }

    int amountRemaining() {
        return amountRemaining;
    }

    int initialAmount() {
        return initialAmount;
    }

    int points() {
        return points;
    }

    String modifierType() {
        return modifierType;
    }

    Integer modifierValue() {
        return modifierValue;
    }

    Boolean modifierNegative() {
        return modifierNegative;
    }

    @Override
    public Object get() {
        Map<String, Object> out = new HashMap<>();
        // Always sent explicitly (even when false) so "no task" is unambiguous on the wire,
        // rather than the consumer having to infer it from missing fields.
        out.put("hasTask", hasTask);
        out.put("points", points);
        out.put("streak", streak);

        if (hasTask) {
            out.put("masterName", masterName);
            out.put("taskName", taskName);
            out.put("taskLocation", taskLocation);
            out.put("amountRemaining", amountRemaining);
            out.put("initialAmount", initialAmount);
            if (modifierType != null) {
                out.put("modifierType", modifierType);
                out.put("modifierValue", modifierValue);
                out.put("modifierNegative", modifierNegative);
            }
        }

        return out;
    }

    @Override
    public String whoOwnsThis() {
        return playerName;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof SlayerTaskState)) return false;

        SlayerTaskState other = (SlayerTaskState) o;
        return hasTask == other.hasTask
                && amountRemaining == other.amountRemaining
                && initialAmount == other.initialAmount
                && points == other.points
                && streak == other.streak
                && Objects.equals(masterName, other.masterName)
                && Objects.equals(taskName, other.taskName)
                && Objects.equals(taskLocation, other.taskLocation)
                && Objects.equals(modifierType, other.modifierType)
                && Objects.equals(modifierValue, other.modifierValue)
                && Objects.equals(modifierNegative, other.modifierNegative);
    }
}

