package com.groupscape.roster;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import net.runelite.api.Point;

/**
 * Shared Ground-Items-plugin-style gradient beam column - a vertical line fading from transparent
 * at the top to solid at the ground, drawn in addition to (not instead of) each overlay's own
 * marker glyph. Used by both {@link PingViewportOverlay} (per-pinger hue) and
 * {@link RaidMarkerViewportOverlay} (per-type color) - in both cases only for a tile ping/marker,
 * never an NPC one.
 */
final class BeamRenderer {
    private static final int WIDTH_PX = 8;
    private static final int TOP_ALPHA = 0;
    private static final int BOTTOM_ALPHA = 160;

    private BeamRenderer() {
    }

    static void draw(Graphics2D graphics, Point top, Point bottom, Color color) {
        if (top == null || bottom == null) {
            return;
        }

        Color transparent = new Color(color.getRed(), color.getGreen(), color.getBlue(), TOP_ALPHA);
        Color solid = new Color(color.getRed(), color.getGreen(), color.getBlue(), BOTTOM_ALPHA);
        Paint originalPaint = graphics.getPaint();
        graphics.setPaint(new GradientPaint(top.getX(), top.getY(), transparent, bottom.getX(), bottom.getY(), solid));
        graphics.setStroke(new BasicStroke(WIDTH_PX));
        graphics.drawLine(top.getX(), top.getY(), bottom.getX(), bottom.getY());
        graphics.setPaint(originalPaint);
    }
}

package com.groupscape.roster;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.groupscape.HttpRequestService;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * Fetches {@code GET /api/characters/{accountHash}/get-chat-messages} once per connect (triggered
 * from {@code GroupLinkListener#onLinked()}, mirroring how the party overlay itself only becomes
 * live once linked) and merges the page into {@link ChatState}. See the "!gs" chat spec §6 - the
 * server always returns the same rolling last-week window for the group, regardless of this
 * account's read/delivery state, so a reconnect never re-shows "nothing happened" for messages
 * this client already has.
 */
@Slf4j
public class ChatBackfillClient {
    private static final Type MESSAGE_LIST_TYPE = new TypeToken<List<ChatWireTypes.ChatMessageWire>>() {}.getType();

    private final HttpRequestService httpRequestService;
    private final Gson gson;
    private final ChatState state;

    public ChatBackfillClient(HttpRequestService httpRequestService, Gson gson, ChatState state) {
        this.httpRequestService = httpRequestService;
        this.gson = gson;
        this.state = state;
    }

    public void fetch(String baseUrl, String accountHash, String apiKey) {
        if (baseUrl == null || accountHash == null || apiKey == null || apiKey.trim().isEmpty()) return;

        String url = baseUrl + "/api/characters/" + accountHash + "/get-chat-messages";
        HttpRequestService.HttpResponse response = httpRequestService.get(url, apiKey);
        if (!response.isSuccessful()) {
            log.debug("get-chat-messages failed: {} {}", response.getCode(), response.getBody());
            return;
        }

        try {
            List<ChatWireTypes.ChatMessageWire> messages = gson.fromJson(response.getBody(), MESSAGE_LIST_TYPE);
            if (messages == null) return;
            for (ChatWireTypes.ChatMessageWire wire : messages) {
                state.add(new ChatState.Entry(wire.messageId, wire.memberName, wire.messageText,
                        Instant.parse(wire.createdAt)));
            }
        } catch (Exception e) {
            log.debug("get-chat-messages: failed to parse response", e);
        }
    }
}

package com.groupscape.roster;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;

/**
 * Thread-safe in-memory group chat log: written from both the backfill HTTP client and the
 * WebSocket callback thread (a live message can race the backfill response that would otherwise
 * have included it), read from the sidepanel's Swing refresh timer. Keyed by {@code messageId} so
 * either writer can land the same message without duplicating it - see the "!gs" chat spec §6.
 */
public class ChatState {
    private static final int MAX_MESSAGES = 200;

    public static class Entry {
        public final long messageId;
        public final String memberName;
        public final String text;
        public final Instant createdAt;

        public Entry(long messageId, String memberName, String text, Instant createdAt) {
            this.messageId = messageId;
            this.memberName = memberName;
            this.text = text;
            this.createdAt = createdAt;
        }
    }

    private final TreeMap<Long, Entry> messagesById = new TreeMap<>();

    public synchronized void add(Entry entry) {
        messagesById.put(entry.messageId, entry);
        while (messagesById.size() > MAX_MESSAGES) {
            messagesById.remove(messagesById.firstKey());
        }
    }

    public synchronized List<Entry> all() {
        return new ArrayList<>(messagesById.values());
    }

    /** The newest message id currently held, used to drive the side panel's read cursor (spec §6) -
     * the delivery cursor itself is tracked server-side, not here. */
    public synchronized long latestMessageId() {
        return messagesById.isEmpty() ? 0 : messagesById.lastKey();
    }

    public synchronized void clear() {
        messagesById.clear();
    }
}

package com.groupscape.roster;

/**
 * DTO for {@code GET /get-chat-messages}'s response body (a {@code groupscape.chat_messages} row
 * as serialized by the server's {@code models::ChatMessage} - see `groupscape-web/server/src/models.rs`).
 * Distinct from {@link RosterWireTypes.ChatMessagePayload} (the WebSocket envelope), which uses
 * `text` rather than `messageText` and has no `createdAt`.
 */
public class ChatWireTypes {
    public static class ChatMessageWire {
        public long messageId;
        public String memberName;
        public String messageText;
        public String createdAt;
    }
}

package com.groupscape.roster;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.groupscape.HttpRequestService;
import java.io.UnsupportedEncodingException;
import java.lang.reflect.Type;
import java.net.URLEncoder;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.util.List;
import lombok.extern.slf4j.Slf4j;

/**
 * Polls {@code GET /api/characters/{accountHash}/get-group-data} on a fixed cadence and merges
 * the response into {@link GroupSnapshotState}. That endpoint is incremental - it only returns a
 * member's field when it changed since the {@code from_time} query param - so this keeps a
 * {@link #cursor} advanced to (approximately) "now" after each successful poll, the same
 * since-timestamp pattern the website's group dashboard uses (see group-data.js).
 */
@Slf4j
public class GroupSnapshotClient {
    private static final Type MEMBER_LIST_TYPE =
            new TypeToken<List<GroupSnapshotWireTypes.GroupMemberWire>>() {}.getType();

    private final HttpRequestService httpRequestService;
    private final Gson gson;
    private final GroupSnapshotState state;
    private Instant cursor = Instant.EPOCH;

    public GroupSnapshotClient(HttpRequestService httpRequestService, Gson gson, GroupSnapshotState state) {
        this.httpRequestService = httpRequestService;
        this.gson = gson;
        this.state = state;
    }

    public void poll(String baseUrl, String accountHash, String apiKey) {
        if (baseUrl == null || accountHash == null || apiKey == null || apiKey.trim().isEmpty()) return;

        // Captured before the request goes out (not after it returns) so a member update that
        // lands mid-request is still covered by the *next* poll's from_time rather than skipped.
        Instant requestStartedAt = Instant.now();
        String url = baseUrl + "/api/characters/" + accountHash + "/get-group-data?from_time="
                + urlEncode(DateTimeFormatter.ISO_INSTANT.format(cursor));

        HttpRequestService.HttpResponse response = httpRequestService.get(url, apiKey);
        if (!response.isSuccessful()) {
            log.debug("get-group-data failed: {} {}", response.getCode(), response.getBody());
            return;
        }

        try {
            List<GroupSnapshotWireTypes.GroupMemberWire> members = gson.fromJson(response.getBody(), MEMBER_LIST_TYPE);
            state.applyDelta(members);
            cursor = requestStartedAt;
        } catch (Exception e) {
            log.debug("get-group-data: failed to parse response", e);
        }
    }

    private static String urlEncode(String value) {
        try {
            return URLEncoder.encode(value, "UTF-8");
        } catch (UnsupportedEncodingException e) {
            return value;
        }
    }
}

package com.groupscape.roster;

import java.time.Instant;
import java.util.Collections;
import java.util.List;

/**
 * Mutable per-member inventory/equipment/skills snapshot the sidepanel renders from, filled by
 * {@link GroupSnapshotClient}'s periodic delta poll. Mirrors {@link RosterMember}'s
 * apply-only-what-changed pattern: the server only sends a field when it changed since the
 * poll's {@code from_time} cursor, so a field null in one response just means "unchanged", not
 * "cleared" - go on displaying the last known value.
 */
public class GroupSnapshotMember {
    public final String name;
    public String color;
    public List<Integer> inventory = Collections.emptyList();
    public List<Integer> equipment = Collections.emptyList();
    public List<Integer> skillXp = Collections.emptyList();
    public Instant lastUpdated;

    public GroupSnapshotMember(String name) {
        this.name = name;
    }

    public void applyDelta(GroupSnapshotWireTypes.GroupMemberWire wire) {
        if (wire == null) return;

        if (wire.color != null) color = wire.color;
        if (wire.inventory != null) inventory = wire.inventory;
        if (wire.equipment != null) equipment = wire.equipment;
        if (wire.skills != null) skillXp = wire.skills;

        if (wire.last_updated != null) {
            try {
                lastUpdated = Instant.parse(wire.last_updated);
            } catch (Exception ignored) {
                // leave the previous value in place
            }
        }
    }
}

package com.groupscape.roster;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Thread-safe in-memory store of inventory/equipment/skills per group member, written from
 * {@link GroupSnapshotClient}'s scheduled poll thread and read from the sidepanel's Swing
 * refresh timer. Mirrors {@link RosterState}'s shape, kept as a separate store rather than
 * folded into {@link RosterMember} since it's fed by a slower HTTP poll instead of the live
 * vitals websocket.
 */
public class GroupSnapshotState {
    private final Map<String, GroupSnapshotMember> members = new LinkedHashMap<>();

    public synchronized void applyDelta(List<GroupSnapshotWireTypes.GroupMemberWire> wire) {
        if (wire == null) return;

        for (GroupSnapshotWireTypes.GroupMemberWire entry : wire) {
            if (entry.name == null) continue;
            GroupSnapshotMember member = members.computeIfAbsent(entry.name, GroupSnapshotMember::new);
            member.applyDelta(entry);
        }
    }

    public synchronized GroupSnapshotMember get(String name) {
        return members.get(name);
    }

    public synchronized List<GroupSnapshotMember> all() {
        return new ArrayList<>(members.values());
    }

    public synchronized void clear() {
        members.clear();
    }
}

package com.groupscape.roster;

import java.util.List;

/**
 * Mirrors the server's {@code GroupMember} (groupscape-web/server/src/models.rs), as returned by
 * {@code GET /api/characters/{accountHash}/get-group-data}. That handler is the plugin-facing
 * mount (same per-character API-key auth as the roster websocket and the rest of DataManager's
 * uploads) of the exact same {@code get_group_data} the website's group dashboard reads from -
 * see main.rs's {@code character_scope}. Field names are left snake_case to match the server's
 * un-renamed serde output verbatim, so Gson's default reflection can deserialize without extra
 * annotations (same convention as {@link RosterWireTypes}).
 *
 * <p>Only the fields the sidepanel actually renders are declared here; the response carries many
 * more (bank, quests, diary_vars, ...) that Gson silently ignores.
 */
public class GroupSnapshotWireTypes {
    public static class GroupMemberWire {
        public String name;
        public String color;
        /** Flat [id, quantity, id, quantity, ...] pairs, one pair per inventory slot (28), empty slots are id 0. */
        public List<Integer> inventory;
        /** Flat [id, quantity, ...] pairs indexed by {@code EquipmentInventorySlot#getSlotIdx()}. */
        public List<Integer> equipment;
        /** XP per skill, ordered per {@code SkillOrder#SKILLS} (alphabetical, Overall excluded). */
        public List<Integer> skills;
        public String last_updated;
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.time.Instant;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Keeps one {@link WorldMapPoint} per eligible group member in sync with {@link RosterState},
 * called from a game tick. A member's name shows as a hover tooltip only - RuneLite's world map
 * has no always-on label rendering for points (its tooltip is a hover-triggered popup, same as
 * quest/clue markers), so this can't diverge from that convention. {@code snapToEdge}/
 * {@code jumpOnClick} give the same off-screen edge arrow (click to pan/zoom into view) that
 * quest and clue markers already use.
 */
public class GroupWorldMapPoints {
    private static final int ICON_HEIGHT = 20;

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final RosterState rosterState;
    private final WorldMapPointManager worldMapPointManager;
    private final MemberMapIcons icons;
    private final Map<String, WorldMapPoint> pointsByMember = new HashMap<>();

    public GroupWorldMapPoints(Client client, GroupScapeTrackerConfig config, RosterState rosterState,
                                WorldMapPointManager worldMapPointManager, MemberMapIcons icons) {
        this.client = client;
        this.config = config;
        this.rosterState = rosterState;
        this.worldMapPointManager = worldMapPointManager;
        this.icons = icons;
    }

    public void sync() {
        Player localPlayer = client.getLocalPlayer();
        if (!config.mapMarkersEnabled() || localPlayer == null || localPlayer.getName() == null) {
            clear();
            return;
        }

        int world = client.getWorld();
        int plane = client.getPlane();
        String localName = localPlayer.getName();

        Map<String, RosterMember> eligible = new HashMap<>();
        for (RosterMember member : rosterState.all()) {
            if (!member.name.equalsIgnoreCase(localName) && isEligible(member, world, plane)) {
                eligible.put(member.name, member);
            }
        }

        Iterator<Map.Entry<String, WorldMapPoint>> it = pointsByMember.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, WorldMapPoint> entry = it.next();
            if (!eligible.containsKey(entry.getKey())) {
                worldMapPointManager.remove(entry.getValue());
                it.remove();
            }
        }

        for (RosterMember member : eligible.values()) {
            WorldPoint worldPoint = new WorldPoint(member.worldX, member.worldY, member.plane);
            WorldMapPoint point = pointsByMember.get(member.name);
            if (point == null) {
                point = new WorldMapPoint(worldPoint, icons.get(member.color, ICON_HEIGHT));
                point.setName(member.name);
                point.setTooltip(member.name);
                point.setSnapToEdge(true);
                point.setJumpOnClick(true);
                pointsByMember.put(member.name, point);
                worldMapPointManager.add(point);
            } else {
                point.setWorldPoint(worldPoint);
                point.setImage(icons.get(member.color, ICON_HEIGHT));
            }
        }
    }

    public void clear() {
        for (WorldMapPoint point : pointsByMember.values()) {
            worldMapPointManager.remove(point);
        }
        pointsByMember.clear();
    }

    private boolean isEligible(RosterMember member, int world, int plane) {
        if (member.worldX == null || member.worldY == null || member.plane == null) {
            return false;
        }
        if (member.world == null || member.world != world || member.plane != plane) {
            return false;
        }
        return !isOffline(member);
    }

    private boolean isOffline(RosterMember member) {
        if (member.lastHeartbeatAt == null) {
            return true;
        }
        return Instant.now().toEpochMilli() - member.lastHeartbeatAt.toEpochMilli() >= RosterMember.OFFLINE_THRESHOLD_MS;
    }
}

package com.groupscape.roster;

import com.groupscape.NpcDialogueTracker;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Builds a {@link RosterMember} for the local player straight from {@link Client}, bypassing the
 * roster/websocket entirely. Shared by {@link PartyFrameOverlay} and the sidepanel's roster list
 * so both show a live "you" row that works even with no server connection.
 */
public final class LocalRosterMemberFactory {
    private LocalRosterMemberFactory() {
    }

    public static RosterMember build(Client client, NpcDialogueTracker dialogueTracker) {
        return build(client, dialogueTracker, null);
    }

    /**
     * @param rosterState if non-null, used to look up the local player's server-assigned color
     * (the same admin-assigned helmet colour shown for every other member) instead of the
     * placeholder gold fallback, since the local player's own row bypasses the roster otherwise.
     */
    public static RosterMember build(Client client, NpcDialogueTracker dialogueTracker, RosterState rosterState) {
        Player player = client.getLocalPlayer();
        if (player == null || player.getName() == null) {
            return null;
        }

        RosterMember self = new RosterMember(player.getName());
        RosterMember known = rosterState != null ? rosterState.findByName(player.getName()) : null;
        self.color = known != null ? known.color : "#FFD700";
        self.hp = client.getBoostedSkillLevel(Skill.HITPOINTS);
        self.maxHp = client.getRealSkillLevel(Skill.HITPOINTS);
        self.prayer = client.getBoostedSkillLevel(Skill.PRAYER);
        self.maxPrayer = client.getRealSkillLevel(Skill.PRAYER);
        self.runEnergy = client.getEnergy() / 100;
        self.specEnergy = client.getVarpValue(VarPlayer.SPECIAL_ATTACK_PERCENT) / 10;
        self.world = client.getWorld();
        self.lastHeartbeatAt = Instant.now();
        self.activePrayers = activePrayerNames(client);
        applyLocalTarget(self, client, dialogueTracker);
        return self;
    }

    /**
     * Fills the self row's target fields straight from Client, the same signals
     * {@code RichPresenceState} used to build its text ("Fighting X" / "Talking to X" /
     * "Browsing the bank"), but kept as structured name+ratio+scale so the bar can render an
     * actual HP fill instead of a static line of text.
     */
    private static void applyLocalTarget(RosterMember self, Client client, NpcDialogueTracker dialogueTracker) {
        Player player = client.getLocalPlayer();

        Actor interacting = player.getInteracting();
        if (interacting != null && interacting.getName() != null) {
            self.targetName = interacting.getName();

            // Non-combat NPCs (bankers, quest givers, Tool Leprechauns, etc.) can still flash a
            // stale/default healthbar ratio from RuneLite for a tick even though they're not
            // actually fightable - combat level isn't reliable here since some non-attackable
            // NPCs still report one. Whether "Attack" is actually a menu option is the signal
            // that can't fluctuate tick to tick.
            boolean combatCapable = !(interacting instanceof NPC) || isAttackable((NPC) interacting);
            if (combatCapable) {
                self.targetHealthScale = interacting.getHealthScale();
                self.targetHealthRatio = interacting.getHealthRatio();
            } else {
                self.targetHealthScale = 0;
                self.targetHealthRatio = -1;
            }
            return;
        }

        // getInteracting() has already gone null once the dialogue box is actually open (see
        // NpcDialogueTracker) but the box is still up, so the player is still "talking to"
        // whoever they last targeted.
        if (dialogueTracker != null && dialogueTracker.lastNpcName() != null) {
            self.targetName = dialogueTracker.lastNpcName();
            self.targetHealthScale = 0;
            self.targetHealthRatio = -1;
            return;
        }

        Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
        if (bankItems != null && !bankItems.isHidden()) {
            self.targetName = "Bank";
            self.targetHealthScale = 0;
            self.targetHealthRatio = -1;
            return;
        }

        self.targetName = null;
        self.targetHealthScale = null;
        self.targetHealthRatio = null;
    }

    private static boolean isAttackable(NPC npc) {
        NPCComposition comp = npc.getTransformedComposition();
        if (comp == null) return false;
        for (String action : comp.getActions()) {
            if ("Attack".equalsIgnoreCase(action)) return true;
        }
        return false;
    }

    private static List<String> activePrayerNames(Client client) {
        List<String> names = new ArrayList<>();
        for (Prayer prayer : Prayer.values()) {
            if (client.isPrayerActive(prayer)) {
                names.add(prayer.name());
            }
        }
        return names;
    }
}

package com.groupscape.roster;

import java.awt.Color;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.util.ImageUtil;

/**
 * Builds and caches the group map marker glyph: the same {@code player-icon.webp} sprite the
 * web app's canvas-map uses for its "Helm & Ring" marker design, recolored to a member's assigned
 * hex color. AWT has no equivalent to CSS's {@code hue-rotate}/{@code saturate} filter the web
 * side uses, so this recolors each pixel directly - target hue/saturation, keeping the source
 * pixel's brightness (and alpha) - which lands the same for a single-hue source icon.
 */
public class MemberMapIcons {
    private static final BufferedImage BASE = ImageUtil.loadImageResource(MemberMapIcons.class, "player-icon.png");

    private final Map<String, BufferedImage> cache = new ConcurrentHashMap<>();

    /** @param heightPx target rendered height; width is scaled to match the source aspect ratio. */
    public BufferedImage get(String hexColor, int heightPx) {
        String key = hexColor + "@" + heightPx;
        return cache.computeIfAbsent(key, k -> render(hexColor, heightPx));
    }

    private static BufferedImage render(String hexColor, int heightPx) {
        Color target;
        try {
            target = Color.decode(hexColor);
        } catch (Exception e) {
            target = Color.WHITE;
        }
        float[] targetHsb = Color.RGBtoHSB(target.getRed(), target.getGreen(), target.getBlue(), null);

        BufferedImage tinted = new BufferedImage(BASE.getWidth(), BASE.getHeight(), BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < BASE.getHeight(); y++) {
            for (int x = 0; x < BASE.getWidth(); x++) {
                int argb = BASE.getRGB(x, y);
                int alpha = (argb >>> 24) & 0xFF;
                if (alpha == 0) {
                    continue;
                }
                float brightness = Color.RGBtoHSB((argb >> 16) & 0xFF, (argb >> 8) & 0xFF, argb & 0xFF, null)[2];
                int rgb = Color.HSBtoRGB(targetHsb[0], targetHsb[1], brightness);
                tinted.setRGB(x, y, (alpha << 24) | (rgb & 0x00FFFFFF));
            }
        }

        int width = Math.max(1, Math.round(BASE.getWidth() * ((float) heightPx / BASE.getHeight())));
        Image scaled = tinted.getScaledInstance(width, heightPx, Image.SCALE_SMOOTH);
        BufferedImage out = new BufferedImage(width, heightPx, BufferedImage.TYPE_INT_ARGB);
        out.getGraphics().drawImage(scaled, 0, 0, null);
        return out;
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.time.Instant;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws each visible group member's hue-tinted marker on the minimap, with the member's name
 * shown as a hover-only tooltip (the world map equivalent, {@link GroupWorldMapPoints}, labels
 * always-on instead - minimap space is tighter). Only members RuneLite has actually loaded as
 * on-screen {@link Player} actors can appear here, which already limits this to members in the
 * local player's world and on their plane.
 */
public class MinimapLocationOverlay extends Overlay {
    private static final int ICON_HEIGHT = 12;
    private static final int HOVER_RADIUS_PX = 7;

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final RosterState rosterState;
    private final TooltipManager tooltipManager;
    private final MemberMapIcons icons;

    public MinimapLocationOverlay(Client client, GroupScapeTrackerConfig config, RosterState rosterState,
                                   TooltipManager tooltipManager, MemberMapIcons icons) {
        this.client = client;
        this.config = config;
        this.rosterState = rosterState;
        this.tooltipManager = tooltipManager;
        this.icons = icons;
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.mapMarkersEnabled()) {
            return null;
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return null;
        }

        Point mouse = client.getMouseCanvasPosition();

        for (Player player : client.getPlayers()) {
            if (player == null || player == localPlayer || player.getName() == null) {
                continue;
            }

            RosterMember member = findMember(player.getName());
            if (member == null || isOffline(member)) {
                continue;
            }

            Point loc = player.getMinimapLocation();
            if (loc == null) {
                continue;
            }

            BufferedImage icon = icons.get(member.color, ICON_HEIGHT);
            graphics.drawImage(icon, loc.getX() - icon.getWidth() / 2, loc.getY() - icon.getHeight() / 2, null);

            if (mouse != null && mouse.distanceTo(loc) <= HOVER_RADIUS_PX) {
                tooltipManager.add(new Tooltip(member.name));
            }
        }

        return null;
    }

    private RosterMember findMember(String playerName) {
        for (RosterMember member : rosterState.all()) {
            if (member.name.equalsIgnoreCase(playerName)) {
                return member;
            }
        }
        return null;
    }

    private boolean isOffline(RosterMember member) {
        if (member.lastHeartbeatAt == null) {
            return true;
        }
        return Instant.now().toEpochMilli() - member.lastHeartbeatAt.toEpochMilli() >= RosterMember.OFFLINE_THRESHOLD_MS;
    }
}

