    @Override
    public Dimension render(Graphics2D graphics) {
        if (config.partyOverlayHideOverlay()) {
            return null;
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || localPlayer.getName() == null) {
            return null;
        }

        List<RosterMember> members = buildMemberList(localPlayer.getName());
        if (members.isEmpty()) {
            return null;
        }

        sortMembers(members);
        applyScale();

        int extraCount = 0;
        int maxMembers = config.partyOverlayMaxMembers();
        if (maxMembers > 0 && members.size() > maxMembers) {
            extraCount = members.size() - maxMembers;
            members = members.subList(0, maxMembers);
        }

        if (isOrbGrid()) {
            return renderOrbGrid(graphics, members, localPlayer.getName(), extraCount);
        }
        if (isScoreboard()) {
            return renderScoreboard(graphics, members, localPlayer.getName(), extraCount);
        }

        graphics.setFont(scaledFont(graphics));

        Map<RosterMember, Boolean> offlineByMember = new LinkedHashMap<>();
        for (RosterMember member : members) {
            boolean self = member.name.equalsIgnoreCase(localPlayer.getName());
            offlineByMember.put(member, !self && isOffline(member));
        }

        int height = padding;
        for (RosterMember member : members) {
            height += memberHeight(member, offlineByMember.get(member));
        }
        if (extraCount > 0) {
            height += lineHeight;
        }
        height += padding;

        drawChrome(graphics, PANEL_WIDTH, height);

        lastRenderedRows.clear();
        int y = padding;
        for (RosterMember member : members) {
            boolean self = member.name.equalsIgnoreCase(localPlayer.getName());
            boolean offline = offlineByMember.get(member);
            boolean outOfVicinity = !self && !offline && config.partyOverlayFadeOutOfVicinity()
                    && !withinVicinity(member, config.partyOverlayVicinityFadeTiles());
            int startY = y;
            y = drawMember(graphics, member, y, offline, offline || outOfVicinity);
            lastRenderedRows.put(new Rectangle(0, startY, PANEL_WIDTH, y - startY), member);
        }

        if (extraCount > 0) {
            graphics.setColor(MUTED_TEXT);
            FontMetrics footerMetrics = graphics.getFontMetrics();
            int footerBaseline = y + (lineHeight + footerMetrics.getAscent() - footerMetrics.getDescent()) / 2;
            graphics.drawString("+" + extraCount + " more", padding + 6, footerBaseline);
        }

        return new Dimension(PANEL_WIDTH, height);
    }

    /**
     * Orb Grid's render path: members tile as circular status orbs left-to-right, wrapping into
     * new rows, instead of stacking as labeled bar rows. Mirrors render()'s general shape (compute
     * height, draw chrome, draw members, record hit rects, draw overflow footer) but the geometry
     * is grid math instead of row math, so it doesn't share applyScale()'s padding/lineHeight/etc.
     */
    private Dimension renderOrbGrid(Graphics2D graphics, List<RosterMember> members, String localPlayerName, int extraCount) {
        int cols = Math.max(1, Math.min(ORB_MAX_COLS, members.size()));
        int rows = (int) Math.ceil(members.size() / (double) cols);
        int width = ORB_PADDING * 2 + cols * (ORB_SIZE + ORB_GAP) - ORB_GAP;
        int gridHeight = rows * (ORB_SIZE + ORB_GAP) - ORB_GAP;
        int footerHeight = extraCount > 0 ? ORB_FOOTER_HEIGHT : 0;
        int height = ORB_PADDING * 2 + gridHeight + ORB_PIP_OVERHANG + footerHeight;

        drawChrome(graphics, width, height);
        graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, ORB_SIZE * 0.28f));

        lastRenderedRows.clear();
        for (int i = 0; i < members.size(); i++) {
            RosterMember member = members.get(i);
            boolean self = member.name.equalsIgnoreCase(localPlayerName);
            boolean offline = !self && isOffline(member);
            boolean outOfVicinity = !self && !offline && config.partyOverlayFadeOutOfVicinity()
                    && !withinVicinity(member, config.partyOverlayVicinityFadeTiles());

            int col = i % cols;
            int row = i / cols;
            int cx = ORB_PADDING + col * (ORB_SIZE + ORB_GAP) + ORB_SIZE / 2;
            int cy = ORB_PADDING + row * (ORB_SIZE + ORB_GAP) + ORB_SIZE / 2;

            drawOrb(graphics, cx, cy, member, offline, offline || outOfVicinity);
            lastRenderedRows.put(new Rectangle(cx - ORB_SIZE / 2, cy - ORB_SIZE / 2, ORB_SIZE, ORB_SIZE), member);
        }

        if (extraCount > 0) {
            graphics.setColor(MUTED_TEXT);
            FontMetrics metrics = graphics.getFontMetrics();
            int footerY = ORB_PADDING + gridHeight + ORB_PIP_OVERHANG + (footerHeight + metrics.getAscent() - metrics.getDescent()) / 2;
            graphics.drawString("+" + extraCount + " more", ORB_PADDING, footerY);
        }

        return new Dimension(width, height);
    }

    /**
     * One member's orb: an HP-ratio ring (track when hidden/empty, filled clockwise from the top
     * otherwise), a color-filled core with 2-letter initials, three tick pips for Prayer/Run/Spec
     * lit proportionally to their ratio, and a target badge - each piece skipped per its own
     * partyOverlayHideX() toggle. Offline members render track-only/desaturated with no pips or
     * badge, matching the grayscale-and-fade convention the row tiers already use for offline.
     */
    private void drawOrb(Graphics2D graphics, int cx, int cy, RosterMember member, boolean offline, boolean faded) {
        java.awt.Composite originalComposite = graphics.getComposite();
        if (faded) {
            graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, OFFLINE_ALPHA));
        }

        float ringStroke = ORB_SIZE * 0.09f;
        float ringR = ORB_SIZE / 2f - ringStroke / 2f;
        Object previousStroke = graphics.getStroke();
        graphics.setStroke(new BasicStroke(ringStroke));

        graphics.setColor(TRACK_COLOR);
        graphics.draw(new Arc2D.Double(cx - ringR, cy - ringR, ringR * 2, ringR * 2, 0, 360, Arc2D.OPEN));

        if (!offline && !config.partyOverlayHideHp()) {
            double hpRatio = ratio(member.hp, member.maxHp);
            graphics.setColor(HP_COLOR);
            graphics.draw(new Arc2D.Double(cx - ringR, cy - ringR, ringR * 2, ringR * 2, 90, -360 * hpRatio, Arc2D.OPEN));
        }
        graphics.setStroke((java.awt.Stroke) previousStroke);

        int coreR = Math.round(ORB_SIZE / 2f - ringStroke * 2f);
        Color coreColor = offline ? toGrayscale(memberColor(member.color)) : memberColor(member.color);
        graphics.setColor(coreColor);
        graphics.fillOval(cx - coreR, cy - coreR, coreR * 2, coreR * 2);

        String initials = member.name.length() >= 2 ? member.name.substring(0, 2).toUpperCase() : member.name.toUpperCase();
        graphics.setColor(ORB_INITIALS_COLOR);
        FontMetrics metrics = graphics.getFontMetrics();
        float textX = cx - metrics.stringWidth(initials) / 2f;
        float textY = cy + (metrics.getAscent() - metrics.getDescent()) / 2f;
        graphics.drawString(initials, textX, textY);

        if (!offline) {
            drawOrbPips(graphics, cx, cy, member, faded ? OFFLINE_ALPHA : 1f);

            if (!config.partyOverlayHideTarget() && member.targetName != null && !member.targetName.isEmpty()) {
                boolean isEnemy = member.targetHealthScale != null && member.targetHealthScale > 0;
                double bx = cx + ORB_SIZE / 2.0 * 0.72;
                double by = cy - ORB_SIZE / 2.0 * 0.72;
                graphics.setColor(isEnemy ? ORB_TARGET_ENEMY : ORB_TARGET_NEUTRAL);
                graphics.fillOval((int) bx - 3, (int) by - 3, 6, 6);
                graphics.setColor(BG_BASE);
                graphics.drawOval((int) bx - 3, (int) by - 3, 6, 6);
            }
        }

        if (faded) {
            graphics.setComposite(originalComposite);
        }
    }

    /** The three Prayer/Run/Spec pips along an orb's bottom arc, each drawn only if its metric isn't hidden. */
    private void drawOrbPips(Graphics2D graphics, int cx, int cy, RosterMember member, float outerAlpha) {
        List<Color> colors = new ArrayList<>(3);
        List<Double> ratios = new ArrayList<>(3);
        if (!config.partyOverlayHidePrayer()) {
            colors.add(PRAYER_COLOR);
            ratios.add(ratio(member.prayer, member.maxPrayer));
        }
        if (!config.partyOverlayHideRun()) {
            colors.add(RUN_COLOR);
            ratios.add(ratio(member.runEnergy, 100));
        }
        if (!config.partyOverlayHideSpec()) {
            colors.add(SPEC_COLOR);
            ratios.add(ratio(member.specEnergy, 100));
        }
        if (colors.isEmpty()) {
            return;
        }

        double baseAngle = Math.PI / 2;
        double spread = 0.75;
        double pipR = ORB_SIZE / 2.0 + ORB_PIP_GAP + ORB_PIP_RADIUS;
        for (int i = 0; i < colors.size(); i++) {
            double angle = colors.size() == 1 ? baseAngle
                    : baseAngle - spread / 2 + spread * (i / (double) (colors.size() - 1));
            int px = (int) Math.round(cx + Math.cos(angle) * pipR);
            int py = (int) Math.round(cy + Math.sin(angle) * pipR);

            graphics.setColor(TRACK_COLOR);
            graphics.fillOval(px - ORB_PIP_RADIUS, py - ORB_PIP_RADIUS, ORB_PIP_RADIUS * 2, ORB_PIP_RADIUS * 2);

            double r = ratios.get(i);
            if (r > 0.05) {
                float alpha = (float) Math.max(0.35, r) * outerAlpha;
                java.awt.Composite pipComposite = graphics.getComposite();
                graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, alpha));
                graphics.setColor(colors.get(i));
                graphics.fillOval(px - ORB_PIP_RADIUS, py - ORB_PIP_RADIUS, ORB_PIP_RADIUS * 2, ORB_PIP_RADIUS * 2);
                graphics.setComposite(pipComposite);
            }
        }
    }

    /**
     * Scoreboard's render path: members sit in narrow side-by-side columns, wrapping into a new
     * strip below past SCOREBOARD_MAX_COLS, instead of stacking as rows or tiling as a 2D grid.
     * Mirrors renderOrbGrid's shape (content-sized panel, draw chrome, draw members, record hit
     * rects, draw overflow footer).
     */
    private Dimension renderScoreboard(Graphics2D graphics, List<RosterMember> members, String localPlayerName, int extraCount) {
        int cols = Math.max(1, Math.min(SCOREBOARD_MAX_COLS, members.size()));
        int rows = (int) Math.ceil(members.size() / (double) cols);
        int stripHeight = SCOREBOARD_BAR_HEIGHT + SCOREBOARD_PIP_ROW_GAP + SCOREBOARD_PIP_SIZE + SCOREBOARD_LABEL_GAP + 8;
        int width = SCOREBOARD_PADDING * 2 + cols * (SCOREBOARD_COL_WIDTH + SCOREBOARD_GAP) - SCOREBOARD_GAP;
        int gridHeight = rows * (stripHeight + SCOREBOARD_GAP) - SCOREBOARD_GAP + SCOREBOARD_TARGET_HEADROOM;
        int footerHeight = extraCount > 0 ? ORB_FOOTER_HEIGHT : 0;
        int height = SCOREBOARD_PADDING * 2 + gridHeight + footerHeight;

        drawChrome(graphics, width, height);
        graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, SCOREBOARD_FONT_SIZE));

        lastRenderedRows.clear();
        for (int i = 0; i < members.size(); i++) {
            RosterMember member = members.get(i);
            boolean self = member.name.equalsIgnoreCase(localPlayerName);
            boolean offline = !self && isOffline(member);
            boolean outOfVicinity = !self && !offline && config.partyOverlayFadeOutOfVicinity()
                    && !withinVicinity(member, config.partyOverlayVicinityFadeTiles());

            int col = i % cols;
            int row = i / cols;
            int x = SCOREBOARD_PADDING + col * (SCOREBOARD_COL_WIDTH + SCOREBOARD_GAP);
            int y = SCOREBOARD_PADDING + row * (stripHeight + SCOREBOARD_GAP) + SCOREBOARD_TARGET_HEADROOM;

            drawScoreColumn(graphics, x, y, member, offline, offline || outOfVicinity);
            lastRenderedRows.put(new Rectangle(x, y - SCOREBOARD_TARGET_HEADROOM, SCOREBOARD_COL_WIDTH, stripHeight + SCOREBOARD_TARGET_HEADROOM), member);
        }

        if (extraCount > 0) {
            graphics.setColor(MUTED_TEXT);
            FontMetrics metrics = graphics.getFontMetrics();
            int footerY = SCOREBOARD_PADDING + gridHeight + (footerHeight + metrics.getAscent() - metrics.getDescent()) / 2;
            graphics.drawString("+" + extraCount + " more", SCOREBOARD_PADDING, footerY);
        }

        return new Dimension(width, height);
    }

    /**
     * One member's column: an optional target-flag triangle above the bar, a vertical HP meter
     * (the one thing meant to read at a glance from across the screen), a row of Prayer/Run/Spec
     * tally pips, and initials below - each piece skipped per its own partyOverlayHideX() toggle.
     * Offline columns show the HP track only, dimmed grayscale initials, and no pips or flag.
     */
    private void drawScoreColumn(Graphics2D graphics, int x, int y, RosterMember member, boolean offline, boolean faded) {
        java.awt.Composite originalComposite = graphics.getComposite();
        if (faded) {
            graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, OFFLINE_ALPHA));
        }

        int barX = x + (SCOREBOARD_COL_WIDTH - SCOREBOARD_BAR_WIDTH) / 2;

        if (!offline && !config.partyOverlayHideTarget() && member.targetName != null && !member.targetName.isEmpty()) {
            boolean isEnemy = member.targetHealthScale != null && member.targetHealthScale > 0;
            int midX = x + SCOREBOARD_COL_WIDTH / 2;
            int[] xs = {midX, midX - 4, midX + 4};
            int[] ys = {y - 6, y - 1, y - 1};
            graphics.setColor(isEnemy ? ORB_TARGET_ENEMY : ORB_TARGET_NEUTRAL);
            graphics.fillPolygon(xs, ys, 3);
        }

        java.awt.geom.RoundRectangle2D.Float track = new java.awt.geom.RoundRectangle2D.Float(
                barX, y, SCOREBOARD_BAR_WIDTH, SCOREBOARD_BAR_HEIGHT, 6, 6);
        graphics.setColor(TRACK_COLOR);
        graphics.fill(track);

        if (!offline && !config.partyOverlayHideHp()) {
            double hpRatio = ratio(member.hp, member.maxHp);
            int fillHeight = (int) Math.round(SCOREBOARD_BAR_HEIGHT * hpRatio);
            Object previousClip = graphics.getClip();
            graphics.clip(track);
            graphics.setColor(HP_COLOR);
            graphics.fillRect(barX, y + SCOREBOARD_BAR_HEIGHT - fillHeight, SCOREBOARD_BAR_WIDTH, fillHeight);
            graphics.setClip((java.awt.Shape) previousClip);
        }

        int py = y + SCOREBOARD_BAR_HEIGHT + SCOREBOARD_PIP_ROW_GAP;
        if (!offline) {
            drawScorePips(graphics, x, py, member, faded ? OFFLINE_ALPHA : 1f);
        }

        int labelY = py + SCOREBOARD_PIP_SIZE + SCOREBOARD_LABEL_GAP;
        FontMetrics metrics = graphics.getFontMetrics();
        String initials = member.name.length() >= 2 ? member.name.substring(0, 2).toUpperCase() : member.name.toUpperCase();
        graphics.setColor(offline ? toGrayscale(memberColor(member.color)) : memberColor(member.color));
        drawBoldString(graphics, initials, x + (SCOREBOARD_COL_WIDTH - metrics.stringWidth(initials)) / 2f, labelY);

        if (faded) {
            graphics.setComposite(originalComposite);
        }
    }

    /** The Prayer/Run/Spec tally pips under a scoreboard column's HP bar, each skipped if its metric is hidden. */
    private void drawScorePips(Graphics2D graphics, int columnX, int y, RosterMember member, float outerAlpha) {
        List<Color> colors = new ArrayList<>(3);
        List<Double> ratios = new ArrayList<>(3);
        if (!config.partyOverlayHidePrayer()) {
            colors.add(PRAYER_COLOR);
            ratios.add(ratio(member.prayer, member.maxPrayer));
        }
        if (!config.partyOverlayHideRun()) {
            colors.add(RUN_COLOR);
            ratios.add(ratio(member.runEnergy, 100));
        }
        if (!config.partyOverlayHideSpec()) {
            colors.add(SPEC_COLOR);
            ratios.add(ratio(member.specEnergy, 100));
        }
        if (colors.isEmpty()) {
            return;
        }

        int totalWidth = colors.size() * SCOREBOARD_PIP_SIZE + (colors.size() - 1) * SCOREBOARD_PIP_H_GAP;
        int px = columnX + (SCOREBOARD_COL_WIDTH - totalWidth) / 2;
        for (int i = 0; i < colors.size(); i++) {
            graphics.setColor(TRACK_COLOR);
            graphics.fillRect(px, y, SCOREBOARD_PIP_SIZE, SCOREBOARD_PIP_SIZE);

            double r = ratios.get(i);
            if (r > 0.05) {
                float alpha = (float) Math.max(0.35, r) * outerAlpha;
                java.awt.Composite pipComposite = graphics.getComposite();
                graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, alpha));
                graphics.setColor(colors.get(i));
                graphics.fillRect(px, y, SCOREBOARD_PIP_SIZE, SCOREBOARD_PIP_SIZE);
                graphics.setComposite(pipComposite);
            }
            px += SCOREBOARD_PIP_SIZE + SCOREBOARD_PIP_H_GAP;
        }
    }

    /**
     * Returns the roster member whose row was drawn under the given canvas position on the last
     * render, or null if the position isn't over this overlay. {@code canvasX}/{@code canvasY}
     * are in the same coordinate space as {@link Client#getMouseCanvasPosition()}; they're
     * translated into overlay-local space using {@link #getBounds()}, which RuneLite's
     * OverlayRenderer keeps in sync with where this overlay was last actually drawn.
     */
    public RosterMember memberAt(int canvasX, int canvasY) {
        Rectangle bounds = getBounds();
        if (bounds == null || bounds.isEmpty()) {
            return null;
        }
        int localX = canvasX - bounds.x;
        int localY = canvasY - bounds.y;
        for (Map.Entry<Rectangle, RosterMember> entry : lastRenderedRows.entrySet()) {
            if (entry.getKey().contains(localX, localY)) {
                return entry.getValue();
            }
        }
        return null;
    }

    private void applyScale() {
        switch (config.partyOverlayScale()) {
            case MINIMAL:
                padding = MINIMAL_PADDING;
                memberGap = MINIMAL_MEMBER_GAP;
                lineHeight = MINIMAL_LINE_HEIGHT;
                barHeight = MINIMAL_BAR_HEIGHT;
                barGap = MINIMAL_BAR_GAP;
                prayerIconSize = MINIMAL_PRAYER_ICON_SIZE;
                prayerIconRowHeight = MINIMAL_PRAYER_ICON_ROW_HEIGHT;
                targetStripHeight = MINIMAL_TARGET_STRIP_HEIGHT;
                break;
            case SUPER_COMPACT:
                padding = SUPER_COMPACT_PADDING;
                memberGap = SUPER_COMPACT_MEMBER_GAP;
                lineHeight = SUPER_COMPACT_LINE_HEIGHT;
                barHeight = SUPER_COMPACT_BAR_HEIGHT;
                barGap = SUPER_COMPACT_BAR_GAP;
                prayerIconSize = SUPER_COMPACT_PRAYER_ICON_SIZE;
                prayerIconRowHeight = SUPER_COMPACT_PRAYER_ICON_ROW_HEIGHT;
                targetStripHeight = barHeight;
                break;
            case COMPACT:
                padding = COMPACT_PADDING;
                memberGap = COMPACT_MEMBER_GAP;
                lineHeight = COMPACT_LINE_HEIGHT;
                barHeight = COMPACT_BAR_HEIGHT;
                barGap = COMPACT_BAR_GAP;
                prayerIconSize = COMPACT_PRAYER_ICON_SIZE;
                prayerIconRowHeight = COMPACT_PRAYER_ICON_ROW_HEIGHT;
                targetStripHeight = barHeight;
                break;
            case NORMAL:
            default:
                padding = NORMAL_PADDING;
                memberGap = NORMAL_MEMBER_GAP;
                lineHeight = NORMAL_LINE_HEIGHT;
                barHeight = NORMAL_BAR_HEIGHT;
                barGap = NORMAL_BAR_GAP;
                prayerIconSize = NORMAL_PRAYER_ICON_SIZE;
                prayerIconRowHeight = NORMAL_PRAYER_ICON_ROW_HEIGHT;
                targetStripHeight = barHeight;
                break;
        }
    }

    private boolean isMinimal() {
        return config.partyOverlayScale() == GroupScapeTrackerConfig.PartyOverlayScale.MINIMAL;
    }

    private boolean isOrbGrid() {
        return config.partyOverlayScale() == GroupScapeTrackerConfig.PartyOverlayScale.ORB_GRID;
    }

    private boolean isScoreboard() {
        return config.partyOverlayScale() == GroupScapeTrackerConfig.PartyOverlayScale.SCOREBOARD;
    }

    /**
     * The base runescape-small font (~16pt) is sized for Normal's 13px line height; a flat -1/-2pt
     * offset from it still overflows Compact/Super Compact's 9-11px rows, which is what caused
     * labels to overlap the bar below them. Instead, shrink the font in half-point steps until its
     * actual metrics (not a guessed offset) fit the tightest row this tier draws text into - the
     * name row (lineHeight) for every tier, plus the bar row (barHeight + barGap) for tiers that
     * label their bars (everything except Minimal, whose bars are unlabeled fills).
     */
    private Font scaledFont(Graphics2D graphics) {
        Font base = FontManager.getRunescapeSmallFont();
        if (config.partyOverlayScale() == GroupScapeTrackerConfig.PartyOverlayScale.NORMAL) {
            return base;
        }

        int targetHeight = isMinimal() ? lineHeight : Math.min(lineHeight, barHeight + barGap);

        Font candidate = base;
        float size = base.getSize2D();
        FontMetrics metrics = graphics.getFontMetrics(candidate);
        while (metrics.getHeight() > targetHeight && size > 6f) {
            size -= 0.5f;
            candidate = base.deriveFont(size);
            metrics = graphics.getFontMetrics(candidate);
        }
        return candidate;
    }

    private Color bgColor() {
        int alpha = (int) Math.round(Math.max(0, Math.min(100, config.partyOverlayOpacity())) * 2.55);
        return new Color(BG_BASE.getRed(), BG_BASE.getGreen(), BG_BASE.getBlue(), alpha);
    }

    private List<RosterMember> buildMemberList(String localPlayerName) {
        List<RosterMember> members = new ArrayList<>();

        if (!config.partyOverlayHideSelf()) {
            members.add(buildSelfRow(localPlayerName));
        }

        for (RosterMember member : rosterState.all()) {
            if (member.name.equalsIgnoreCase(localPlayerName)) {
                continue;
            }
            if (config.partyOverlayHideOfflineMembers() && isOffline(member)) {
                continue;
            }
            if (config.partyOverlayHideOutOfVicinity()
                    && !isOffline(member)
                    && !withinVicinity(member, config.partyOverlayVicinityHideTiles())) {
                continue;
            }
            members.add(member);
        }

        return members;
    }

    /**
     * True if {@code member}'s actor is loaded in the local client's scene and within
     * {@code tiles} of the local player. The roster carries no synced world position, so distance
     * can only be confirmed for members RuneLite has actually rendered nearby - an unloaded actor
     * (different world, out of render distance) is treated as not within vicinity.
     */
    private boolean withinVicinity(RosterMember member, int tiles) {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return false;
        }
        for (Player player : client.getPlayers()) {
            if (player == null || player.getName() == null) {
                continue;
            }
            if (!player.getName().equalsIgnoreCase(member.name)) {
                continue;
            }
            return player.getWorldLocation().distanceTo(localPlayer.getWorldLocation()) <= tiles;
        }
        return false;
    }

    /** Reads the local player's own vitals straight from Client, avoiding any WebSocket round-trip. */
    private RosterMember buildSelfRow(String name) {
        return LocalRosterMemberFactory.build(client, dialogueTracker, rosterState);
    }

    private void sortMembers(List<RosterMember> members) {
        Map<RosterMember, Integer> joinOrder = new LinkedHashMap<>();
        for (int i = 0; i < members.size(); i++) {
            joinOrder.put(members.get(i), i);
        }

        Comparator<RosterMember> comparator;
        switch (config.partyOverlaySortOrder()) {
            case JOIN_ORDER_REVERSED:
                comparator = Comparator.<RosterMember>comparingInt(joinOrder::get).reversed();
                break;
            case ALPHABETICAL:
                comparator = Comparator.comparing(m -> m.name.toLowerCase());
                break;
            case LOWEST_HP_FIRST:
                comparator = Comparator.comparingInt(this::hpRatioForSort);
                break;
            case JOIN_ORDER:
            default:
                comparator = Comparator.comparingInt(joinOrder::get);
                break;
        }

        if (config.partyOverlayOfflineMembersLast()) {
            comparator = Comparator.comparing((RosterMember m) -> isOffline(m) ? 1 : 0).thenComparing(comparator);
        }
        members.sort(comparator);
    }

    private int hpRatioForSort(RosterMember member) {
        if (member.hp == null || member.maxHp == null || member.maxHp == 0) {
            return Integer.MAX_VALUE;
        }
        return (member.hp * 100) / member.maxHp;
    }

    private boolean isOffline(RosterMember member) {
        if (member.lastHeartbeatAt == null) {
            return true;
        }
        return Instant.now().toEpochMilli() - member.lastHeartbeatAt.toEpochMilli() >= RosterMember.OFFLINE_THRESHOLD_MS;
    }

    private int memberHeight(RosterMember member, boolean offline) {
        int height = nameRowHeight(member, offline); // name row

        if (offline) {
            return height + memberGap;
        }

        if (isMinimal()) {
            if (hasVisibleClusterBar()) height += barHeight + barGap;
            if (!config.partyOverlayHideTarget()) height += targetStripHeight + barGap;
            return height + memberGap;
        }

        if (!config.partyOverlayHideHp()) height += barHeight + barGap;
        if (!config.partyOverlayHidePrayer()) {
            height += barHeight + barGap;
        }
        if (!config.partyOverlayHideRun()) height += barHeight + barGap;
        if (!config.partyOverlayHideSpec()) height += barHeight + barGap;
        if (!config.partyOverlayHideTarget()) height += barHeight + barGap;
        return height + memberGap;
    }

    /**
     * Height of the name row, which now doubles as the active-prayer-icon row (icons sit between
     * the name and the right-aligned world/offline text), so it grows past {@link #lineHeight}
     * when the icons are taller than the text.
     */
    private int nameRowHeight(RosterMember member, boolean offline) {
        if (offline || config.partyOverlayHidePrayer() || config.partyOverlayHidePrayerIcons()
                || visibleActivePrayers(member).isEmpty()) {
            return lineHeight;
        }
        return Math.max(lineHeight, prayerIconRowHeight);
    }

    /** True if at least one of HP/Prayer/Run/Spec is visible, i.e. the minimal cluster row has something to draw. */
    private boolean hasVisibleClusterBar() {
        return !config.partyOverlayHideHp() || !config.partyOverlayHidePrayer()
                || !config.partyOverlayHideRun() || !config.partyOverlayHideSpec();
    }

    private int drawMember(Graphics2D graphics, RosterMember member, int y, boolean offline, boolean faded) {
        int startY = y;
        Color stripeColor = memberColor(member.color);

        float alpha = faded ? OFFLINE_ALPHA : 1f;
        java.awt.Composite originalComposite = graphics.getComposite();
        if (faded) {
            graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, alpha));
        }

        graphics.setColor(stripeColor);
        graphics.fillRect(padding, y, 2, memberHeight(member, offline) - memberGap);

        int textX = padding + 6;
        int barWidth = PANEL_WIDTH - textX - padding;

        int nameRowHeight = nameRowHeight(member, offline);
        FontMetrics metrics = graphics.getFontMetrics();
        int nameBaseline = y + (nameRowHeight + metrics.getAscent() - metrics.getDescent()) / 2;

        graphics.setColor(offline ? toGrayscale(TEXT) : TEXT);
        graphics.drawString(member.name, textX, nameBaseline);

        String status = offline ? "Offline" : (!config.partyOverlayHideWorld() && member.world != null ? "W" + member.world : null);
        if (status != null) {
            graphics.drawString(status, PANEL_WIDTH - padding - metrics.stringWidth(status), nameBaseline);
        }

        if (!offline && !config.partyOverlayHidePrayer() && !config.partyOverlayHidePrayerIcons()) {
            List<String> activePrayers = visibleActivePrayers(member);
            if (!activePrayers.isEmpty()) {
                int nameEndX = textX + metrics.stringWidth(member.name) + 6;
                int statusStartX = status != null
                        ? PANEL_WIDTH - padding - metrics.stringWidth(status) - 6
                        : PANEL_WIDTH - padding;
                int availableWidth = Math.max(0, statusStartX - nameEndX);
                int iconsY = y + (nameRowHeight - prayerIconSize) / 2;
                drawPrayerIcons(graphics, nameEndX, iconsY, availableWidth, activePrayers);
            }
        }

        y += nameRowHeight;

        if (offline) {
            if (faded) {
                graphics.setComposite(originalComposite);
            }
            return startY + memberHeight(member, offline);
        }

        if (isMinimal()) {
            if (hasVisibleClusterBar()) {
                drawMinimalCluster(graphics, textX, y, barWidth, member);
                y += barHeight + barGap;
            }

            if (!config.partyOverlayHideTarget()) {
                drawMinimalTargetStrip(graphics, textX, y, barWidth, member);
                y += targetStripHeight + barGap;
            }

            if (faded) {
                graphics.setComposite(originalComposite);
            }

            return startY + memberHeight(member, offline);
        }

        if (!config.partyOverlayHideHp()) {
            drawBar(graphics, textX, y, barWidth, "HP", member.hp, member.maxHp, HP_COLOR);
            y += barHeight + barGap;
        }

        if (!config.partyOverlayHidePrayer()) {
            drawBar(graphics, textX, y, barWidth, "Pr", member.prayer, member.maxPrayer, PRAYER_COLOR);
            y += barHeight + barGap;
        }

        if (!config.partyOverlayHideRun()) {
            drawBar(graphics, textX, y, barWidth, "Run", member.runEnergy, 100, RUN_COLOR);
            y += barHeight + barGap;
        }

        if (!config.partyOverlayHideSpec()) {
            drawBar(graphics, textX, y, barWidth, "Sp", member.specEnergy, 100, SPEC_COLOR);
            y += barHeight + barGap;
        }

        if (!config.partyOverlayHideTarget()) {
            drawTargetBar(graphics, textX, y, barWidth, member);
            y += barHeight + barGap;
        }

        if (faded) {
            graphics.setComposite(originalComposite);
        }

        return startY + memberHeight(member, offline);
    }

    private void drawBar(Graphics2D graphics, int x, int y, int width, String label, Integer value, Integer max, Color color) {
        int textBaseline = barTextBaseline(graphics, y);

        graphics.setColor(MUTED_TEXT);
        graphics.drawString(label, x, textBaseline);

        int labelWidth = 22;
        int barX = x + labelWidth;
        int barWidth = width - labelWidth - 26;

        graphics.setColor(TRACK_COLOR);
        graphics.fillRect(barX, y, barWidth, barHeight);

        if (value != null && max != null && max > 0) {
            int clampedValue = Math.max(0, Math.min(value, max));
            int filledWidth = (int) ((clampedValue / (double) max) * barWidth);
            graphics.setColor(color);
            graphics.fillRect(barX, y, filledWidth, barHeight);

            graphics.setColor(TEXT);
            graphics.drawString(String.valueOf(clampedValue), barX + barWidth + 4, textBaseline);
        } else {
            graphics.setColor(MUTED_TEXT);
            graphics.drawString("--", barX + barWidth + 4, textBaseline);
        }
    }

    /** Bottom-aligns bar label/value text inside a barHeight-tall row using the current font's actual descent. */
    private int barTextBaseline(Graphics2D graphics, int y) {
        return y + barHeight - graphics.getFontMetrics().getDescent();
    }

    /**
     * Renders the "target" row as an HP-style bar instead of plain text, laid out exactly like
     * {@link #drawBar} (label outside to the left, value outside to the right) so it lines up
     * with the HP/Pr/Run/Sp rows above it. Styled to match the webapp's player-interacting
     * component: red bar filled by HP ratio for an actual combat target (health scale &gt; 0),
     * full gold bar with no HP value for a neutral interaction (banking, talking to an NPC). The
     * target's name renders inside the bar and truncates with an ellipsis instead of overflowing.
     * Row is always drawn — reserving its height even with no target — so the panel doesn't
     * grow/shrink as members enter and leave combat; with no target it falls back to the same
     * muted-track/"--" look {@link #drawBar} uses for missing values, rather than going blank.
     */
    private void drawTargetBar(Graphics2D graphics, int x, int y, int width, RosterMember member) {
        if (member.targetName == null || member.targetName.isEmpty()) {
            drawBar(graphics, x, y, width, "Tgt", null, null, null);
            return;
        }

        boolean isEnemy = member.targetHealthScale != null && member.targetHealthScale > 0;
        boolean hasRatio = isEnemy && member.targetHealthRatio != null && member.targetHealthRatio >= 0;

        Color fill = isEnemy ? TARGET_COMBAT_FILL : TARGET_NEUTRAL_FILL;
        Color track = isEnemy ? TARGET_COMBAT_TRACK : TARGET_NEUTRAL_TRACK;
        Color border = isEnemy ? TARGET_COMBAT_BORDER : TARGET_NEUTRAL_BORDER;
        Color labelColor = isEnemy ? TARGET_COMBAT_LABEL : TARGET_NEUTRAL_LABEL;

        int textBaseline = barTextBaseline(graphics, y);
        graphics.setColor(labelColor);
        graphics.drawString("Tgt", x, textBaseline);

        FontMetrics metrics = graphics.getFontMetrics();
        String hpText = hasRatio ? targetHealthPercent(member) + "%" : null;
        int valueWidth = hpText != null ? metrics.stringWidth(hpText) + 4 : 0;

        int labelWidth = 22;
        int barX = x + labelWidth;
        int barWidth = Math.max(20, width - labelWidth - valueWidth);

        graphics.setColor(track);
        graphics.fillRect(barX, y, barWidth, barHeight);

        int filledWidth = barWidth;
        if (hasRatio) {
            filledWidth = (int) (targetHealthRatio(member) * barWidth);
        }
        graphics.setColor(fill);
        graphics.fillRect(barX, y, filledWidth, barHeight);

        graphics.setColor(border);
        graphics.drawRect(barX, y, barWidth - 1, barHeight - 1);

        graphics.setColor(TEXT);
        String name = truncateToWidth(metrics, member.targetName, Math.max(0, barWidth - 6));
        graphics.drawString(name, barX + 3, textBaseline);

        if (hasRatio) {
            graphics.setColor(labelColor);
            graphics.drawString(hpText, barX + barWidth + 4, textBaseline);
        }
    }

    /**
     * Minimal tier only: fuses whichever of HP/Prayer/Run/Spec aren't hidden into one row of
     * equal-width segments (color + fill, no label/number) instead of stacking them as separate
     * labeled bars. Hiding a bar via its own config toggle removes its segment and lets the
     * remaining ones grow to fill the freed width, rather than leaving a gap.
     */
    private void drawMinimalCluster(Graphics2D graphics, int x, int y, int width, RosterMember member) {
        List<Color> colors = new ArrayList<>(4);
        List<Double> ratios = new ArrayList<>(4);
        if (!config.partyOverlayHideHp()) {
            colors.add(HP_COLOR);
            ratios.add(ratio(member.hp, member.maxHp));
        }
        if (!config.partyOverlayHidePrayer()) {
            colors.add(PRAYER_COLOR);
            ratios.add(ratio(member.prayer, member.maxPrayer));
        }
        if (!config.partyOverlayHideRun()) {
            colors.add(RUN_COLOR);
            ratios.add(ratio(member.runEnergy, 100));
        }
        if (!config.partyOverlayHideSpec()) {
            colors.add(SPEC_COLOR);
            ratios.add(ratio(member.specEnergy, 100));
        }
        if (colors.isEmpty()) {
            return;
        }

        int segmentCount = colors.size();
        int gapTotal = MINIMAL_CLUSTER_SEGMENT_GAP * (segmentCount - 1);
        int segmentWidth = (width - gapTotal) / segmentCount;

        int segX = x;
        for (int i = 0; i < segmentCount; i++) {
            int w = (i == segmentCount - 1) ? (width - (segX - x)) : segmentWidth;

            graphics.setColor(TRACK_COLOR);
            graphics.fillRect(segX, y, w, barHeight);

            double r = ratios.get(i);
            if (r > 0) {
                graphics.setColor(colors.get(i));
                graphics.fillRect(segX, y, (int) Math.round(w * r), barHeight);
            }

            segX += w + MINIMAL_CLUSTER_SEGMENT_GAP;
        }
    }

    /**
     * Minimal tier only: renders the target row as a thin, label-free strip instead of
     * {@link #drawTargetBar}'s full bar-with-name-and-percentage, matching the cluster row's
     * color-and-fill-only style. Always drawn (muted/empty when there's no target) so the panel
     * doesn't resize as members enter and leave combat, mirroring drawTargetBar's convention.
     */
    private void drawMinimalTargetStrip(Graphics2D graphics, int x, int y, int width, RosterMember member) {
        Color track = TRACK_COLOR;
        Color fill = null;
        double ratio = 1.0;

        if (member.targetName != null && !member.targetName.isEmpty()) {
            boolean isEnemy = member.targetHealthScale != null && member.targetHealthScale > 0;
            boolean hasRatio = isEnemy && member.targetHealthRatio != null && member.targetHealthRatio >= 0;
            track = isEnemy ? TARGET_COMBAT_TRACK : TARGET_NEUTRAL_TRACK;
            fill = isEnemy ? TARGET_COMBAT_FILL : TARGET_NEUTRAL_FILL;
            if (hasRatio) {
                ratio = targetHealthRatio(member);
            }
        }

        graphics.setColor(track);
        graphics.fillRect(x, y, width, targetStripHeight);
        if (fill != null) {
            graphics.setColor(fill);
            graphics.fillRect(x, y, (int) Math.round(width * ratio), targetStripHeight);
        }
    }

    /** Clamped 0-1 ratio for a value/max pair, treating a missing value or non-positive max as empty. */
    private static double ratio(Integer value, Integer max) {
        if (value == null || max == null || max <= 0) {
            return 0;
        }
        return Math.max(0, Math.min(1.0, value / (double) max));
    }

    /** Clamped current/scale ratio for a target with a known health scale, mirroring the webapp's player-interacting component. */
    private static double targetHealthRatio(RosterMember member) {
        return Math.max(0, Math.min(1.0, member.targetHealthRatio / (double) member.targetHealthScale));
    }

    private static long targetHealthPercent(RosterMember member) {
        return Math.round(targetHealthRatio(member) * 100);
    }

    private static String truncateToWidth(FontMetrics metrics, String text, int maxWidth) {
        if (metrics.stringWidth(text) <= maxWidth) {
            return text;
        }

        String ellipsis = "...";
        int ellipsisWidth = metrics.stringWidth(ellipsis);
        if (maxWidth <= ellipsisWidth) {
            return "";
        }

        StringBuilder truncated = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            truncated.append(text.charAt(i));
            if (metrics.stringWidth(truncated.toString()) + ellipsisWidth > maxWidth) {
                truncated.setLength(truncated.length() - 1);
                break;
            }
        }
        return truncated + ellipsis;
    }

    /**
     * The member's active prayers, with base tri-prayers dropped when their upgraded curse
     * replacement (e.g. Deadeye over Rigour) is active too. Returns an empty list (not just a
     * missing field) so callers can use it directly to decide whether to reserve the icon row.
     */
    private static List<String> visibleActivePrayers(RosterMember member) {
        return PrayerVisibility.visible(member.activePrayers);
    }

    /**
     * Draws real prayer-tab sprites for each active prayer, overhead/protection prayers first
     * (gold-tinted), overflowing into a plain "+N" once the row runs out of width.
     */
    private void drawPrayerIcons(Graphics2D graphics, int x, int y, int availableWidth, List<String> activePrayerNames) {
        List<String> ordered = new ArrayList<>(activePrayerNames);
        ordered.sort(Comparator.comparingInt(name -> isOverheadPrayerName(name) ? 0 : 1));

        int maxIcons = Math.max(1, (availableWidth + PRAYER_ICON_GAP) / (prayerIconSize + PRAYER_ICON_GAP));

        int shownCount = ordered.size();
        int overflow = 0;
        if (shownCount > maxIcons) {
            overflow = shownCount - (maxIcons - 1);
            shownCount = maxIcons - 1;
        }

        int drawX = x;
        for (int i = 0; i < shownCount; i++) {
            drawX = drawPrayerIcon(graphics, drawX, y, ordered.get(i));
        }

        if (overflow > 0) {
            graphics.setColor(MUTED_TEXT);
            graphics.drawString("+" + overflow, drawX + 2, y + prayerIconSize - 3);
        }
    }

    /** Draws one prayer's sprite (with an overhead tint behind it if applicable) and returns the x for the next icon. */
    private int drawPrayerIcon(Graphics2D graphics, int x, int y, String prayerName) {
        Prayer prayer = parsePrayer(prayerName);
        BufferedImage sprite = prayer != null ? prayerSprites.get(prayer) : null;

        if (prayer != null && OVERHEAD_PRAYERS.contains(prayer)) {
            graphics.setColor(OVERHEAD_TINT);
            graphics.fillOval(x, y, prayerIconSize, prayerIconSize);
        }

        if (sprite != null) {
            // Sprites aren't all the same aspect ratio - stretching to a square box visibly
            // squishes the wider/taller ones, so scale uniformly and center instead.
            double scale = Math.min(prayerIconSize / (double) sprite.getWidth(), prayerIconSize / (double) sprite.getHeight());
            int drawWidth = (int) Math.round(sprite.getWidth() * scale);
            int drawHeight = (int) Math.round(sprite.getHeight() * scale);
            int drawX = x + (prayerIconSize - drawWidth) / 2;
            int drawY = y + (prayerIconSize - drawHeight) / 2;

            Object previousHint = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
            graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            graphics.drawImage(sprite, drawX, drawY, drawWidth, drawHeight, null);
            if (previousHint != null) {
                graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, previousHint);
            }
        } else {
            graphics.setColor(TRACK_COLOR);
            graphics.fillOval(x, y, prayerIconSize, prayerIconSize);
        }

        return x + prayerIconSize + PRAYER_ICON_GAP;
    }

    private static boolean isOverheadPrayerName(String prayerName) {
        Prayer prayer = parsePrayer(prayerName);
        return prayer != null && OVERHEAD_PRAYERS.contains(prayer);
    }

    private static Prayer parsePrayer(String prayerName) {
        try {
            return Prayer.valueOf(prayerName);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    /**
     * Faux-bolds text by drawing it twice with a slight horizontal offset. The RuneScape font is
     * a single-weight embedded TTF, so requesting {@link Font#BOLD} via deriveFont doesn't
     * reliably synthesize an actual bold glyph outline - this stroke-doubling trick is what
     * consistently reads as bold instead.
     */
    private static void drawBoldString(Graphics2D graphics, String text, float x, float y) {
        graphics.drawString(text, x, y);
        graphics.drawString(text, x + 0.6f, y);
    }

    /** Desaturates a color to gray while preserving its alpha and perceived brightness. */
    private static Color toGrayscale(Color c) {
        int gray = (int) Math.round(0.299 * c.getRed() + 0.587 * c.getGreen() + 0.114 * c.getBlue());
        return new Color(gray, gray, gray, c.getAlpha());
    }

    private static Color memberColor(String hex) {
        try {
            return Color.decode(hex);
        } catch (Exception e) {
            return BORDER;
        }
    }

    private void drawChrome(Graphics2D graphics, int width, int height) {
        graphics.setColor(bgColor());
        graphics.fillRoundRect(0, 0, width, height, 6, 6);
        graphics.setColor(BORDER);
        graphics.drawRoundRect(0, 0, width - 1, height - 1, 6, 6);
    }

}

package com.groupscape.roster;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Builds and caches the downward arrow/pin glyph used for ping markers on the minimap and world
 * map - deliberately a different silhouette from {@link MemberMapIcons}' helmet glyph so a ping
 * never reads as a member-position marker at a glance. Tinted per-pinger via the same hue as their
 * assigned color (see {@link com.groupscape.roster.RosterMember#color}).
 */
public class PingArrowIcons {
    private final Map<String, BufferedImage> cache = new ConcurrentHashMap<>();

    /** @param heightPx target rendered height, arrowhead included. */
    public BufferedImage get(String hexColor, int heightPx) {
        String key = hexColor + "@" + heightPx;
        return cache.computeIfAbsent(key, k -> render(hexColor, heightPx));
    }

    private static BufferedImage render(String hexColor, int heightPx) {
        Color fill;
        try {
            fill = Color.decode(hexColor);
        } catch (Exception e) {
            fill = Color.WHITE;
        }

        int width = Math.max(1, Math.round(heightPx * 0.85f));
        BufferedImage image = new BufferedImage(width, heightPx, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        int headHeight = Math.round(heightPx * 0.55f);
        int shaftWidth = Math.max(1, Math.round(width * 0.35f));
        int shaftX = (width - shaftWidth) / 2;

        Polygon arrow = new Polygon();
        arrow.addPoint(width / 2, heightPx - 1);
        arrow.addPoint(0, heightPx - 1 - headHeight);
        arrow.addPoint(shaftX, heightPx - 1 - headHeight);
        arrow.addPoint(shaftX, 0);
        arrow.addPoint(shaftX + shaftWidth, 0);
        arrow.addPoint(shaftX + shaftWidth, heightPx - 1 - headHeight);
        arrow.addPoint(width, heightPx - 1 - headHeight);

        g.setColor(fill);
        g.fillPolygon(arrow);
        g.setColor(Color.BLACK);
        g.drawPolygon(arrow);
        g.dispose();

        return image;
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import com.groupscape.HttpRequestService;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns the local player's own active pings: starting one (right-click menu entry or the hold-key
 * shortcut), re-broadcasting a live NPC ping's position each tick, and ending it on timeout,
 * despawn, or manual clear. A player can have at most one active NPC ping and one active tile ping
 * at the same time - starting a new ping only replaces a prior one of the same kind, so e.g.
 * pinging a tile doesn't clear an already-active NPC ping. Every send is a fire-and-forget
 * {@code POST} to {@code /api/characters/{accountHash}/ping}, relayed by the server to every
 * connected overlay (including this client - {@link PingState} is what actually renders it,
 * populated via {@link RosterClient.PingEventListener} regardless of who started the ping).
 *
 * <p>Only ever tracks an NPC ping's NPC by holding the same {@link NPC} object reference handed to
 * {@link #startNpcPing} - RuneLite keeps that instance stable for as long as the NPC hasn't
 * despawned, so no per-tick {@code client.getNpcs()} lookup is needed. This also sidesteps NPC
 * identity not being reliably comparable across different clients/instances: every other client
 * just renders wherever this client's updates say, never resolving the NPC themselves.
 */
@Slf4j
public class PingManager {
    /** Both the tile-ping lifetime and the NPC-ping safety-net ceiling (despawn/death ends it sooner). */
    private static final long MAX_DURATION_MS = 60_000;
    /** How often a live NPC ping re-sends its position - a fraction of a game tick's worth of
     * slack under typical ping, well below the 60s timeout, without spamming an update every tick. */
    private static final long NPC_UPDATE_INTERVAL_MS = 600;

    private final Client client;
    private final HttpRequestService httpRequestService;
    private final ExecutorService sendExecutor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "groupscape-ping-send");
        t.setDaemon(true);
        return t;
    });

    /** One in-flight ping of a single kind (NPC or tile) started by the local player. */
    private static class OwnPing {
        final String pingId;
        final long startedAtMs;
        /** Only set for an NPC ping - null for a tile ping. */
        NPC trackedNpc;
        long lastUpdateSentAtMs;
        int lastSentX;
        int lastSentY;
        int lastSentPlane;

        OwnPing(String pingId, long startedAtMs) {
            this.pingId = pingId;
            this.startedAtMs = startedAtMs;
        }
    }

    private OwnPing ownNpcPing;
    private OwnPing ownTilePing;

    public PingManager(Client client, HttpRequestService httpRequestService) {
        this.client = client;
        this.httpRequestService = httpRequestService;
    }

    public boolean hasOwnNpcPing() {
        return ownNpcPing != null;
    }

    public boolean hasOwnTilePing() {
        return ownTilePing != null;
    }

    public void startTilePing(WorldPoint worldPoint, GroupScapeTrackerConfig config) {
        if (worldPoint == null) {
            log.debug("Ping: startTilePing called with null worldPoint, ignoring");
            return;
        }
        String memberName = localPlayerName();
        if (memberName == null) {
            log.debug("Ping: startTilePing aborted, no local player name");
            return;
        }

        endTilePing(config);

        OwnPing ping = new OwnPing(UUID.randomUUID().toString(), System.currentTimeMillis());
        ping.lastSentX = worldPoint.getX();
        ping.lastSentY = worldPoint.getY();
        ping.lastSentPlane = worldPoint.getPlane();
        ownTilePing = ping;

        sendStart(ping.pingId, memberName, PingState.KIND_TILE, worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(), null, config);
    }

    public void startNpcPing(NPC npc, GroupScapeTrackerConfig config) {
        WorldPoint worldPoint = npc.getWorldLocation();
        if (worldPoint == null) {
            log.debug("Ping: startNpcPing aborted, NPC {} has no world location", npc.getName());
            return;
        }
        String memberName = localPlayerName();
        if (memberName == null) {
            log.debug("Ping: startNpcPing aborted, no local player name");
            return;
        }

        endNpcPing(config);

        OwnPing ping = new OwnPing(UUID.randomUUID().toString(), System.currentTimeMillis());
        ping.trackedNpc = npc;
        ping.lastUpdateSentAtMs = ping.startedAtMs;
        ping.lastSentX = worldPoint.getX();
        ping.lastSentY = worldPoint.getY();
        ping.lastSentPlane = worldPoint.getPlane();
        ownNpcPing = ping;

        sendStart(ping.pingId, memberName, PingState.KIND_NPC, worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(), npc.getName(), config);
    }

    /** Manual early clear of the local player's own NPC ping, if any. */
    public void clearOwnNpcPing(GroupScapeTrackerConfig config) {
        endNpcPing(config);
    }

    /** Manual early clear of the local player's own tile ping, if any. */
    public void clearOwnTilePing(GroupScapeTrackerConfig config) {
        endTilePing(config);
    }

    /**
     * Called by {@link com.groupscape.GroupScapeTrackerPlugin#onNpcDespawned} for every despawn -
     * ends the NPC ping if it happens to be the one we're tracking (death or ordinary despawn both
     * end it, per spec; there's no separate "died" signal worth distinguishing here).
     */
    public void onNpcDespawned(NPC npc, GroupScapeTrackerConfig config) {
        if (ownNpcPing != null && ownNpcPing.trackedNpc == npc) {
            endNpcPing(config);
        }
    }

    public void onGameTick(GroupScapeTrackerConfig config) {
        long now = System.currentTimeMillis();

        if (ownTilePing != null && now - ownTilePing.startedAtMs >= MAX_DURATION_MS) {
            endTilePing(config);
        }

        if (ownNpcPing != null) {
            if (now - ownNpcPing.startedAtMs >= MAX_DURATION_MS) {
                endNpcPing(config);
            } else if (ownNpcPing.trackedNpc == null) {
                endNpcPing(config);
            } else {
                WorldPoint worldPoint = ownNpcPing.trackedNpc.getWorldLocation();
                if (worldPoint != null) {
                    boolean moved = worldPoint.getX() != ownNpcPing.lastSentX
                            || worldPoint.getY() != ownNpcPing.lastSentY
                            || worldPoint.getPlane() != ownNpcPing.lastSentPlane;
                    if (moved && now - ownNpcPing.lastUpdateSentAtMs >= NPC_UPDATE_INTERVAL_MS) {
                        ownNpcPing.lastSentX = worldPoint.getX();
                        ownNpcPing.lastSentY = worldPoint.getY();
                        ownNpcPing.lastSentPlane = worldPoint.getPlane();
                        ownNpcPing.lastUpdateSentAtMs = now;
                        sendUpdate(ownNpcPing.pingId, worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(), config);
                    }
                }
            }
        }
    }

    public void shutdown() {
        sendExecutor.shutdownNow();
    }

    private void endNpcPing(GroupScapeTrackerConfig config) {
        if (ownNpcPing == null) return;
        sendEnd(ownNpcPing.pingId, config);
        ownNpcPing = null;
    }

    private void endTilePing(GroupScapeTrackerConfig config) {
        if (ownTilePing == null) return;
        sendEnd(ownTilePing.pingId, config);
        ownTilePing = null;
    }

    private String localPlayerName() {
        Player local = client.getLocalPlayer();
        return local == null ? null : local.getName();
    }

    private static class PingRequestBody {
        String action;
        String pingId;
        String memberName;
        String kind;
        Integer x;
        Integer y;
        Integer plane;
        String npcName;
    }

    private void sendStart(String pingId, String memberName, String kind, int x, int y, int plane, String npcName, GroupScapeTrackerConfig config) {
        PingRequestBody body = new PingRequestBody();
        body.action = "start";
        body.pingId = pingId;
        body.memberName = memberName;
        body.kind = kind;
        body.x = x;
        body.y = y;
        body.plane = plane;
        body.npcName = npcName;
        send(body, config);
    }

    private void sendUpdate(String pingId, int x, int y, int plane, GroupScapeTrackerConfig config) {
        PingRequestBody body = new PingRequestBody();
        body.action = "update";
        body.pingId = pingId;
        body.x = x;
        body.y = y;
        body.plane = plane;
        send(body, config);
    }

    private void sendEnd(String pingId, GroupScapeTrackerConfig config) {
        PingRequestBody body = new PingRequestBody();
        body.action = "end";
        body.pingId = pingId;
        send(body, config);
    }

    /** Fire-and-forget - never called from the client thread's blocking path. */
    private void send(PingRequestBody body, GroupScapeTrackerConfig config) {
        String apiKey = config.apiKey().trim();
        long accountHashValue = client.getAccountHash();
        if (apiKey.isEmpty() || accountHashValue == -1) {
            log.debug("Ping: not sending {} - apiKey empty={}, accountHash={}", body.action, apiKey.isEmpty(), accountHashValue);
            return;
        }

        String url = httpRequestService.getBaseUrl() + "/api/characters/" + accountHashValue + "/ping";
        sendExecutor.submit(() -> {
            HttpRequestService.HttpResponse response = httpRequestService.post(url, apiKey, body);
            if (!response.isSuccessful()) {
                log.debug("ping {} failed: {} {}", body.action, response.getCode(), response.getBody());
            } else {
                log.debug("ping {} sent ok (pingId={})", body.action, body.pingId);
            }
        });
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws every active ping's arrow marker on the minimap, hue-tinted per pinger. Only pings whose
 * tile is currently within the loaded scene resolve a minimap position ({@link LocalPoint#fromWorld}
 * returns null otherwise), which naturally limits this to pings near the local player - same
 * scoping {@link MinimapLocationOverlay} gets for free from RuneLite's own {@code Player} actors.
 */
public class PingMinimapOverlay extends Overlay {
    private static final int ICON_HEIGHT = 14;
    private static final int HOVER_RADIUS_PX = 8;

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final PingState pingState;
    private final RosterState rosterState;
    private final TooltipManager tooltipManager;
    private final PingArrowIcons icons;

    public PingMinimapOverlay(Client client, GroupScapeTrackerConfig config, PingState pingState,
                               RosterState rosterState, TooltipManager tooltipManager, PingArrowIcons icons) {
        this.client = client;
        this.config = config;
        this.pingState = pingState;
        this.rosterState = rosterState;
        this.tooltipManager = tooltipManager;
        this.icons = icons;
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.pingsEnabled()) {
            return null;
        }

        Point mouse = client.getMouseCanvasPosition();

        for (PingState.ActivePing ping : pingState.all()) {
            if (ping.plane != client.getPlane()) continue;

            LocalPoint localPoint = LocalPoint.fromWorld(client, new WorldPoint(ping.worldX, ping.worldY, ping.plane));
            if (localPoint == null) continue;

            Point loc = Perspective.localToMinimap(client, localPoint);
            if (loc == null) continue;

            RosterMember member = rosterState.findByName(ping.memberName);
            String hex = member != null ? member.color : "#808080";
            BufferedImage icon = icons.get(hex, ICON_HEIGHT);
            graphics.drawImage(icon, loc.getX() - icon.getWidth() / 2, loc.getY() - icon.getHeight(), null);

            if (mouse != null && mouse.distanceTo(loc) <= HOVER_RADIUS_PX) {
                String label = ping.npcName != null ? ping.memberName + " pinged " + ping.npcName : ping.memberName + " pinged here";
                tooltipManager.add(new Tooltip(label));
            }
        }

        return null;
    }
}

package com.groupscape.roster;

import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Every group member's currently active ping (right-click/hotkey on an NPC or tile), keyed by
 * ping id, as reported over the party overlay WebSocket. {@link RosterClient.PingEventListener}
 * writes to this; the minimap/world-map/viewport overlays read from it. Includes the local
 * player's own ping too - the server relays everything it publishes back to the sender as well,
 * so this is the single source of truth for "what pings are currently active", not just other
 * members'.
 */
public class PingState {
    public static final String KIND_TILE = "tile";
    public static final String KIND_NPC = "npc";

    public static class ActivePing {
        public final String pingId;
        public final String memberName;
        public final String kind;
        public final String npcName;
        public volatile int worldX;
        public volatile int worldY;
        public volatile int plane;

        ActivePing(String pingId, String memberName, String kind, int worldX, int worldY, int plane, String npcName) {
            this.pingId = pingId;
            this.memberName = memberName;
            this.kind = kind;
            this.worldX = worldX;
            this.worldY = worldY;
            this.plane = plane;
            this.npcName = npcName;
        }
    }

    private final Map<String, ActivePing> pingsById = new ConcurrentHashMap<>();

    public void start(RosterWireTypes.PingStartPayload payload) {
        pingsById.put(payload.pingId,
                new ActivePing(payload.pingId, payload.memberName, payload.kind, payload.x, payload.y, payload.plane, payload.npcName));
    }

    public void update(RosterWireTypes.PingUpdatePayload payload) {
        ActivePing ping = pingsById.get(payload.pingId);
        if (ping != null) {
            ping.worldX = payload.x;
            ping.worldY = payload.y;
            ping.plane = payload.plane;
        }
    }

    public void end(RosterWireTypes.PingEndPayload payload) {
        pingsById.remove(payload.pingId);
    }

    public Collection<ActivePing> all() {
        return pingsById.values();
    }

    public void clear() {
        pingsById.clear();
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Draws every active ping visible in the local player's game scene: both a tile ping and an NPC
 * ping outline the ground tile itself (not the NPC's 3D model hull - a moving NPC's hull is a
 * poor match for "the tile RuneLite says it's on" a tick later anyway); a tile ping also gets a
 * solid connector line up to its arrow, plus a gradient beam column (see {@link BeamRenderer}),
 * and an NPC ping gets an arrow floating at a fixed height above the tile with no beam.
 */
public class PingViewportOverlay extends Overlay {
    private static final int BEAM_HEIGHT = 140;
    private static final int NPC_ARROW_HEIGHT = 190;

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final PingState pingState;
    private final RosterState rosterState;

    public PingViewportOverlay(Client client, GroupScapeTrackerConfig config, PingState pingState, RosterState rosterState) {
        this.client = client;
        this.config = config;
        this.pingState = pingState;
        this.rosterState = rosterState;
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.pingsEnabled()) {
            return null;
        }

        for (PingState.ActivePing ping : pingState.all()) {
            if (ping.plane != client.getPlane()) continue;

            WorldPoint worldPoint = new WorldPoint(ping.worldX, ping.worldY, ping.plane);
            LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
            if (localPoint == null) continue;

            Color color = colorFor(ping.memberName);
            drawTileOutline(graphics, localPoint, color);

            boolean isNpc = PingState.KIND_NPC.equals(ping.kind);
            if (!isNpc) {
                Point top = Perspective.localToCanvas(client, localPoint, client.getPlane(), BEAM_HEIGHT);
                Point bottom = Perspective.localToCanvas(client, localPoint, client.getPlane(), 0);
                BeamRenderer.draw(graphics, top, bottom, color);
            }

            if (isNpc) {
                drawArrowAt(graphics, localPoint, NPC_ARROW_HEIGHT, color);
            } else {
                drawBeamAndArrow(graphics, localPoint, BEAM_HEIGHT, color);
            }
        }

        return null;
    }

    private void drawTileOutline(Graphics2D graphics, LocalPoint localPoint, Color color) {
        Polygon tilePoly = Perspective.getCanvasTilePoly(client, localPoint);
        if (tilePoly != null) {
            graphics.setColor(color);
            graphics.setStroke(new BasicStroke(2));
            graphics.draw(tilePoly);
        }
    }

    private void drawArrowAt(Graphics2D graphics, LocalPoint localPoint, int height, Color color) {
        Point arrowPoint = Perspective.localToCanvas(client, localPoint, client.getPlane(), height);
        if (arrowPoint != null) {
            drawArrowGlyph(graphics, arrowPoint.getX(), arrowPoint.getY(), color);
        }
    }

    private void drawBeamAndArrow(Graphics2D graphics, LocalPoint localPoint, int beamHeight, Color color) {
        Point top = Perspective.localToCanvas(client, localPoint, client.getPlane(), beamHeight);
        Point bottom = Perspective.localToCanvas(client, localPoint, client.getPlane(), 0);
        if (top == null || bottom == null) return;

        graphics.setColor(color);
        graphics.setStroke(new BasicStroke(3));
        graphics.drawLine(top.getX(), top.getY(), bottom.getX(), bottom.getY());
        drawArrowGlyph(graphics, top.getX(), top.getY(), color);
    }

    /** A small downward-pointing arrow, tip at {@code (tipX, tipY)} - same motif as the
     * minimap/world map/web markers ({@link PingArrowIcons}), just drawn directly instead of
     * cached as an image since a viewport marker's screen position changes every frame. */
    private void drawArrowGlyph(Graphics2D graphics, int tipX, int tipY, Color color) {
        int headWidth = 13;
        int headHeight = 8;
        int shaftWidth = 5;
        int shaftHeight = 12;

        Polygon arrow = new Polygon();
        arrow.addPoint(tipX, tipY);
        arrow.addPoint(tipX - headWidth / 2, tipY - headHeight);
        arrow.addPoint(tipX - shaftWidth / 2, tipY - headHeight);
        arrow.addPoint(tipX - shaftWidth / 2, tipY - headHeight - shaftHeight);
        arrow.addPoint(tipX + shaftWidth / 2, tipY - headHeight - shaftHeight);
        arrow.addPoint(tipX + shaftWidth / 2, tipY - headHeight);
        arrow.addPoint(tipX + headWidth / 2, tipY - headHeight);

        graphics.setColor(color);
        graphics.fillPolygon(arrow);
        graphics.setColor(Color.BLACK);
        graphics.setStroke(new BasicStroke(1));
        graphics.drawPolygon(arrow);
    }

    private Color colorFor(String memberName) {
        RosterMember member = rosterState.findByName(memberName);
        String hex = member != null ? member.color : "#808080";
        try {
            return Color.decode(hex);
        } catch (Exception e) {
            return Color.WHITE;
        }
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Keeps one {@link WorldMapPoint} per active ping in sync with {@link PingState}, called from a
 * game tick - same pattern as {@link GroupWorldMapPoints}, but keyed by ping id instead of member
 * name and deliberately not filtered by world/plane: unlike a member's live position, a ping's
 * whole point is "meet/look here", which is still useful to see even if you're not currently on
 * the same world as the pinger.
 */
public class PingWorldMapPoints {
    private static final int ICON_HEIGHT = 20;

    private final GroupScapeTrackerConfig config;
    private final PingState pingState;
    private final RosterState rosterState;
    private final WorldMapPointManager worldMapPointManager;
    private final PingArrowIcons icons;
    private final Map<String, WorldMapPoint> pointsByPingId = new HashMap<>();

    public PingWorldMapPoints(GroupScapeTrackerConfig config, PingState pingState, RosterState rosterState,
                               WorldMapPointManager worldMapPointManager, PingArrowIcons icons) {
        this.config = config;
        this.pingState = pingState;
        this.rosterState = rosterState;
        this.worldMapPointManager = worldMapPointManager;
        this.icons = icons;
    }

    public void sync() {
        if (!config.pingsEnabled()) {
            clear();
            return;
        }

        Map<String, PingState.ActivePing> active = new HashMap<>();
        for (PingState.ActivePing ping : pingState.all()) {
            active.put(ping.pingId, ping);
        }

        Iterator<Map.Entry<String, WorldMapPoint>> it = pointsByPingId.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, WorldMapPoint> entry = it.next();
            if (!active.containsKey(entry.getKey())) {
                worldMapPointManager.remove(entry.getValue());
                it.remove();
            }
        }

        for (PingState.ActivePing ping : active.values()) {
            WorldPoint worldPoint = new WorldPoint(ping.worldX, ping.worldY, ping.plane);
            RosterMember member = rosterState.findByName(ping.memberName);
            String hex = member != null ? member.color : "#808080";
            String tooltip = ping.npcName != null ? ping.memberName + " pinged " + ping.npcName : ping.memberName + " pinged here";

            WorldMapPoint point = pointsByPingId.get(ping.pingId);
            if (point == null) {
                point = new WorldMapPoint(worldPoint, icons.get(hex, ICON_HEIGHT));
                point.setName(tooltip);
                point.setTooltip(tooltip);
                point.setSnapToEdge(true);
                point.setJumpOnClick(true);
                pointsByPingId.put(ping.pingId, point);
                worldMapPointManager.add(point);
            } else {
                point.setWorldPoint(worldPoint);
                point.setImage(icons.get(hex, ICON_HEIGHT));
                point.setTooltip(tooltip);
            }
        }
    }

    public void clear() {
        for (WorldMapPoint point : pointsByPingId.values()) {
            worldMapPointManager.remove(point);
        }
        pointsByPingId.clear();
    }
}

package com.groupscape.roster;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.util.ImageUtil;

/**
 * Builds and caches the badge glyph for a raid marker type: the type's real OSRS wiki icon (or, for
 * a type with no wiki icon - see {@link RaidMarkerType#iconResource} - its {@link
 * RaidMarkerType#displayName} drawn as a bold text glyph) centered on a colored circle, used
 * identically in the viewport, minimap, and world map overlays so a marker reads the same
 * everywhere - unlike plain pings, which are only ever tinted by pinger color (see {@link
 * PingArrowIcons}), a raid marker's whole point is being recognizable by type at a glance.
 */
public class RaidMarkerIcons {
    private static final Map<RaidMarkerType, BufferedImage> BASE_ICONS = new EnumMap<>(RaidMarkerType.class);

    static {
        for (RaidMarkerType type : RaidMarkerType.values()) {
            if (type.iconResource != null) {
                BASE_ICONS.put(type, ImageUtil.loadImageResource(RaidMarkerIcons.class, type.iconResource));
            }
        }
    }

    private final Map<String, BufferedImage> cache = new ConcurrentHashMap<>();

    /** @param heightPx target rendered badge diameter. */
    public BufferedImage get(RaidMarkerType type, int heightPx) {
        String key = type.name() + "@" + heightPx;
        return cache.computeIfAbsent(key, k -> render(type, heightPx));
    }

    private static BufferedImage render(RaidMarkerType type, int heightPx) {
        BufferedImage badge = new BufferedImage(heightPx, heightPx, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = badge.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        Color fill = type.color();
        g.setColor(new Color(fill.getRed(), fill.getGreen(), fill.getBlue(), 210));
        g.fillOval(0, 0, heightPx - 1, heightPx - 1);
        g.setColor(Color.BLACK);
        g.drawOval(0, 0, heightPx - 1, heightPx - 1);

        BufferedImage base = BASE_ICONS.get(type);
        if (base != null) {
            int iconSize = Math.max(1, Math.round(heightPx * 0.6f));
            int offset = (heightPx - iconSize) / 2;
            g.drawImage(base, offset, offset, iconSize, iconSize, null);
        } else {
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setFont(g.getFont().deriveFont(Font.BOLD, heightPx * 0.55f));
            g.setColor(Color.WHITE);
            FontMetrics metrics = g.getFontMetrics();
            String glyph = type.displayName;
            int textX = (heightPx - metrics.stringWidth(glyph)) / 2;
            int textY = (heightPx - metrics.getHeight()) / 2 + metrics.getAscent();
            g.drawString(glyph, textX, textY);
        }
        g.dispose();

        return badge;
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import com.groupscape.HttpRequestService;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns the local player's own active raid markers: up to one marker of each {@link RaidMarkerType}
 * on a tile and one of each type on an NPC (8 independent slots total), started from the
 * "Raid Markers" right-click submenu. Unlike {@link PingManager}, a marker never auto-expires - it
 * is cleared only by a manual clear/redrop, the tracked NPC despawning, or the plugin shutting
 * down/logging out ({@link com.groupscape.GroupScapeTrackerPlugin#onGameStateChanged}). Every send
 * is a fire-and-forget {@code POST} to {@code /api/characters/{accountHash}/raid-marker}, relayed
 * by the server to every connected overlay (including this client - {@link RaidMarkerState} is
 * what actually renders it).
 */
@Slf4j
public class RaidMarkerManager {
    /** How often a live NPC marker re-sends its position - same cadence as {@link PingManager}. */
    private static final long NPC_UPDATE_INTERVAL_MS = 600;

    private final Client client;
    private final HttpRequestService httpRequestService;
    private final ExecutorService sendExecutor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "groupscape-raid-marker-send");
        t.setDaemon(true);
        return t;
    });

    /** One in-flight marker of a single type+kind started by the local player. */
    private static class OwnMarker {
        final String markerId;
        /** Only set for an NPC marker - null for a tile marker. */
        NPC trackedNpc;
        long lastUpdateSentAtMs;
        int lastSentX;
        int lastSentY;
        int lastSentPlane;

        OwnMarker(String markerId) {
            this.markerId = markerId;
        }
    }

    private final Map<RaidMarkerType, OwnMarker> ownTileMarkers = new EnumMap<>(RaidMarkerType.class);
    private final Map<RaidMarkerType, OwnMarker> ownNpcMarkers = new EnumMap<>(RaidMarkerType.class);

    public RaidMarkerManager(Client client, HttpRequestService httpRequestService) {
        this.client = client;
        this.httpRequestService = httpRequestService;
    }

    public boolean hasOwnTileMarker(RaidMarkerType type) {
        return ownTileMarkers.containsKey(type);
    }

    public boolean hasOwnNpcMarker(RaidMarkerType type) {
        return ownNpcMarkers.containsKey(type);
    }

    /** Every marker type the local player currently has active on this exact NPC. */
    public Set<RaidMarkerType> ownMarkerTypesOnNpc(NPC npc) {
        Set<RaidMarkerType> types = EnumSet.noneOf(RaidMarkerType.class);
        for (Map.Entry<RaidMarkerType, OwnMarker> entry : ownNpcMarkers.entrySet()) {
            if (entry.getValue().trackedNpc == npc) {
                types.add(entry.getKey());
            }
        }
        return types;
    }

    /** Every marker type the local player currently has active on this exact tile. */
    public Set<RaidMarkerType> ownMarkerTypesOnTile(WorldPoint worldPoint) {
        Set<RaidMarkerType> types = EnumSet.noneOf(RaidMarkerType.class);
        for (Map.Entry<RaidMarkerType, OwnMarker> entry : ownTileMarkers.entrySet()) {
            OwnMarker marker = entry.getValue();
            if (marker.lastSentX == worldPoint.getX() && marker.lastSentY == worldPoint.getY()
                    && marker.lastSentPlane == worldPoint.getPlane()) {
                types.add(entry.getKey());
            }
        }
        return types;
    }

    public void dropTileMarker(RaidMarkerType type, WorldPoint worldPoint, GroupScapeTrackerConfig config) {
        if (worldPoint == null) {
            return;
        }
        String memberName = localPlayerName();
        if (memberName == null) {
            return;
        }

        clearOwnTileMarker(type, config);

        OwnMarker marker = new OwnMarker(UUID.randomUUID().toString());
        marker.lastSentX = worldPoint.getX();
        marker.lastSentY = worldPoint.getY();
        marker.lastSentPlane = worldPoint.getPlane();
        ownTileMarkers.put(type, marker);

        sendStart(marker.markerId, memberName, type, RaidMarkerState.KIND_TILE,
                worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(), null, config);
    }

    public void dropNpcMarker(RaidMarkerType type, NPC npc, GroupScapeTrackerConfig config) {
        WorldPoint worldPoint = npc.getWorldLocation();
        if (worldPoint == null) {
            return;
        }
        String memberName = localPlayerName();
        if (memberName == null) {
            return;
        }

        clearOwnNpcMarker(type, config);

        OwnMarker marker = new OwnMarker(UUID.randomUUID().toString());
        marker.trackedNpc = npc;
        marker.lastUpdateSentAtMs = System.currentTimeMillis();
        marker.lastSentX = worldPoint.getX();
        marker.lastSentY = worldPoint.getY();
        marker.lastSentPlane = worldPoint.getPlane();
        ownNpcMarkers.put(type, marker);

        sendStart(marker.markerId, memberName, type, RaidMarkerState.KIND_NPC,
                worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(), npc.getName(), config);
    }

    public void clearOwnTileMarker(RaidMarkerType type, GroupScapeTrackerConfig config) {
        OwnMarker marker = ownTileMarkers.remove(type);
        if (marker != null) {
            sendEnd(marker.markerId, config);
        }
    }

    public void clearOwnNpcMarker(RaidMarkerType type, GroupScapeTrackerConfig config) {
        OwnMarker marker = ownNpcMarkers.remove(type);
        if (marker != null) {
            sendEnd(marker.markerId, config);
        }
    }

    public void clearOwnMarkersOnNpc(NPC npc, GroupScapeTrackerConfig config) {
        for (RaidMarkerType type : ownMarkerTypesOnNpc(npc)) {
            clearOwnNpcMarker(type, config);
        }
    }

    public void clearOwnMarkersOnTile(WorldPoint worldPoint, GroupScapeTrackerConfig config) {
        for (RaidMarkerType type : ownMarkerTypesOnTile(worldPoint)) {
            clearOwnTileMarker(type, config);
        }
    }

    /** Clears every active marker (all 8 slots) at once - used on logout/hop/plugin shutdown, since
     * unlike a ping a marker never auto-expires on its own. */
    public void clearAll(GroupScapeTrackerConfig config) {
        for (RaidMarkerType type : RaidMarkerType.values()) {
            clearOwnTileMarker(type, config);
            clearOwnNpcMarker(type, config);
        }
    }

    /** Called by {@link com.groupscape.GroupScapeTrackerPlugin#onNpcDespawned} for every despawn -
     * ends any marker tracking that specific NPC (death or ordinary despawn both end it). */
    public void onNpcDespawned(NPC npc, GroupScapeTrackerConfig config) {
        clearOwnMarkersOnNpc(npc, config);
    }

    /** No expiry check, unlike {@link PingManager#onGameTick} - only re-sends a live NPC marker's
     * position as it moves. */
    public void onGameTick(GroupScapeTrackerConfig config) {
        long now = System.currentTimeMillis();
        for (OwnMarker marker : ownNpcMarkers.values()) {
            if (marker.trackedNpc == null) {
                continue;
            }
            WorldPoint worldPoint = marker.trackedNpc.getWorldLocation();
            if (worldPoint == null) {
                continue;
            }
            boolean moved = worldPoint.getX() != marker.lastSentX
                    || worldPoint.getY() != marker.lastSentY
                    || worldPoint.getPlane() != marker.lastSentPlane;
            if (moved && now - marker.lastUpdateSentAtMs >= NPC_UPDATE_INTERVAL_MS) {
                marker.lastSentX = worldPoint.getX();
                marker.lastSentY = worldPoint.getY();
                marker.lastSentPlane = worldPoint.getPlane();
                marker.lastUpdateSentAtMs = now;
                sendUpdate(marker.markerId, worldPoint.getX(), worldPoint.getY(), worldPoint.getPlane(), config);
            }
        }
    }

    public void shutdown() {
        sendExecutor.shutdownNow();
    }

    private String localPlayerName() {
        Player local = client.getLocalPlayer();
        return local == null ? null : local.getName();
    }

    private static class RaidMarkerRequestBody {
        String action;
        String markerId;
        String memberName;
        String markerType;
        String kind;
        Integer x;
        Integer y;
        Integer plane;
        String npcName;
    }

    private void sendStart(String markerId, String memberName, RaidMarkerType type, String kind,
                            int x, int y, int plane, String npcName, GroupScapeTrackerConfig config) {
        RaidMarkerRequestBody body = new RaidMarkerRequestBody();
        body.action = "start";
        body.markerId = markerId;
        body.memberName = memberName;
        body.markerType = type.wireValue;
        body.kind = kind;
        body.x = x;
        body.y = y;
        body.plane = plane;
        body.npcName = npcName;
        send(body, config);
    }

    private void sendUpdate(String markerId, int x, int y, int plane, GroupScapeTrackerConfig config) {
        RaidMarkerRequestBody body = new RaidMarkerRequestBody();
        body.action = "update";
        body.markerId = markerId;
        body.x = x;
        body.y = y;
        body.plane = plane;
        send(body, config);
    }

    private void sendEnd(String markerId, GroupScapeTrackerConfig config) {
        RaidMarkerRequestBody body = new RaidMarkerRequestBody();
        body.action = "end";
        body.markerId = markerId;
        send(body, config);
    }

    /** Fire-and-forget - never called from the client thread's blocking path. */
    private void send(RaidMarkerRequestBody body, GroupScapeTrackerConfig config) {
        String apiKey = config.apiKey().trim();
        long accountHashValue = client.getAccountHash();
        if (apiKey.isEmpty() || accountHashValue == -1) {
            log.debug("RaidMarker: not sending {} - apiKey empty={}, accountHash={}", body.action, apiKey.isEmpty(), accountHashValue);
            return;
        }

        String url = httpRequestService.getBaseUrl() + "/api/characters/" + accountHashValue + "/raid-marker";
        sendExecutor.submit(() -> {
            HttpRequestService.HttpResponse response = httpRequestService.post(url, apiKey, body);
            if (!response.isSuccessful()) {
                log.debug("raid marker {} failed: {} {}", body.action, response.getCode(), response.getBody());
            } else {
                log.debug("raid marker {} sent ok (markerId={})", body.action, body.markerId);
            }
        });
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws every active raid marker's badge icon on the minimap - see {@link PingMinimapOverlay} for
 * the equivalent plain-ping rendering this mirrors. Only markers whose tile is currently within
 * the loaded scene resolve a minimap position, same scoping the ping version gets.
 */
public class RaidMarkerMinimapOverlay extends Overlay {
    private static final int ICON_HEIGHT = 16;
    private static final int HOVER_RADIUS_PX = 8;

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final RaidMarkerState raidMarkerState;
    private final TooltipManager tooltipManager;
    private final RaidMarkerIcons icons;

    public RaidMarkerMinimapOverlay(Client client, GroupScapeTrackerConfig config, RaidMarkerState raidMarkerState,
                                     TooltipManager tooltipManager, RaidMarkerIcons icons) {
        this.client = client;
        this.config = config;
        this.raidMarkerState = raidMarkerState;
        this.tooltipManager = tooltipManager;
        this.icons = icons;
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.raidMarkersEnabled()) {
            return null;
        }

        Point mouse = client.getMouseCanvasPosition();

        for (RaidMarkerState.ActiveMarker marker : raidMarkerState.all()) {
            if (marker.plane != client.getPlane()) continue;

            LocalPoint localPoint = LocalPoint.fromWorld(client, new WorldPoint(marker.worldX, marker.worldY, marker.plane));
            if (localPoint == null) continue;

            Point loc = Perspective.localToMinimap(client, localPoint);
            if (loc == null) continue;

            BufferedImage icon = icons.get(marker.markerType, ICON_HEIGHT);
            graphics.drawImage(icon, loc.getX() - icon.getWidth() / 2, loc.getY() - icon.getHeight() / 2, null);

            if (mouse != null && mouse.distanceTo(loc) <= HOVER_RADIUS_PX) {
                tooltipManager.add(new Tooltip(markerLabel(marker)));
            }
        }

        return null;
    }

    static String markerLabel(RaidMarkerState.ActiveMarker marker) {
        return marker.npcName != null
                ? marker.memberName + "'s " + marker.markerType.displayName + " on " + marker.npcName
                : marker.memberName + "'s " + marker.markerType.displayName;
    }
}

package com.groupscape.roster;

import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Every group member's currently active raid markers, keyed by marker id, as reported over the
 * party overlay WebSocket - see {@link PingState} for the equivalent plain-ping version this
 * mirrors. Unlike a ping, a marker never auto-expires, so this only ever changes on an explicit
 * start/update/end.
 */
public class RaidMarkerState {
    public static final String KIND_TILE = "tile";
    public static final String KIND_NPC = "npc";

    public static class ActiveMarker {
        public final String markerId;
        public final String memberName;
        public final RaidMarkerType markerType;
        public final String kind;
        public final String npcName;
        public volatile int worldX;
        public volatile int worldY;
        public volatile int plane;

        ActiveMarker(String markerId, String memberName, RaidMarkerType markerType, String kind,
                     int worldX, int worldY, int plane, String npcName) {
            this.markerId = markerId;
            this.memberName = memberName;
            this.markerType = markerType;
            this.kind = kind;
            this.worldX = worldX;
            this.worldY = worldY;
            this.plane = plane;
            this.npcName = npcName;
        }
    }

    private final Map<String, ActiveMarker> markersById = new ConcurrentHashMap<>();

    public void start(RosterWireTypes.RaidMarkerStartPayload payload) {
        RaidMarkerType type = RaidMarkerType.fromWireValue(payload.markerType);
        if (type == null) {
            return;
        }
        markersById.put(payload.markerId,
                new ActiveMarker(payload.markerId, payload.memberName, type, payload.kind,
                        payload.x, payload.y, payload.plane, payload.npcName));
    }

    public void update(RosterWireTypes.RaidMarkerUpdatePayload payload) {
        ActiveMarker marker = markersById.get(payload.markerId);
        if (marker != null) {
            marker.worldX = payload.x;
            marker.worldY = payload.y;
            marker.plane = payload.plane;
        }
    }

    public void end(RosterWireTypes.RaidMarkerEndPayload payload) {
        markersById.remove(payload.markerId);
    }

    public Collection<ActiveMarker> all() {
        return markersById.values();
    }

    public void clear() {
        markersById.clear();
    }
}

package com.groupscape.roster;

import java.awt.Color;

/**
 * The fixed set of raid-callout marker types (see {@link RaidMarkerManager}). The four "standard"
 * types have a real OSRS wiki icon bundled as a plugin resource and a display color shared with the
 * web app's palette (kept in sync with {@code main.css}'s {@code --clue-hard}/{@code
 * --rarity-uncommon}/{@code --clue-master}/{@code --rarity-very-rare} tokens). The 1-4/A-D callout
 * types have no wiki icon to draw on - {@code iconResource} is {@code null} for those and {@link
 * RaidMarkerIcons} falls back to drawing the {@link #displayName} as a text glyph instead.
 */
public enum RaidMarkerType {
    DANGER("Danger", "danger", "#e0574f", "raid-marker-danger.png"),
    DEFEND("Defend", "defend", "#4caf50", "raid-marker-defend.png"),
    LOOT("Loot", "loot", "#d4af37", "raid-marker-loot.png"),
    FOCUS("Focus / Kill Target", "focus", "#a855f7", "raid-marker-focus.png"),

    A("A", "a", "#f97316", null),
    B("B", "b", "#ec4899", null),
    C("C", "c", "#84cc16", null),
    D("D", "d", "#64748b", null),

    ONE("1", "one", "#3b82f6", null),
    TWO("2", "two", "#0ea5e9", null),
    THREE("3", "three", "#14b8a6", null),
    FOUR("4", "four", "#6366f1", null);

    public final String displayName;
    /** The value sent over the wire - matches the server's {@code websocket::MarkerType} snake_case rename. */
    public final String wireValue;
    public final String hexColor;
    /** A bundled plugin resource path, or {@code null} for a type with no real wiki icon (drawn as a text glyph instead). */
    public final String iconResource;

    RaidMarkerType(String displayName, String wireValue, String hexColor, String iconResource) {
        this.displayName = displayName;
        this.wireValue = wireValue;
        this.hexColor = hexColor;
        this.iconResource = iconResource;
    }

    public Color color() {
        return Color.decode(hexColor);
    }

    public static RaidMarkerType fromWireValue(String wireValue) {
        for (RaidMarkerType type : values()) {
            if (type.wireValue.equals(wireValue)) {
                return type;
            }
        }
        return null;
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Draws every active raid marker visible in the local player's game scene: a tile outline in the
 * marker type's color plus the type's badge icon floating above it (see {@link RaidMarkerIcons}),
 * and - only for a tile marker, never an NPC marker - a gradient beam column (see
 * {@link BeamRenderer}). See {@link PingViewportOverlay} for the equivalent plain-ping rendering
 * this mirrors; unlike that overlay a marker never expires, so there's no timeout logic here.
 */
public class RaidMarkerViewportOverlay extends Overlay {
    private static final int ICON_HEIGHT = 32;
    private static final int MARKER_HEIGHT = 170;
    private static final float MARKER_ALPHA = 0.5f;

    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final RaidMarkerState raidMarkerState;
    private final RaidMarkerIcons icons;

    public RaidMarkerViewportOverlay(Client client, GroupScapeTrackerConfig config,
                                      RaidMarkerState raidMarkerState, RaidMarkerIcons icons) {
        this.client = client;
        this.config = config;
        this.raidMarkerState = raidMarkerState;
        this.icons = icons;
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.raidMarkersEnabled()) {
            return null;
        }

        Composite originalComposite = graphics.getComposite();
        graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, MARKER_ALPHA));

        for (RaidMarkerState.ActiveMarker marker : raidMarkerState.all()) {
            if (marker.plane != client.getPlane()) continue;

            WorldPoint worldPoint = new WorldPoint(marker.worldX, marker.worldY, marker.plane);
            LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);
            if (localPoint == null) continue;

            Color color = marker.markerType.color();
            drawTileOutline(graphics, localPoint, color);

            if (RaidMarkerState.KIND_TILE.equals(marker.kind)) {
                Point top = Perspective.localToCanvas(client, localPoint, client.getPlane(), MARKER_HEIGHT);
                Point bottom = Perspective.localToCanvas(client, localPoint, client.getPlane(), 0);
                BeamRenderer.draw(graphics, top, bottom, color);
            }

            drawIcon(graphics, localPoint, marker.markerType);
        }

        graphics.setComposite(originalComposite);
        return null;
    }

    private void drawTileOutline(Graphics2D graphics, LocalPoint localPoint, Color color) {
        Polygon tilePoly = Perspective.getCanvasTilePoly(client, localPoint);
        if (tilePoly != null) {
            graphics.setColor(color);
            graphics.setStroke(new BasicStroke(2));
            graphics.draw(tilePoly);
        }
    }

    private void drawIcon(Graphics2D graphics, LocalPoint localPoint, RaidMarkerType type) {
        Point iconPoint = Perspective.localToCanvas(client, localPoint, client.getPlane(), MARKER_HEIGHT);
        if (iconPoint == null) return;
        BufferedImage icon = icons.get(type, ICON_HEIGHT);
        graphics.drawImage(icon, iconPoint.getX() - icon.getWidth() / 2, iconPoint.getY() - icon.getHeight() / 2, null);
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/**
 * Keeps one {@link WorldMapPoint} per active raid marker in sync with {@link RaidMarkerState},
 * called from a game tick - see {@link PingWorldMapPoints} for the equivalent plain-ping version
 * this mirrors, including why it's deliberately not filtered by world/plane.
 */
public class RaidMarkerWorldMapPoints {
    private static final int ICON_HEIGHT = 24;

    private final GroupScapeTrackerConfig config;
    private final RaidMarkerState raidMarkerState;
    private final WorldMapPointManager worldMapPointManager;
    private final RaidMarkerIcons icons;
    private final Map<String, WorldMapPoint> pointsByMarkerId = new HashMap<>();

    public RaidMarkerWorldMapPoints(GroupScapeTrackerConfig config, RaidMarkerState raidMarkerState,
                                     WorldMapPointManager worldMapPointManager, RaidMarkerIcons icons) {
        this.config = config;
        this.raidMarkerState = raidMarkerState;
        this.worldMapPointManager = worldMapPointManager;
        this.icons = icons;
    }

    public void sync() {
        if (!config.raidMarkersEnabled()) {
            clear();
            return;
        }

        Map<String, RaidMarkerState.ActiveMarker> active = new HashMap<>();
        for (RaidMarkerState.ActiveMarker marker : raidMarkerState.all()) {
            active.put(marker.markerId, marker);
        }

        Iterator<Map.Entry<String, WorldMapPoint>> it = pointsByMarkerId.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, WorldMapPoint> entry = it.next();
            if (!active.containsKey(entry.getKey())) {
                worldMapPointManager.remove(entry.getValue());
                it.remove();
            }
        }

        for (RaidMarkerState.ActiveMarker marker : active.values()) {
            WorldPoint worldPoint = new WorldPoint(marker.worldX, marker.worldY, marker.plane);
            String tooltip = RaidMarkerMinimapOverlay.markerLabel(marker);

            WorldMapPoint point = pointsByMarkerId.get(marker.markerId);
            if (point == null) {
                point = new WorldMapPoint(worldPoint, icons.get(marker.markerType, ICON_HEIGHT));
                point.setName(tooltip);
                point.setTooltip(tooltip);
                point.setSnapToEdge(true);
                point.setJumpOnClick(true);
                pointsByMarkerId.put(marker.markerId, point);
                worldMapPointManager.add(point);
            } else {
                point.setWorldPoint(worldPoint);
                point.setImage(icons.get(marker.markerType, ICON_HEIGHT));
                point.setTooltip(tooltip);
            }
        }
    }

    public void clear() {
        for (WorldMapPoint point : pointsByMarkerId.values()) {
            worldMapPointManager.remove(point);
        }
        pointsByMarkerId.clear();
    }
}

package com.groupscape.roster;

import com.groupscape.GroupLinkListener;
import com.google.gson.Gson;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/**
 * Real-time roster feed for the party overlay. Connects to the server's
 * `/api/characters/{accountHash}/ws` endpoint using the same API-key
 * `Authorization` header as the plugin's existing HTTP telemetry POSTs, gets
 * one `roster_snapshot` handshake, then applies `vitals_update` deltas as
 * they arrive. Auto-reconnects with a fixed delay on any close/failure.
 */
@Slf4j
public class RosterClient {
    private static final int RECONNECT_DELAY_SECONDS = 5;
    private static final String ROSTER_SNAPSHOT = "roster_snapshot";
    private static final String VITALS_UPDATE = "vitals_update";
    private static final String KILL_EVENT = "kill_event";
    private static final String DROP_EVENT = "drop_event";
    private static final String COLOR_UPDATE = "color_update";
    private static final String PING_START = "ping_start";
    private static final String PING_UPDATE = "ping_update";
    private static final String PING_END = "ping_end";
    private static final String MARKER_START = "marker_start";
    private static final String MARKER_UPDATE = "marker_update";
    private static final String MARKER_END = "marker_end";
    private static final String CHAT_MESSAGE = "chat_message";
    private static final String CHAT_READ = "chat_read";

    /** Notified when another group member's kill arrives over the websocket. */
    public interface KillEventListener {
        void onKillEvent(String memberName, String npcName);
    }

    /** Notified when a group member's notable drop arrives over the websocket. */
    public interface DropEventListener {
        void onDropEvent(String memberName, String message);
    }

    /**
     * Notified as a group member's ping (right-click/hotkey on an NPC or tile) starts, moves
     * (live NPC tracking - see {@link com.groupscape.roster.PingManager}), or ends. Includes the
     * local player's own pings too, since the server relays everything it publishes back to every
     * connected overlay including the sender.
     */
    public interface PingEventListener {
        void onPingStart(RosterWireTypes.PingStartPayload payload);
        void onPingUpdate(RosterWireTypes.PingUpdatePayload payload);
        void onPingEnd(RosterWireTypes.PingEndPayload payload);
    }

    /**
     * Notified as a group member's raid marker (see {@link com.groupscape.roster.RaidMarkerManager})
     * starts, moves (live NPC tracking), or ends. Includes the local player's own markers too, same
     * as {@link PingEventListener}.
     */
    public interface RaidMarkerEventListener {
        void onMarkerStart(RosterWireTypes.RaidMarkerStartPayload payload);
        void onMarkerUpdate(RosterWireTypes.RaidMarkerUpdatePayload payload);
        void onMarkerEnd(RosterWireTypes.RaidMarkerEndPayload payload);
    }

    /** Notified as a group chat message (in-game {@code !gs} or webapp-sent) arrives - see the "!gs" chat spec §3. */
    public interface ChatEventListener {
        void onChatMessage(RosterWireTypes.ChatMessagePayload payload, String ts);
    }

    /** Notified as any of the account's sessions advances its read cursor - see the "!gs" chat
     * spec §6. Kept as its own interface (rather than a second method on {@link ChatEventListener})
     * so that interface stays a plain functional interface for its existing lambda callers. */
    public interface ChatReadEventListener {
        void onChatRead(RosterWireTypes.ChatReadPayload payload);
    }

    private final OkHttpClient okHttpClient;
    private final Gson gson;
    private final RosterState rosterState;
    private final KillEventListener killEventListener;
    private final DropEventListener dropEventListener;
    private final PingEventListener pingEventListener;
    private final RaidMarkerEventListener raidMarkerEventListener;
    private final ChatEventListener chatEventListener;
    private final ChatReadEventListener chatReadEventListener;
    private final GroupLinkListener groupLinkListener;
    private final ScheduledExecutorService reconnectExecutor =
            Executors.newSingleThreadScheduledExecutor(r -> {
                Thread t = new Thread(r, "groupscape-roster-reconnect");
                t.setDaemon(true);
                return t;
            });

    private WebSocket webSocket;
    private volatile boolean intentionallyClosed = true;
    private String connectedBaseUrl;
    private String connectedAccountHash;
    private String connectedApiKey;

    public RosterClient(OkHttpClient okHttpClient, Gson gson, RosterState rosterState, KillEventListener killEventListener,
                         DropEventListener dropEventListener, PingEventListener pingEventListener,
                         RaidMarkerEventListener raidMarkerEventListener, ChatEventListener chatEventListener,
                         ChatReadEventListener chatReadEventListener, GroupLinkListener groupLinkListener) {
        // Derived from the shared RuneLite client (never mutate that one - other plugins use it).
        // Without a ping interval, a half-open connection (e.g. the backend disappearing behind a
        // proxy/LB during a rebuild without sending a clean close) never fires onClosed/onFailure,
        // so scheduleReconnect() below never runs and the overlay stays dead until RuneLite restarts.
        this.okHttpClient = okHttpClient.newBuilder()
                .pingInterval(15, TimeUnit.SECONDS)
                .build();
        this.gson = gson;
        this.rosterState = rosterState;
        this.killEventListener = killEventListener;
        this.dropEventListener = dropEventListener;
        this.pingEventListener = pingEventListener;
        this.raidMarkerEventListener = raidMarkerEventListener;
        this.chatEventListener = chatEventListener;
        this.chatReadEventListener = chatReadEventListener;
        this.groupLinkListener = groupLinkListener;
    }

    /** No-op if already connected to this exact baseUrl+accountHash+apiKey. */
    public synchronized void connect(String baseUrl, String accountHash, String apiKey) {
        if (baseUrl == null || accountHash == null || apiKey == null || apiKey.trim().isEmpty()) {
            disconnect();
            return;
        }
        if (webSocket != null
                && baseUrl.equals(connectedBaseUrl)
                && accountHash.equals(connectedAccountHash)
                && apiKey.equals(connectedApiKey)) {
            return;
        }

        disconnect();
        intentionallyClosed = false;
        connectedBaseUrl = baseUrl;
        connectedAccountHash = accountHash;
        connectedApiKey = apiKey;
        openSocket(baseUrl, accountHash, apiKey);
    }

    public synchronized void disconnect() {
        intentionallyClosed = true;
        connectedBaseUrl = null;
        connectedAccountHash = null;
        connectedApiKey = null;
        if (webSocket != null) {
            webSocket.close(1000, "client disconnect");
            webSocket = null;
        }
        rosterState.clear();
    }

    public void shutdown() {
        disconnect();
        reconnectExecutor.shutdownNow();
    }

    private void openSocket(String baseUrl, String accountHash, String apiKey) {
        String wsUrl = toWebSocketUrl(baseUrl) + "/api/characters/" + accountHash + "/ws";
        Request request = new Request.Builder().url(wsUrl).header("Authorization", apiKey).build();

        webSocket = okHttpClient.newWebSocket(request, new WebSocketListener() {
            @Override
            public void onOpen(WebSocket webSocket, Response response) {
                log.info("Party overlay WebSocket connected (accountHash={})", accountHash);
                groupLinkListener.onLinked();
            }

            @Override
            public void onMessage(WebSocket webSocket, String text) {
                handleMessage(text);
            }

            @Override
            public void onClosed(WebSocket webSocket, int code, String reason) {
                log.info("Party overlay WebSocket closed (accountHash={}, code={}, reason={})", accountHash, code, reason);
                scheduleReconnect(baseUrl, accountHash, apiKey);
            }

            @Override
            public void onFailure(WebSocket webSocket, Throwable t, Response response) {
                log.warn("Party overlay WebSocket failure (accountHash={}, httpStatus={}): {}",
                        accountHash, response != null ? response.code() : "n/a", t.toString());
                if (response != null && response.code() == 403) {
                    groupLinkListener.onLinkRequired();
                }
                scheduleReconnect(baseUrl, accountHash, apiKey);
            }
        });
    }

    private static String toWebSocketUrl(String baseUrl) {
        if (baseUrl.startsWith("https://")) {
            return "wss://" + baseUrl.substring("https://".length());
        }
        if (baseUrl.startsWith("http://")) {
            return "ws://" + baseUrl.substring("http://".length());
        }
        return baseUrl;
    }

    private void handleMessage(String text) {
        try {
            RosterWireTypes.Envelope envelope = gson.fromJson(text, RosterWireTypes.Envelope.class);
            if (envelope == null || envelope.type == null || envelope.payload == null) {
                return;
            }

            if (ROSTER_SNAPSHOT.equals(envelope.type)) {
                RosterWireTypes.RosterSnapshotPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.RosterSnapshotPayload.class);
                rosterState.replaceAll(payload.roster);
            } else if (VITALS_UPDATE.equals(envelope.type)) {
                RosterWireTypes.VitalsUpdatePayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.VitalsUpdatePayload.class);
                if (payload.name != null) {
                    rosterState.getOrCreate(payload.name).applyVitals(payload.vitals);
                }
            } else if (KILL_EVENT.equals(envelope.type)) {
                RosterWireTypes.KillEventPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.KillEventPayload.class);
                if (payload.memberName != null && payload.npcName != null) {
                    killEventListener.onKillEvent(payload.memberName, payload.npcName);
                }
            } else if (DROP_EVENT.equals(envelope.type)) {
                RosterWireTypes.DropEventPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.DropEventPayload.class);
                if (payload.memberName != null && payload.message != null) {
                    dropEventListener.onDropEvent(payload.memberName, payload.message);
                }
            } else if (COLOR_UPDATE.equals(envelope.type)) {
                RosterWireTypes.ColorUpdatePayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.ColorUpdatePayload.class);
                if (payload.name != null && payload.color != null) {
                    rosterState.getOrCreate(payload.name).color = payload.color;
                }
            } else if (PING_START.equals(envelope.type)) {
                RosterWireTypes.PingStartPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.PingStartPayload.class);
                if (payload.pingId != null && payload.memberName != null) {
                    pingEventListener.onPingStart(payload);
                }
            } else if (PING_UPDATE.equals(envelope.type)) {
                RosterWireTypes.PingUpdatePayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.PingUpdatePayload.class);
                if (payload.pingId != null) {
                    pingEventListener.onPingUpdate(payload);
                }
            } else if (PING_END.equals(envelope.type)) {
                RosterWireTypes.PingEndPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.PingEndPayload.class);
                if (payload.pingId != null) {
                    pingEventListener.onPingEnd(payload);
                }
            } else if (MARKER_START.equals(envelope.type)) {
                RosterWireTypes.RaidMarkerStartPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.RaidMarkerStartPayload.class);
                if (payload.markerId != null && payload.memberName != null && payload.markerType != null) {
                    raidMarkerEventListener.onMarkerStart(payload);
                }
            } else if (MARKER_UPDATE.equals(envelope.type)) {
                RosterWireTypes.RaidMarkerUpdatePayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.RaidMarkerUpdatePayload.class);
                if (payload.markerId != null) {
                    raidMarkerEventListener.onMarkerUpdate(payload);
                }
            } else if (MARKER_END.equals(envelope.type)) {
                RosterWireTypes.RaidMarkerEndPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.RaidMarkerEndPayload.class);
                if (payload.markerId != null) {
                    raidMarkerEventListener.onMarkerEnd(payload);
                }
            } else if (CHAT_MESSAGE.equals(envelope.type)) {
                RosterWireTypes.ChatMessagePayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.ChatMessagePayload.class);
                if (payload.text != null) {
                    chatEventListener.onChatMessage(payload, envelope.ts);
                }
            } else if (CHAT_READ.equals(envelope.type)) {
                RosterWireTypes.ChatReadPayload payload =
                        gson.fromJson(envelope.payload, RosterWireTypes.ChatReadPayload.class);
                if (payload.memberName != null && payload.messageId > 0) {
                    chatReadEventListener.onChatRead(payload);
                }
            }
        } catch (Exception e) {
            log.warn("Failed to parse party overlay message: {}", e.toString());
        }
    }

    private synchronized void scheduleReconnect(String baseUrl, String accountHash, String apiKey) {
        if (intentionallyClosed) return;
        log.info("Party overlay WebSocket reconnect scheduled in {}s (accountHash={})", RECONNECT_DELAY_SECONDS, accountHash);
        reconnectExecutor.schedule(() -> {
            synchronized (this) {
                if (!intentionallyClosed
                        && accountHash.equals(connectedAccountHash)
                        && apiKey.equals(connectedApiKey)) {
                    log.info("Party overlay WebSocket reconnecting (accountHash={})", accountHash);
                    openSocket(baseUrl, accountHash, apiKey);
                }
            }
        }, RECONNECT_DELAY_SECONDS, TimeUnit.SECONDS);
    }
}

package com.groupscape.roster;

import java.time.Instant;
import java.util.Collections;
import java.util.List;

/** Mutable per-member vitals snapshot the overlay renders from. */
public class RosterMember {
    /**
     * Shared by {@code PartyFrameOverlay}, {@code RosterListPanel}, {@code MinimapLocationOverlay},
     * {@code GroupWorldMapPoints}, and {@code RosterNotifier} so they all agree on "offline".
     *
     * <p>Must stay comfortably above {@code DataManager.HEARTBEAT_INTERVAL_MILLIS} (30s) - a
     * member's idle heartbeat lands roughly every 30-31s (1s poll granularity) plus whatever
     * network latency, so a threshold equal to the interval left no margin: any jitter tipped an
     * online member into "offline" for a chunk of every cycle. 60s matches the margin the web
     * app's own online badge already uses ({@code admin_account_is_online_column} in db.rs).
     */
    public static final long OFFLINE_THRESHOLD_MS = 60_000;

    public final String name;
    public String color = "#808080";

    public Integer hp;
    public Integer maxHp;
    public Integer prayer;
    public Integer maxPrayer;
    public Integer runEnergy;
    public Integer specEnergy;
    public Integer world;
    public Instant lastHeartbeatAt;
    public String targetName;
    public Integer targetHealthRatio;
    public Integer targetHealthScale;
    public List<String> activePrayers = Collections.emptyList();
    public String richPresence;
    public Integer worldX;
    public Integer worldY;
    public Integer plane;

    public RosterMember(String name) {
        this.name = name;
    }

    public void applyVitals(RosterWireTypes.WireVitals vitals) {
        if (vitals == null) return;

        // The server sends hp/maxHp/prayer/maxPrayer/runEnergy/world as one all-or-nothing bundle,
        // going all-null for a single missed heartbeat tick. Only overwrite them together when the
        // bundle actually has data, so one missed heartbeat doesn't blank the overlay instantly -
        // stale values persist until isOffline() trips past OFFLINE_THRESHOLD_MS.
        if (vitals.hp != null || vitals.maxHp != null) {
            this.hp = vitals.hp;
            this.maxHp = vitals.maxHp;
            this.prayer = vitals.prayer;
            this.maxPrayer = vitals.maxPrayer;
            this.runEnergy = vitals.runEnergy;
            this.world = vitals.world;
        }
        this.specEnergy = vitals.specEnergy;
        this.targetName = vitals.targetName;
        this.targetHealthRatio = vitals.targetHealthRatio;
        this.targetHealthScale = vitals.targetHealthScale;
        this.activePrayers = vitals.activePrayers != null ? vitals.activePrayers : Collections.emptyList();
        this.richPresence = vitals.richPresence;

        // Sent independently of the hp/prayer bundle above - a heartbeat can carry a position
        // update without touching vitals, so this isn't gated by the same all-or-nothing check.
        if (vitals.coordinates != null && vitals.coordinates.size() >= 3) {
            this.worldX = vitals.coordinates.get(0);
            this.worldY = vitals.coordinates.get(1);
            this.plane = vitals.coordinates.get(2);
        }

        if (vitals.lastHeartbeatAt != null) {
            try {
                this.lastHeartbeatAt = Instant.parse(vitals.lastHeartbeatAt);
            } catch (Exception ignored) {
                this.lastHeartbeatAt = null;
            }
        } else {
            // No heartbeat on record for this member (e.g. they've never sent vitals) -
            // null means offline (see isOffline()), not "just seen".
            this.lastHeartbeatAt = null;
        }
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Detects notification-worthy transitions in the roster (a member coming online/offline, a
 * member's HP dropping below the configured threshold) and returns chat message strings for the
 * plugin to send, so all {@code ChatMessageManager} usage stays centralized there. Mirrors the
 * armed/rearm hysteresis idiom {@code GroupScapeTrackerPlugin.checkLowHpAlert} already uses for
 * the local player's own HP.
 */
public class RosterNotifier {
    private static final double LOW_HP_REARM_MULTIPLIER = 2.0;

    private final Map<String, Boolean> onlineByName = new HashMap<>();
    private final Map<String, Boolean> lowHpArmedByName = new HashMap<>();

    public List<String> check(List<RosterMember> members, String localPlayerName, GroupScapeTrackerConfig config) {
        List<String> messages = new ArrayList<>();

        for (RosterMember member : members) {
            if (member.name.equalsIgnoreCase(localPlayerName)) {
                continue;
            }
            checkOnlineOffline(member, config, messages);
            checkLowHp(member, config, messages);
        }

        return messages;
    }

    private void checkOnlineOffline(RosterMember member, GroupScapeTrackerConfig config, List<String> messages) {
        boolean isOnline = !isOffline(member);
        Boolean wasOnline = onlineByName.put(member.name, isOnline);

        // First observation of this member - nothing to compare against, so don't fire a
        // notification burst the moment the roster/plugin connects.
        if (wasOnline == null) {
            return;
        }

        if (wasOnline && !isOnline && config.notifyMemberOffline()) {
            messages.add(member.name + " has gone offline.");
        } else if (!wasOnline && isOnline && config.notifyMemberOnline()) {
            messages.add(member.name + " has come online.");
        }
    }

    private void checkLowHp(RosterMember member, GroupScapeTrackerConfig config, List<String> messages) {
        if (member.hp == null || member.maxHp == null || member.maxHp <= 0) {
            return;
        }

        double ratio = (double) member.hp / member.maxHp;
        double threshold = config.lowHpNotifyThreshold() / 100.0;
        double rearmRatio = Math.min(threshold * LOW_HP_REARM_MULTIPLIER, 1.0);
        boolean armed = lowHpArmedByName.getOrDefault(member.name, true);

        if (armed && ratio < threshold) {
            lowHpArmedByName.put(member.name, false);
            if (config.notifyLowHp()) {
                messages.add(member.name + " is low on HP! (" + member.hp + "/" + member.maxHp + ")");
            }
        } else if (!armed && ratio >= rearmRatio) {
            lowHpArmedByName.put(member.name, true);
        }
    }

    private boolean isOffline(RosterMember member) {
        if (member.lastHeartbeatAt == null) {
            return true;
        }
        return Instant.now().toEpochMilli() - member.lastHeartbeatAt.toEpochMilli() >= RosterMember.OFFLINE_THRESHOLD_MS;
    }
}

package com.groupscape.roster;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Thread-safe in-memory roster: written from the WebSocket callback thread, read from the overlay render thread. */
public class RosterState {
    private final Map<String, RosterMember> members = new LinkedHashMap<>();

    public synchronized void replaceAll(List<RosterWireTypes.RosterMemberEntry> roster) {
        members.clear();
        if (roster == null) return;

        for (RosterWireTypes.RosterMemberEntry entry : roster) {
            RosterMember member = new RosterMember(entry.name);
            member.color = entry.color != null ? entry.color : member.color;
            member.applyVitals(entry.vitals);
            members.put(entry.name, member);
        }
    }

    public synchronized RosterMember getOrCreate(String name) {
        return members.computeIfAbsent(name, RosterMember::new);
    }

    public synchronized List<RosterMember> all() {
        return new ArrayList<>(members.values());
    }

    /** Case-insensitive - matches how {@code MinimapLocationOverlay}/{@code TileHighlightOverlay} already look up a member by their {@code Player} actor's name. */
    public synchronized RosterMember findByName(String name) {
        for (RosterMember member : members.values()) {
            if (member.name.equalsIgnoreCase(name)) {
                return member;
            }
        }
        return null;
    }

    public synchronized void clear() {
        members.clear();
    }
}

package com.groupscape.roster;

import java.util.List;

/**
 * DTOs mirroring the server's WebSocket wire format
 * (`groupscape-web/server/src/websocket.rs`). Field names match the JSON
 * keys exactly (server serializes camelCase) so Gson's default reflection
 * can deserialize without extra annotations.
 */
public class RosterWireTypes {
    public static class Envelope {
        public String type;
        public com.google.gson.JsonObject payload;
        public String ts;
    }

    public static class RosterSnapshotPayload {
        public List<RosterMemberEntry> roster;
    }

    public static class RosterMemberEntry {
        public String name;
        public String color;
        public WireVitals vitals;
    }

    public static class VitalsUpdatePayload {
        public String name;
        public WireVitals vitals;
    }

    public static class KillEventPayload {
        public String memberName;
        public String npcName;
    }

    public static class DropEventPayload {
        public String memberName;
        public String message;
    }

    public static class ColorUpdatePayload {
        public String name;
        public String color;
    }

    public static class PingStartPayload {
        public String pingId;
        public String memberName;
        /** {@code "tile"} or {@code "npc"} - see the server's {@code websocket::PingKind}. */
        public String kind;
        public int x;
        public int y;
        public int plane;
        public String npcName;
    }

    public static class PingUpdatePayload {
        public String pingId;
        public int x;
        public int y;
        public int plane;
    }

    public static class PingEndPayload {
        public String pingId;
    }

    public static class RaidMarkerStartPayload {
        public String markerId;
        public String memberName;
        /** e.g. {@code "danger"}, {@code "defend"}, {@code "loot"}, {@code "focus"}, {@code "one"}..{@code "four"}, {@code "a"}..{@code "d"} - see the server's {@code websocket::MarkerType}. */
        public String markerType;
        /** {@code "tile"} or {@code "npc"} - see the server's {@code websocket::PingKind}. */
        public String kind;
        public int x;
        public int y;
        public int plane;
        public String npcName;
    }

    public static class RaidMarkerUpdatePayload {
        public String markerId;
        public int x;
        public int y;
        public int plane;
    }

    public static class RaidMarkerEndPayload {
        public String markerId;
    }

    public static class ChatMessagePayload {
        public long messageId;
        /** Nullable - an account with no resolved character can still send. */
        public String memberName;
        public String text;
    }

    /** {@code chat_read} envelope - fires when any of the account's sessions advances its
     * server-side read cursor (spec §6). {@code memberName} identifies whose cursor advanced, the
     * same self-filtering pattern as {@code ChatRateLimitedPayload} on the server side - the
     * receiver checks it against the local player's own name to tell "one of my other sessions
     * just read chat" apart from "someone else in the group did". */
    public static class ChatReadPayload {
        public String memberName;
        public long messageId;
    }

    public static class WireVitals {
        public Integer hp;
        public Integer maxHp;
        public Integer prayer;
        public Integer maxPrayer;
        public Integer runEnergy;
        public Integer specEnergy;
        public Integer world;
        public String lastHeartbeatAt;
        public String targetName;
        public Integer targetHealthRatio;
        public Integer targetHealthScale;
        public List<String> activePrayers;
        public String richPresence;
        /** {@code [x, y, plane, ...]} - see the server's {@code WireVitals.coordinates}. */
        public List<Integer> coordinates;
    }
}

package com.groupscape.roster;

import com.groupscape.GroupScapeTrackerConfig;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

/**
 * Outlines the tile of every group member currently rendered in the local player's game scene.
 * {@link Player#getCanvasTilePoly()} already returns null when an actor isn't projectable onto
 * the canvas, so that's used as the "visible on screen" check - no separate occlusion raycasting.
 */
public class TileHighlightOverlay extends Overlay {
    private final Client client;
    private final GroupScapeTrackerConfig config;
    private final RosterState rosterState;

    public TileHighlightOverlay(Client client, GroupScapeTrackerConfig config, RosterState rosterState) {
        this.client = client;
        this.config = config;
        this.rosterState = rosterState;
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.tileHighlightEnabled()) {
            return null;
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return null;
        }

        graphics.setStroke(new BasicStroke(config.tileHighlightStrokeWidth()));

        for (Player player : client.getPlayers()) {
            if (player == null || player == localPlayer || player.getName() == null) {
                continue;
            }

            RosterMember member = findMember(player.getName());
            if (member == null) {
                continue;
            }

            Shape tilePoly = player.getCanvasTilePoly();
            if (tilePoly == null) {
                continue;
            }

            graphics.setColor(highlightColor(member.color));
            graphics.draw(tilePoly);
        }

        return null;
    }

    private RosterMember findMember(String playerName) {
        for (RosterMember member : rosterState.all()) {
            if (member.name.equalsIgnoreCase(playerName)) {
                return member;
            }
        }
        return null;
    }

    private Color highlightColor(String hex) {
        int alpha = (int) Math.round(Math.max(0, Math.min(100, config.tileHighlightOpacity())) * 2.55);
        try {
            Color base = Color.decode(hex);
            return new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
        } catch (Exception e) {
            return new Color(255, 255, 255, alpha);
        }
    }
}

package com.groupscape.roster;

import java.awt.Rectangle;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;

/**
 * Reverses {@code WorldMapOverlay.mapWorldPointToGraphicsPoint} (RuneLite has no built-in
 * canvas-to-world helper for the world map - only the forward direction, used for drawing markers)
 * so a right-click on the world map can resolve to a {@link WorldPoint} for a ping. Derived by
 * decompiling that method in {@code client-1.12.37.jar} (javap -c), the same technique used to
 * verify the world-map/minimap member marker overlays - see {@code MinimapLocationOverlay}'s and
 * {@code GroupWorldMapPoints}' doc comments. Worth re-checking against that bytecode if this ever
 * mis-places a ping by a visible amount; it's cosmetic-only (a wrong tile, not a crash) if a RuneLite
 * update shifts the formula.
 */
public final class WorldMapCoordinates {
    /** The world map's map-area widget, {@code group 594 (Worldmap), child 7} - found as the
     * literal RuneLite's own {@code WorldMapOverlay} looks up via {@code getWidget(38993927)}. */
    public static final int WORLD_MAP_VIEW_WIDGET_ID = 38993927;

    private WorldMapCoordinates() {
    }

    /** @return the world point under {@code canvasPoint}, or null if the world map isn't open/ready. */
    public static WorldPoint canvasPointToWorldPoint(Client client, Point canvasPoint) {
        Widget widget = client.getWidget(WORLD_MAP_VIEW_WIDGET_ID);
        if (widget == null) return null;

        float zoom = client.getWorldMap().getWorldMapZoom();
        if (zoom <= 0) return null;

        Rectangle bounds = widget.getBounds();
        int tilesWide = (int) Math.ceil(bounds.getWidth() / zoom);
        int tilesHigh = (int) Math.ceil(bounds.getHeight() / zoom);

        Point mapPosition = client.getWorldMap().getWorldMapPosition();

        int relX = canvasPoint.getX() - bounds.x;
        int relY = canvasPoint.getY() - bounds.y;

        double halfZoomCeil = Math.ceil(zoom / 2.0);
        double xPixels = relX - halfZoomCeil + zoom;
        double yPixels = bounds.getHeight() - relY;
        yPixels = yPixels + zoom + halfZoomCeil;

        double tileOffsetX = xPixels / zoom;
        double tileOffsetY = yPixels / zoom;

        int worldX = (int) Math.round(tileOffsetX - tilesWide / 2 + mapPosition.getX());
        int y9 = mapPosition.getY() - tilesHigh / 2;
        int worldY = (int) Math.round(tileOffsetY + y9 - 1);

        return new WorldPoint(worldX, worldY, client.getPlane());
    }
}

package com.groupscape.sidepanel;

import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Prayer;
import net.runelite.client.game.SpriteManager;

/** Row of real prayer-tab sprites for a member's active prayers, overhead/protection prayers first. */
class ActivePrayerIconsPanel extends JPanel {
    private static final int ICON_SIZE = 16;

    private final SpriteManager spriteManager;
    private List<String> lastRendered = null;

    ActivePrayerIconsPanel(SpriteManager spriteManager) {
        this.spriteManager = spriteManager;
        setLayout(new FlowLayout(FlowLayout.LEFT, 3, 0));
        setOpaque(false);
        setBorder(new EmptyBorder(0, 0, 0, 0));
    }

    void setActivePrayers(List<String> activePrayers) {
        List<String> prayers = activePrayers == null ? List.of() : activePrayers;
        if (prayers.equals(lastRendered)) return;
        lastRendered = new ArrayList<>(prayers);

        removeAll();
        setVisible(!prayers.isEmpty());
        if (prayers.isEmpty()) {
            revalidate();
            repaint();
            return;
        }

        List<String> ordered = new ArrayList<>(prayers);
        ordered.sort(Comparator.comparingInt(name -> isOverhead(name) ? 0 : 1));

        for (String name : ordered) {
            PrayerIcon icon = new PrayerIcon();
            Prayer prayer = PrayerSprites.parse(name);
            Integer spriteId = prayer != null ? PrayerSprites.SPRITE_IDS.get(prayer) : null;
            if (spriteId != null) {
                spriteManager.getSpriteAsync(spriteId, 0, icon::setSprite);
            }
            add(icon);
        }

        revalidate();
        repaint();
    }

    private static boolean isOverhead(String name) {
        Prayer prayer = PrayerSprites.parse(name);
        return prayer != null && PrayerSprites.OVERHEAD.contains(prayer);
    }

    /**
     * A plain {@code JLabel} icon here drew each prayer sprite at its native game resolution
     * (much larger than our 16px row), overflowing/clipping instead of shrinking to fit. Painting
     * it ourselves, scaled uniformly and centered - the same approach the in-game overlay already
     * uses for these same sprites - keeps every icon a clean 16x16 regardless of its source size.
     */
    private static final class PrayerIcon extends JComponent {
        private BufferedImage sprite;

        PrayerIcon() {
            setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
            setOpaque(false);
        }

        void setSprite(BufferedImage sprite) {
            this.sprite = sprite;
            repaint();
        }

        @Override
        protected void paintComponent(Graphics g) {
            if (sprite == null || sprite.getWidth() <= 0 || sprite.getHeight() <= 0) {
                return;
            }
            double scale = Math.min(getWidth() / (double) sprite.getWidth(), getHeight() / (double) sprite.getHeight());
            int drawWidth = (int) Math.round(sprite.getWidth() * scale);
            int drawHeight = (int) Math.round(sprite.getHeight() * scale);
            int x = (getWidth() - drawWidth) / 2;
            int y = (getHeight() - drawHeight) / 2;

            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g2.drawImage(sprite, x, y, drawWidth, drawHeight, this);
            g2.dispose();
        }
    }
}

package com.groupscape.sidepanel;

import com.groupscape.GroupScapeTrackerConfig;
import com.groupscape.roster.ChatState;
import com.groupscape.roster.RosterState;
import java.awt.BorderLayout;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.util.function.Consumer;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JWindow;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.FontManager;

/**
 * The floating chat surface (spec §2's third, opt-in surface) - an always-on-top, draggable
 * window over the game viewport, independent of the chatbox and sidepanel. Reuses {@link
 * ChatPanel} verbatim for the message log/input box, same as {@code GroupScapePanel}'s Chat tab,
 * so the two surfaces stay visually and behaviorally identical.
 *
 * <p>Unlike every other overlay in this plugin (all painted {@code Graphics2D} via RuneLite's
 * {@code OverlayManager}, which owns drag handling itself), this is a genuine {@link JWindow} -
 * there's no way to host an interactive text input inside a painted overlay. Dragging and
 * visibility are handled here directly rather than through {@code OverlayManager}, and the
 * dragged position is persisted via raw {@link ConfigManager} keys rather than a declared {@code
 * @ConfigItem}, since it's not something a user sets from the config panel.
 *
 * <p>Self-contained refresh, matching {@code GroupScapePanel}'s pattern: a {@link Timer} polls
 * {@code chatOverlayEnabled} to show/hide the window and, while visible, re-renders from {@link
 * ChatState}.
 */
public class ChatOverlayWindow extends JWindow {
    private static final int REFRESH_MS = 600;
    private static final String POSITION_X_KEY = "chatOverlayWindowX";
    private static final String POSITION_Y_KEY = "chatOverlayWindowY";
    private static final int DEFAULT_X = 200;
    private static final int DEFAULT_Y = 200;
    private static final int WIDTH = 300;
    private static final int HEIGHT = 380;

    private final GroupScapeTrackerConfig config;
    private final ConfigManager configManager;
    private final ChatState chatState;
    private final ChatPanel chatPanel;
    private final Timer timer;
    private Point dragOrigin;
    private boolean shown = false;

    public ChatOverlayWindow(
            RosterState rosterState,
            ChatState chatState,
            Consumer<String> onSend,
            GroupScapeTrackerConfig config,
            ConfigManager configManager
    ) {
        this.config = config;
        this.configManager = configManager;
        this.chatState = chatState;

        setAlwaysOnTop(true);
        setSize(WIDTH, HEIGHT);
        setLocation(loadPosition());

        JPanel root = new JPanel(new BorderLayout());
        root.setBorder(new MatteBorder(1, 1, 1, 1, SidePanelTheme.BORDER));
        root.add(buildHeader(), BorderLayout.NORTH);

        chatPanel = new ChatPanel(rosterState, onSend);
        root.add(chatPanel, BorderLayout.CENTER);
        setContentPane(root);

        timer = new Timer(REFRESH_MS, e -> tick());
        timer.start();
    }

    private JPanel buildHeader() {
        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(SidePanelTheme.CARD_BG);
        header.setBorder(new EmptyBorder(4, 8, 4, 4));

        JLabel title = new JLabel("GroupScape Chat");
        title.setFont(FontManager.getRunescapeSmallFont());
        title.setForeground(SidePanelTheme.MUTED);
        header.add(title, BorderLayout.WEST);

        JButton close = new JButton("x");
        close.setFont(FontManager.getRunescapeSmallFont());
        close.setForeground(SidePanelTheme.MUTED);
        close.setBackground(SidePanelTheme.CARD_BG);
        close.setBorderPainted(false);
        close.setFocusPainted(false);
        close.setHorizontalAlignment(SwingConstants.CENTER);
        close.addActionListener(e -> configManager.setConfiguration("GroupScapeTracker", "chatOverlayEnabled", false));
        header.add(close, BorderLayout.EAST);

        header.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                dragOrigin = e.getPoint();
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                dragOrigin = null;
                savePosition();
            }
        });
        header.addMouseMotionListener(new MouseMotionAdapter() {
            @Override
            public void mouseDragged(MouseEvent e) {
                if (dragOrigin == null) return;
                Point current = getLocation();
                setLocation(current.x + e.getX() - dragOrigin.x, current.y + e.getY() - dragOrigin.y);
            }
        });

        return header;
    }

    private void tick() {
        boolean enabled = config.chatOverlayEnabled();
        if (enabled != shown) {
            shown = enabled;
            setVisible(enabled);
        }
        if (enabled) {
            // No read-cursor divider here - this window has no unread concept of its own (spec
            // §6 gives it no "missed message" signal either); `0` suppresses `ChatPanel`'s
            // divider entirely, same as the sentinel before `GroupScapePanel`'s first tick.
            chatPanel.refresh(chatState, 0L, 0L);
        }
    }

    private Point loadPosition() {
        Integer x = parseOrNull(configManager.getConfiguration("GroupScapeTracker", POSITION_X_KEY));
        Integer y = parseOrNull(configManager.getConfiguration("GroupScapeTracker", POSITION_Y_KEY));
        return new Point(x != null ? x : DEFAULT_X, y != null ? y : DEFAULT_Y);
    }

    private void savePosition() {
        Point location = getLocation();
        configManager.setConfiguration("GroupScapeTracker", POSITION_X_KEY, location.x);
        configManager.setConfiguration("GroupScapeTracker", POSITION_Y_KEY, location.y);
    }

    private static Integer parseOrNull(String value) {
        if (value == null) return null;
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    public void shutdown() {
        timer.stop();
        dispose();
    }
}

package com.groupscape.sidepanel;

import com.groupscape.roster.ChatState;
import com.groupscape.roster.MemberMapIcons;
import com.groupscape.roster.RosterMember;
import com.groupscape.roster.RosterState;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.event.ActionEvent;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.FontManager;

/**
 * Group chat tab's own view inside {@code GroupScapePanel}: a scrolling message log (card rows -
 * helmet icon tinted to the member's color, name, text) plus an input box, matching the approved
 * side-panel chat mockup (spec §2/§6). Live receive comes from
 * {@code RosterClient.ChatEventListener} appending into {@link ChatState}; {@link #refresh} just
 * re-renders whatever's there now, same poll-a-shared-state pattern as {@link RosterListPanel}.
 */
public class ChatPanel extends JPanel {
    private static final int MAX_LEN = 150;
    private static final int ICON_HEIGHT_PX = 18;
    private static final DateTimeFormatter TIME_FORMAT = DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault());
    /** Matches the webapp chat drawer's {@code --chat-unread-badge} - same red across surfaces. */
    private static final Color UNREAD_DIVIDER = new Color(0xff, 0x4b, 0x4b);

    private final RosterState rosterState;
    private final Consumer<String> onSend;
    private final MemberMapIcons memberIcons = new MemberMapIcons();
    private final JPanel log = new JPanel();
    private final JScrollPane scrollPane;
    private final JTextField input = new JTextField();
    private final JLabel charCount = new JLabel();
    private long lastRenderedMessageId = -1;

    public ChatPanel(RosterState rosterState, Consumer<String> onSend) {
        this.rosterState = rosterState;
        this.onSend = onSend;

        setLayout(new BorderLayout());
        setBackground(SidePanelTheme.SLOT_BG);
        setBorder(new MatteBorder(1, 1, 1, 1, SidePanelTheme.BORDER));

        log.setLayout(new BoxLayout(log, BoxLayout.Y_AXIS));
        log.setOpaque(false);
        log.setBorder(new EmptyBorder(6, 6, 6, 6));

        scrollPane = new JScrollPane(log,
                ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED, ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(null);
        scrollPane.setOpaque(false);
        scrollPane.getViewport().setOpaque(false);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        add(scrollPane, BorderLayout.CENTER);

        add(buildInputArea(), BorderLayout.SOUTH);
    }

    private JPanel buildInputArea() {
        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setOpaque(false);
        wrap.setBorder(new CompoundBorder(new MatteBorder(1, 0, 0, 0, SidePanelTheme.BORDER), new EmptyBorder(4, 6, 6, 6)));

        charCount.setFont(FontManager.getRunescapeSmallFont());
        charCount.setForeground(SidePanelTheme.MUTED_DIM);
        charCount.setHorizontalAlignment(JLabel.RIGHT);
        charCount.setText("0 / " + MAX_LEN);
        wrap.add(charCount, BorderLayout.NORTH);

        JPanel row = new JPanel(new BorderLayout(4, 0));
        row.setOpaque(false);
        row.setBorder(new EmptyBorder(3, 0, 0, 0));

        input.setFont(FontManager.getRunescapeSmallFont());
        input.setBackground(SidePanelTheme.CARD_BG);
        input.setForeground(SidePanelTheme.TEXT);
        input.setCaretColor(SidePanelTheme.TEXT);
        input.setBorder(new CompoundBorder(new MatteBorder(1, 1, 1, 1, SidePanelTheme.BORDER), new EmptyBorder(3, 5, 3, 5)));
        input.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            @Override
            public void insertUpdate(javax.swing.event.DocumentEvent e) {
                enforceLimitAndUpdateCount();
            }

            @Override
            public void removeUpdate(javax.swing.event.DocumentEvent e) {
                updateCount();
            }

            @Override
            public void changedUpdate(javax.swing.event.DocumentEvent e) {
                updateCount();
            }
        });
        input.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ENTER) {
                    doSend();
                }
            }
        });
        row.add(input, BorderLayout.CENTER);

        JButton send = new JButton("Send");
        send.setFont(FontManager.getRunescapeSmallFont());
        send.setForeground(new Color(0x24, 0x13, 0x00));
        send.setBackground(SidePanelTheme.ACCENT);
        send.setFocusPainted(false);
        send.addActionListener((ActionEvent e) -> doSend());
        row.add(send, BorderLayout.EAST);

        wrap.add(row, BorderLayout.CENTER);
        return wrap;
    }

    /** Silent client-side truncation, matching the server's own truncate-not-reject behavior (spec §8). */
    private void enforceLimitAndUpdateCount() {
        SwingUtilities.invokeLater(() -> {
            String text = input.getText();
            if (text.length() > MAX_LEN) {
                input.setText(text.substring(0, MAX_LEN));
            }
            updateCount();
        });
    }

    private void updateCount() {
        charCount.setText(input.getText().length() + " / " + MAX_LEN);
    }

    private void doSend() {
        String text = input.getText().trim();
        if (text.isEmpty()) return;
        onSend.accept(text);
        input.setText("");
    }

    /**
     * Re-renders the log from {@link ChatState} - a no-op rebuild when nothing's new since last
     * call. {@code lastReadMessageId}/{@code newestIdAtOpen} are {@code GroupScapePanel}'s frozen
     * divider snapshot ({@code dividerSnapshotCursor}/{@code dividerSnapshotNewestId}, see
     * {@code updateChatDividerSnapshot}'s doc comment) - bounding the divider search to messages
     * that existed when the Chat tab was last opened means a message that arrives while it's
     * already open (this account's own sent message included) never itself gets flagged unread.
     * Suppressed for a boundary of {@code <= 0} - the sentinel value before the panel's first
     * tick has run, and the "nothing read yet" state where there's no "already read" section to
     * draw a boundary under.
     */
    public void refresh(ChatState chatState, long lastReadMessageId, long newestIdAtOpen) {
        List<ChatState.Entry> messages = chatState.all();
        if (messages.isEmpty()) return;

        long newestId = messages.get(messages.size() - 1).messageId;
        if (newestId == lastRenderedMessageId) return;
        lastRenderedMessageId = newestId;

        boolean wasAtBottom = isScrolledToBottom();

        // Only draws a boundary when there's an actual "already read" section above it (index 0
        // being first-unread would put the divider above everything - same as having none), and
        // only among messages that existed at `newestIdAtOpen` - anything newer arrived during
        // this already-open viewing session and is treated as seen live, never flagged.
        int firstUnreadIndex = -1;
        if (lastReadMessageId > 0) {
            for (int i = 0; i < messages.size(); i++) {
                ChatState.Entry entry = messages.get(i);
                if (entry.messageId > lastReadMessageId && entry.messageId <= newestIdAtOpen) {
                    firstUnreadIndex = i;
                    break;
                }
            }
            if (firstUnreadIndex == 0) firstUnreadIndex = -1;
        }

        log.removeAll();
        for (int i = 0; i < messages.size(); i++) {
            if (i == firstUnreadIndex) {
                log.add(buildUnreadDivider());
                log.add(spacer());
            }
            log.add(buildRow(messages.get(i)));
            log.add(spacer());
        }
        log.revalidate();
        log.repaint();

        if (wasAtBottom) {
            SwingUtilities.invokeLater(this::scrollToBottom);
        }
    }

    private boolean isScrolledToBottom() {
        JScrollBar bar = scrollPane.getVerticalScrollBar();
        return !bar.isVisible() || bar.getValue() + bar.getVisibleAmount() >= bar.getMaximum() - 12;
    }

    private void scrollToBottom() {
        JScrollBar bar = scrollPane.getVerticalScrollBar();
        bar.setValue(bar.getMaximum());
    }

    /** Minimal hairline rule - "NEW" label then a line running out to the panel edge, matching
     * the webapp chat drawer's approved unread-divider design. */
    private JPanel buildUnreadDivider() {
        JPanel row = new JPanel(new BorderLayout(6, 0)) {
            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        row.setOpaque(false);
        row.setAlignmentX(LEFT_ALIGNMENT);

        JLabel label = new JLabel("NEW");
        label.setFont(FontManager.getRunescapeSmallFont().deriveFont(9f));
        label.setForeground(UNREAD_DIVIDER);
        row.add(label, BorderLayout.WEST);

        JPanel line = new JPanel();
        line.setOpaque(true);
        line.setBackground(UNREAD_DIVIDER);
        line.setPreferredSize(new Dimension(1, 1));
        JPanel lineWrap = new JPanel(new BorderLayout());
        lineWrap.setOpaque(false);
        lineWrap.setBorder(new EmptyBorder(label.getFont().getSize() / 2, 0, 0, 0));
        lineWrap.add(line, BorderLayout.CENTER);
        row.add(lineWrap, BorderLayout.CENTER);

        return row;
    }

    private JPanel buildRow(ChatState.Entry entry) {
        String displayName = entry.memberName != null ? entry.memberName : "Unknown";
        RosterMember member = rosterState.findByName(displayName);
        Color color = member != null ? SidePanelTheme.memberColor(member.color) : SidePanelTheme.ACCENT;
        String hex = member != null ? member.color : "#FF981F";

        JPanel row = new JPanel(new BorderLayout(6, 0)) {
            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        row.setOpaque(false);
        row.setAlignmentX(LEFT_ALIGNMENT);

        JLabel icon = new JLabel(new ImageIcon(memberIcons.get(hex, ICON_HEIGHT_PX)));
        JPanel iconWrap = new JPanel(new BorderLayout());
        iconWrap.setOpaque(false);
        iconWrap.add(icon, BorderLayout.NORTH);
        row.add(iconWrap, BorderLayout.WEST);

        JPanel body = new JPanel();
        body.setOpaque(false);
        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));

        JPanel who = new JPanel();
        who.setOpaque(false);
        who.setLayout(new BoxLayout(who, BoxLayout.X_AXIS));
        who.setAlignmentX(LEFT_ALIGNMENT);
        JLabel nameLabel = new JLabel(displayName);
        nameLabel.setFont(FontManager.getRunescapeBoldFont());
        nameLabel.setForeground(color);
        who.add(nameLabel);
        who.add(javax.swing.Box.createHorizontalStrut(6));
        JLabel timeLabel = new JLabel(TIME_FORMAT.format(entry.createdAt));
        timeLabel.setFont(FontManager.getRunescapeSmallFont());
        timeLabel.setForeground(SidePanelTheme.MUTED_DIM);
        who.add(timeLabel);
        body.add(who);

        JLabel textLabel = new JLabel("<html><div style='width:170px'>" + escapeHtml(entry.text) + "</div></html>");
        textLabel.setFont(FontManager.getRunescapeSmallFont());
        textLabel.setForeground(SidePanelTheme.TEXT);
        textLabel.setAlignmentX(LEFT_ALIGNMENT);
        body.add(textLabel);

        row.add(body, BorderLayout.CENTER);
        return row;
    }

    /** Chat text is plain-text-only and stored raw (spec §8) - this panel is the one place it's rendered, so it escapes for its own HTML-label output context here. */
    private static String escapeHtml(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private static JPanel spacer() {
        JPanel panel = new JPanel();
        panel.setOpaque(false);
        panel.setPreferredSize(new Dimension(1, 8));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
        return panel;
    }
}

package com.groupscape.sidepanel;

import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.ui.FontManager;

/**
 * Attack/Defence/Other combat bonus totals, summed directly from each equipped item's
 * {@link ItemEquipmentStats} via {@link ItemManager#getItemStats(int)} - RuneLite's own bundled
 * item-stat cache - rather than the website's server-side item-bonuses dataset
 * (server/src/item_bonuses.rs), so this needs no extra network round trip and works from
 * whatever gear a member's snapshot equipment array reports equipped.
 *
 * <p>{@code getItemStats} falls back to {@code Client#getItemDefinition} on a cache miss, which
 * asserts it's running on the client thread - so the actual lookup+sum runs there via
 * {@link ClientThread#invoke}, with only the resulting label text handed back to the EDT.
 * Calling it straight from {@link #setEquipment} (as this used to) crashed the sidepanel's whole
 * refresh timer the first time an uncached item showed up in someone's gear.
 */
class EquipmentBonusesPanel extends JPanel {
    private final ItemManager itemManager;
    private final ClientThread clientThread;

    private final JLabel attackStab = new JLabel("+0");
    private final JLabel attackSlash = new JLabel("+0");
    private final JLabel attackCrush = new JLabel("+0");
    private final JLabel attackMagic = new JLabel("+0");
    private final JLabel attackRanged = new JLabel("+0");
    private final JLabel defenceStab = new JLabel("+0");
    private final JLabel defenceSlash = new JLabel("+0");
    private final JLabel defenceCrush = new JLabel("+0");
    private final JLabel defenceMagic = new JLabel("+0");
    private final JLabel defenceRanged = new JLabel("+0");
    private final JLabel meleeStrength = new JLabel("+0");
    private final JLabel rangedStrength = new JLabel("+0");
    private final JLabel magicDamage = new JLabel("+0%");
    private final JLabel prayerBonus = new JLabel("+0");
    private final JLabel weaponSpeed = new JLabel("-");
    private final JLabel undeadBonus = new JLabel("+0%");
    private final JLabel slayerBonus = new JLabel("+0%");

    private List<Integer> lastRendered = null;

    EquipmentBonusesPanel(ItemManager itemManager, ClientThread clientThread) {
        this.itemManager = itemManager;
        this.clientThread = clientThread;

        setLayout(new javax.swing.BoxLayout(this, javax.swing.BoxLayout.Y_AXIS));
        setBackground(SidePanelTheme.SLOT_BG);
        setBorder(new CompoundBorder(new LineBorder(SidePanelTheme.BORDER, 1), new EmptyBorder(6, 6, 6, 6)));

        add(heading("Attack bonus"));
        add(grid(
                "Stab", attackStab, "Slash", attackSlash, "Crush", attackCrush,
                "Magic", attackMagic, "Ranged", attackRanged
        ));
        add(heading("Defence bonus"));
        add(grid(
                "Stab", defenceStab, "Slash", defenceSlash, "Crush", defenceCrush,
                "Magic", defenceMagic, "Ranged", defenceRanged
        ));
        add(heading("Other bonuses"));
        add(grid(
                "Melee str", meleeStrength, "Ranged str", rangedStrength,
                "Magic dmg", magicDamage, "Prayer", prayerBonus
        ));
        add(heading("Target-specific"));
        add(grid("Undead", undeadBonus, "Slayer", slayerBonus));
        add(heading("Weapon speed"));
        add(grid("Speed", weaponSpeed));
    }

    private JLabel heading(String text) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(SidePanelTheme.ACCENT);
        label.setBorder(new EmptyBorder(6, 0, 2, 0));
        label.setAlignmentX(LEFT_ALIGNMENT);
        return label;
    }

    private JPanel grid(Object... labelValuePairs) {
        JPanel panel = new JPanel(new GridLayout(labelValuePairs.length / 2, 2, 4, 1));
        panel.setOpaque(false);
        panel.setAlignmentX(LEFT_ALIGNMENT);
        for (int i = 0; i < labelValuePairs.length; i += 2) {
            JLabel key = new JLabel((String) labelValuePairs[i]);
            key.setFont(FontManager.getRunescapeSmallFont());
            key.setForeground(SidePanelTheme.MUTED);
            panel.add(key);

            JLabel value = (JLabel) labelValuePairs[i + 1];
            value.setFont(FontManager.getRunescapeSmallFont());
            value.setForeground(SidePanelTheme.TEXT);
            value.setHorizontalAlignment(SwingConstants.RIGHT);
            panel.add(value);
        }
        return panel;
    }

    void setEquipment(List<Integer> flatIdQuantityPairs) {
        List<Integer> items = flatIdQuantityPairs == null ? List.of() : flatIdQuantityPairs;
        if (items.equals(lastRendered)) return;
        lastRendered = new ArrayList<>(items);
        List<Integer> request = lastRendered;

        clientThread.invoke(() -> {
            Totals totals = computeTotals(request);
            SwingUtilities.invokeLater(() -> {
                if (request == lastRendered) {
                    applyTotals(totals);
                }
            });
        });
    }

    private Totals computeTotals(List<Integer> items) {
        Totals totals = new Totals();
        List<Integer> equippedItemIds = new ArrayList<>();

        for (EquipmentInventorySlot slot : EquipmentInventorySlot.values()) {
            int idIndex = slot.getSlotIdx() * 2;
            int id = idIndex < items.size() ? items.get(idIndex) : 0;
            if (id <= 0) continue;
            equippedItemIds.add(id);

            ItemStats stats = itemManager.getItemStats(id);
            ItemEquipmentStats eq = stats != null ? stats.getEquipment() : null;
            if (eq == null) continue;

            totals.aStab += eq.getAstab();
            totals.aSlash += eq.getAslash();
            totals.aCrush += eq.getAcrush();
            totals.aMagic += eq.getAmagic();
            totals.aRanged += eq.getArange();
            totals.dStab += eq.getDstab();
            totals.dSlash += eq.getDslash();
            totals.dCrush += eq.getDcrush();
            totals.dMagic += eq.getDmagic();
            totals.dRanged += eq.getDrange();
            totals.str += eq.getStr();
            totals.rstr += eq.getRstr();
            totals.prayer += eq.getPrayer();
            totals.mdmg += eq.getMdmg();

            if (slot == EquipmentInventorySlot.WEAPON) {
                totals.speed = eq.getAspeed();
            }
        }

        totals.undeadPercent = TargetBonuses.undeadPercent(equippedItemIds);
        totals.slayerPercent = TargetBonuses.slayerPercent(equippedItemIds);
        return totals;
    }

    private void applyTotals(Totals totals) {
        attackStab.setText(signed(totals.aStab));
        attackSlash.setText(signed(totals.aSlash));
        attackCrush.setText(signed(totals.aCrush));
        attackMagic.setText(signed(totals.aMagic));
        attackRanged.setText(signed(totals.aRanged));
        defenceStab.setText(signed(totals.dStab));
        defenceSlash.setText(signed(totals.dSlash));
        defenceCrush.setText(signed(totals.dCrush));
        defenceMagic.setText(signed(totals.dMagic));
        defenceRanged.setText(signed(totals.dRanged));
        meleeStrength.setText(signed(totals.str));
        rangedStrength.setText(signed(totals.rstr));
        magicDamage.setText(signed((int) Math.round(totals.mdmg)) + "%");
        prayerBonus.setText(signed(totals.prayer));
        weaponSpeed.setText(totals.speed > 0 ? totals.speed + "t" : "-");
        undeadBonus.setText(formatPercent(totals.undeadPercent));
        slayerBonus.setText(formatPercent(totals.slayerPercent));
    }

    private static final class Totals {
        int aStab, aSlash, aCrush, aMagic, aRanged;
        int dStab, dSlash, dCrush, dMagic, dRanged;
        int str, rstr, prayer;
        double mdmg;
        int speed = -1;
        double undeadPercent;
        double slayerPercent;
    }

    private static String formatPercent(double percent) {
        return "+" + (percent == Math.rint(percent) ? String.valueOf((long) percent) : String.valueOf(percent)) + "%";
    }

    private static String signed(int value) {
        return value >= 0 ? "+" + value : String.valueOf(value);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }
}

package com.groupscape.sidepanel;

import java.awt.Dimension;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.swing.JPanel;
import javax.swing.border.LineBorder;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * Fixed paperdoll layout of the 11 equipment slots, positions ported from the website's
 * {@code .equipment-*} CSS (site/src/player-equipment/player-equipment.css) and rescaled to the
 * sidepanel's actual ~170px content width - {@code CardLayout} reports its preferred size as the
 * max across every card it holds, not just the visible one, so a wider-than-necessary doll here
 * was forcing every tab (not just Gear) wider than the sidepanel.
 *
 * <p>Sized and positioned at a fixed pixel scale rather than responsively - {@link
 * EquipmentTabPanel} is responsible for centering this within whatever width is actually
 * available, via a {@code FlowLayout} wrapper rather than this panel guessing at its own bounds.
 */
class EquipmentDollPanel extends JPanel {
    private static final int SLOT_SIZE = 28;

    private final ItemManager itemManager;
    private final ClientThread clientThread;
    private final Map<EquipmentInventorySlot, ItemSlotComponent> slots = new EnumMap<>(EquipmentInventorySlot.class);
    private List<Integer> lastRendered = null;

    EquipmentDollPanel(ItemManager itemManager, ClientThread clientThread) {
        this.itemManager = itemManager;
        this.clientThread = clientThread;
        setLayout(null);
        setOpaque(false);

        addSlot(EquipmentInventorySlot.HEAD, 70, 0);
        addSlot(EquipmentInventorySlot.CAPE, 2, 36);
        addSlot(EquipmentInventorySlot.AMULET, 70, 36);
        addSlot(EquipmentInventorySlot.AMMO, 138, 36);
        addSlot(EquipmentInventorySlot.WEAPON, 2, 72);
        addSlot(EquipmentInventorySlot.BODY, 70, 72);
        addSlot(EquipmentInventorySlot.SHIELD, 138, 72);
        addSlot(EquipmentInventorySlot.LEGS, 70, 108);
        addSlot(EquipmentInventorySlot.GLOVES, 2, 144);
        addSlot(EquipmentInventorySlot.BOOTS, 70, 144);
        addSlot(EquipmentInventorySlot.RING, 138, 144);
        setPreferredSize(new Dimension(170, 176));
        setMinimumSize(new Dimension(170, 176));
    }

    private void addSlot(EquipmentInventorySlot slot, int x, int y) {
        ItemSlotComponent component = new ItemSlotComponent(itemManager, clientThread);
        component.setBounds(x, y, SLOT_SIZE, SLOT_SIZE);
        component.setBackground(SidePanelTheme.SLOT_BG);
        component.setBorder(new LineBorder(SidePanelTheme.BORDER, 1));
        slots.put(slot, component);
        add(component);
    }

    void setEquipment(List<Integer> flatIdQuantityPairs) {
        List<Integer> items = flatIdQuantityPairs == null ? List.of() : flatIdQuantityPairs;
        if (items.equals(lastRendered)) return;
        lastRendered = new ArrayList<>(items);

        for (Map.Entry<EquipmentInventorySlot, ItemSlotComponent> entry : slots.entrySet()) {
            int idIndex = entry.getKey().getSlotIdx() * 2;
            int id = idIndex < items.size() ? items.get(idIndex) : 0;
            int quantity = idIndex + 1 < items.size() ? items.get(idIndex + 1) : 0;
            entry.getValue().setItem(id, quantity);
        }
    }
}

package com.groupscape.sidepanel;

import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/** Equipment tab content: the paperdoll on top, combat bonus totals stacked below it. */
class EquipmentTabPanel extends JPanel {
    private final EquipmentDollPanel dollPanel;
    private final EquipmentBonusesPanel bonusesPanel;

    EquipmentTabPanel(ItemManager itemManager, ClientThread clientThread) {
        this.dollPanel = new EquipmentDollPanel(itemManager, clientThread);
        this.bonusesPanel = new EquipmentBonusesPanel(itemManager, clientThread);

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setOpaque(false);

        // FlowLayout centers a fixed-size child within whatever width it's actually given -
        // BoxLayout's own cross-axis alignmentX centering doesn't reliably kick in here since the
        // doll sits behind a CardLayout that resizes its visible card to fill the container
        // outright rather than respecting the card's reported max size.
        JPanel dollWrapper = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        dollWrapper.setOpaque(false);
        dollWrapper.setAlignmentX(LEFT_ALIGNMENT);
        dollWrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, dollPanel.getPreferredSize().height));
        dollWrapper.add(dollPanel);
        add(dollWrapper);
        add(bonusesPanel);
    }

    void setEquipment(List<Integer> flatIdQuantityPairs) {
        dollPanel.setEquipment(flatIdQuantityPairs);
        bonusesPanel.setEquipment(flatIdQuantityPairs);
    }
}

