/** 3-column grid of skill level boxes plus a total-level row, matching site/src/player-skills. */
class SkillsGridPanel extends JPanel {
    private static final int ICON_SIZE = 14;

    private final SkillIconManager skillIconManager;
    private final JLabel[] levelLabels = new JLabel[SkillOrder.GRID_ORDER.length];
    private final JLabel totalLevelValue;

    SkillsGridPanel(SkillIconManager skillIconManager) {
        this.skillIconManager = skillIconManager;
        setLayout(new BorderLayout(0, 4));
        setOpaque(false);

        JPanel grid = new JPanel(new GridLayout(SkillOrder.GRID_ORDER.length / 3, 3, 1, 1));
        grid.setBackground(SidePanelTheme.SLOT_BG);
        grid.setBorder(new LineBorder(SidePanelTheme.BORDER, 1));

        for (int i = 0; i < SkillOrder.GRID_ORDER.length; i++) {
            Skill skill = SkillOrder.GRID_ORDER[i];
            JPanel box = new JPanel(new BorderLayout(4, 0));
            box.setOpaque(false);
            box.setBorder(new EmptyBorder(1, 6, 1, 6));

            JLabel icon = new JLabel();
            java.awt.image.BufferedImage sprite = skillIconManager.getSkillImage(skill, true);
            if (sprite != null) {
                icon.setIcon(new ImageIcon(sprite.getScaledInstance(ICON_SIZE, ICON_SIZE, java.awt.Image.SCALE_SMOOTH)));
            }
            box.add(icon, BorderLayout.WEST);

            JLabel level = new JLabel("1", SwingConstants.RIGHT);
            level.setFont(FontManager.getRunescapeSmallFont());
            level.setForeground(SidePanelTheme.TEXT);
            levelLabels[i] = level;
            box.add(level, BorderLayout.CENTER);

            grid.add(box);
        }
        add(grid, BorderLayout.CENTER);

        JPanel totalRow = new JPanel(new BorderLayout());
        totalRow.setBackground(SidePanelTheme.SLOT_BG);
        totalRow.setBorder(new CompoundBorder(new LineBorder(SidePanelTheme.BORDER, 1), new EmptyBorder(4, 6, 4, 6)));
        JLabel totalLevelLabel = new JLabel("Total level");
        totalLevelLabel.setFont(FontManager.getRunescapeSmallFont());
        totalLevelLabel.setForeground(SidePanelTheme.MUTED);
        totalLevelValue = new JLabel("0");
        totalLevelValue.setFont(FontManager.getRunescapeBoldFont());
        totalLevelValue.setForeground(SidePanelTheme.ACCENT);
        totalRow.add(totalLevelLabel, BorderLayout.WEST);
        totalRow.add(totalLevelValue, BorderLayout.EAST);
        add(totalRow, BorderLayout.SOUTH);
    }

    void setSkillXp(List<Integer> skillXpBySkillOrder) {
        List<Integer> xp = skillXpBySkillOrder == null ? List.of() : skillXpBySkillOrder;

        int totalLevel = 0;
        for (int i = 0; i < SkillOrder.GRID_ORDER.length; i++) {
            int skillIndex = indexOf(SkillOrder.GRID_ORDER[i]);
            int value = skillIndex >= 0 && skillIndex < xp.size() ? xp.get(skillIndex) : 0;
            int level = value > 0 ? Experience.getLevelForXp(value) : 1;
            levelLabels[i].setText(String.valueOf(level));
            totalLevel += level;
        }
        totalLevelValue.setText(String.format("%,d", totalLevel));
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    private static int indexOf(Skill skill) {
        for (int i = 0; i < SkillOrder.SKILLS.length; i++) {
            if (SkillOrder.SKILLS[i] == skill) return i;
        }
        return -1;
    }
}

package com.groupscape.sidepanel;

import java.util.HashMap;
import java.util.Map;

/**
 * Undead (Salve amulet-style) and Slayer (Black mask/Slayer helmet-style) target bonuses, ported
 * from the website's public/data/target_bonuses.json - not in the wiki's per-item Infobox Bonuses
 * template {@link EquipmentBonusesPanel}'s {@code ItemEquipmentStats} numbers come from, so it's
 * a small hand-curated lookup rather than something derivable from RuneLite's item-stat cache.
 * Each item's percentage is its melee Attack/Strength bonus - imbued variants extend part of that
 * bonus to ranged/magic too, but never above the melee figure, so one flat number per item loses
 * nothing for a single-value display.
 */
final class TargetBonuses {
    private static final Map<Integer, Double> UNDEAD = new HashMap<>();
    private static final Map<Integer, Double> SLAYER = new HashMap<>();

    static {
        UNDEAD.put(4081, 16.67);
        UNDEAD.put(10588, 20.0);
        UNDEAD.put(12017, 16.67);
        UNDEAD.put(25250, 16.67);
        UNDEAD.put(26763, 16.67);
        UNDEAD.put(12018, 20.0);
        UNDEAD.put(25278, 20.0);
        UNDEAD.put(26782, 20.0);

        int[] slayerIds = {
                8901, 8903, 8905, 8907, 8909, 8911, 8913, 8915, 8917, 8919, 8921,
                11774, 11775, 11776, 11777, 11778, 11779, 11780, 11781, 11782, 11783, 11784,
                25266, 25267, 25268, 25269, 25270, 25271, 25272, 25273, 25274, 25275, 25276,
                26771, 26772, 26773, 26774, 26775, 26776, 26777, 26778, 26779, 26780, 26781,
                11864, 11865, 25177, 26674,
        };
        for (int id : slayerIds) {
            SLAYER.put(id, 16.67);
        }
    }

    private TargetBonuses() {
    }

    /** Highest undead bonus among the given equipped item ids, or 0 if none qualify. */
    static double undeadPercent(Iterable<Integer> equippedItemIds) {
        return highest(UNDEAD, equippedItemIds);
    }

    /** Highest slayer bonus among the given equipped item ids, or 0 if none qualify. */
    static double slayerPercent(Iterable<Integer> equippedItemIds) {
        return highest(SLAYER, equippedItemIds);
    }

    private static double highest(Map<Integer, Double> table, Iterable<Integer> equippedItemIds) {
        double best = 0;
        for (int id : equippedItemIds) {
            Double value = table.get(id);
            if (value != null && value > best) {
                best = value;
            }
        }
        return best;
    }
}

package com.groupscape.sidepanel;

import com.groupscape.roster.RosterMember;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * Paints HP/Prayer/Run/Spec bars plus the target bar for one roster member, ported from
 * {@code PartyFrameOverlay#drawBar}/{@code drawTargetBar} but full-width for the sidepanel's
 * ~220px column instead of the overlay's fixed 180px canvas.
 */
class VitalsBarsPanel extends JComponent {
    private static final int ROW_GAP = 2;
    private static final int LABEL_WIDTH = 22;
    private static final int VALUE_WIDTH = 28;

    /**
     * Sized from the font's real metrics rather than a guessed constant - a hardcoded row height
     * shorter than the font's ascent+descent clipped the top pixels off every digit.
     */
    private final int rowHeight;

    private RosterMember member;
    private boolean showHp = true;
    private boolean showPrayer = true;
    private boolean showRun = true;
    private boolean showSpec = true;
    private boolean showTarget = true;

    VitalsBarsPanel() {
        setOpaque(false);
        setFont(FontManager.getRunescapeSmallFont());
        rowHeight = getFontMetrics(getFont()).getHeight() + 2;
    }

    void setMember(RosterMember member) {
        this.member = member;
        repaint();
    }

    /** Config-driven per-bar visibility - hidden bars neither render nor take up row height. */
    void setVisibleBars(boolean hp, boolean prayer, boolean run, boolean spec, boolean target) {
        this.showHp = hp;
        this.showPrayer = prayer;
        this.showRun = run;
        this.showSpec = spec;
        this.showTarget = target;
        revalidate();
        repaint();
    }

    @Override
    public Dimension getPreferredSize() {
        int rows = visibleRowCount();
        int height = rows == 0 ? 0 : rows * rowHeight + (rows - 1) * ROW_GAP;
        return new Dimension(200, height);
    }

    private int visibleRowCount() {
        int rows = 0;
        if (showHp) rows++;
        if (showPrayer) rows++;
        if (showRun) rows++;
        if (showSpec) rows++;
        if (showTarget) rows++;
        return rows;
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setFont(getFont());

        int width = getWidth();
        int y = 0;

        if (member == null) {
            g2.dispose();
            return;
        }

        if (showHp) y = drawBar(g2, y, width, "HP", member.hp, member.maxHp, SidePanelTheme.HP);
        if (showPrayer) y = drawBar(g2, y, width, "Pr", member.prayer, member.maxPrayer, SidePanelTheme.PRAYER);
        if (showRun) y = drawBar(g2, y, width, "Run", member.runEnergy, 100, SidePanelTheme.RUN);
        if (showSpec) y = drawBar(g2, y, width, "Sp", member.specEnergy, 100, SidePanelTheme.SPEC);
        if (showTarget) drawTargetBar(g2, y, width);

        g2.dispose();
    }

    private int drawBar(Graphics2D g2, int y, int width, String label, Integer value, Integer max, Color color) {
        FontMetrics metrics = g2.getFontMetrics();
        int textY = y + (rowHeight + metrics.getAscent()) / 2 - 1;

        g2.setColor(SidePanelTheme.MUTED);
        g2.drawString(label, 0, textY);

        int barX = LABEL_WIDTH;
        int barWidth = Math.max(0, width - LABEL_WIDTH - VALUE_WIDTH);

        g2.setColor(SidePanelTheme.TRACK);
        g2.fillRoundRect(barX, y + 1, barWidth, rowHeight - 2, 2, 2);

        String valueText;
        if (value != null && max != null && max > 0) {
            int clamped = Math.max(0, Math.min(value, max));
            int filled = (int) ((clamped / (double) max) * barWidth);
            g2.setColor(color);
            g2.fillRoundRect(barX, y + 1, filled, rowHeight - 2, 2, 2);
            valueText = String.valueOf(clamped);
        } else {
            valueText = "--";
        }

        g2.setColor(SidePanelTheme.TEXT);
        g2.drawString(valueText, barX + barWidth + 4, textY);

        return y + rowHeight + ROW_GAP;
    }

    private void drawTargetBar(Graphics2D g2, int y, int width) {
        FontMetrics metrics = g2.getFontMetrics();
        int textY = y + (rowHeight + metrics.getAscent()) / 2 - 1;

        String targetName = member.targetName;
        boolean isEnemy = member.targetHealthScale != null && member.targetHealthScale > 0;
        boolean hasRatio = isEnemy && member.targetHealthRatio != null && member.targetHealthRatio >= 0;

        Color fill = isEnemy ? SidePanelTheme.TARGET_COMBAT_FILL : SidePanelTheme.TARGET_NEUTRAL_FILL;
        Color track = isEnemy ? SidePanelTheme.TARGET_COMBAT_TRACK : SidePanelTheme.TARGET_NEUTRAL_TRACK;

        g2.setColor(SidePanelTheme.MUTED);
        g2.drawString("Tgt", 0, textY);

        int barX = LABEL_WIDTH;
        int barWidth = Math.max(0, width - LABEL_WIDTH - VALUE_WIDTH);

        if (targetName == null || targetName.isEmpty()) {
            g2.setColor(SidePanelTheme.TRACK);
            g2.fillRoundRect(barX, y + 1, barWidth, rowHeight - 2, 2, 2);
            g2.setColor(SidePanelTheme.MUTED);
            g2.drawString("--", barX + barWidth + 4, textY);
            return;
        }

        g2.setColor(track);
        g2.fillRoundRect(barX, y + 1, barWidth, rowHeight - 2, 2, 2);

        double ratio = hasRatio ? Math.max(0, Math.min(1.0, member.targetHealthRatio / (double) member.targetHealthScale)) : 1.0;
        int filled = (int) Math.round(barWidth * ratio);
        g2.setColor(fill);
        g2.fillRoundRect(barX, y + 1, filled, rowHeight - 2, 2, 2);

        g2.setColor(SidePanelTheme.TEXT);
        String name = truncateToWidth(metrics, targetName, Math.max(0, barWidth - 6));
        g2.drawString(name, barX + 3, textY);

        if (hasRatio) {
            g2.setColor(SidePanelTheme.MUTED);
            g2.drawString(Math.round(ratio * 100) + "%", barX + barWidth + 4, textY);
        }
    }

    private static String truncateToWidth(FontMetrics metrics, String text, int maxWidth) {
        if (metrics.stringWidth(text) <= maxWidth) return text;

        String ellipsis = "...";
        int ellipsisWidth = metrics.stringWidth(ellipsis);
        if (maxWidth <= ellipsisWidth) return "";

        StringBuilder truncated = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            truncated.append(text.charAt(i));
            if (metrics.stringWidth(truncated.toString()) + ellipsisWidth > maxWidth) {
                truncated.setLength(truncated.length() - 1);
                break;
            }
        }
        return truncated + ellipsis;
    }
}

